INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (12454,3,1,'နှစ်ဆယ့်ရှစ်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(12455,3,1,'အဘိုး။ အမိ (သို့မဟုတ်) အဖ၏ဖခင်။','‘လဇု’ (န) လည်းရှု။')
,(12456,3,1,'နှစ်ခုအနက်ရွေးစရာ။ တစ်ခြားရွေးစရာ။ (an alternative)','‘မွဲလကာ’ (သဗဓ) လည်းရှု။')
,(12457,3,4,'တွဲလောင်းကျသည်။ တွဲလျားဆွဲသည်။','“မဗလတ် သတ်လကဲ။” = “အစေ့ငေါထွက်၍ အသီးတွဲလောင်းကျသည်။” (သီဟိုဠ်သီးကို ဆိုလိုသော မွန်စကားထာ) || “(သၟိၚ်ထၚ်ဍာ်လောန် အေၚ်ဒုၚ်ဟွံမာန်တုဲ) စိၚ်ဂှ် စွံလဝ်သၟန်ကမၠိုၚ်တုဲ ဇုက်ဂှ် ဒက်စုတ်ပ္ဍဲဇိုၚ်စိၚ်တုဲ သၟိၚ်လကဲစှ်ေရ။” (ဇ—၂၅၉။ အစွောံ။) = “မင်းသည် ရေငတ်လွန်း၍ သည်းမခံနိုင်ဘဲ ဆင်ကို ရေတွင်းနား­ထား၍ ထိုဆင်၏ခြေ­ ကြိုးကိုဖွဲ့၍ ရေတွင်းသို့ တွဲလောင်းဆင်း၏။” || “ဗောဓိသတ် (သၟိၚ်ၜိုပ်ထဝ်) ဒးဓနက် မၞုံက္ဍိုပ်လကဲမံၚ်ဂှ်—။” (ဇ—၅ဝ၂။ အစွောံ။) = “ဘုရားလောင်း (ရွှေဟင်္သာမင်း) သည် လှံတံကျော့ကွင်း­ ဖွဲ့မိ၍ လှံတံကျော့ကွင်း­ (ဦးခေါင်း) တွဲလျားဆွဲလျက်—။” (ညောင်ကန်)')
,(12458,3,1,'၁။ ရင်ကမ်းသီး။',NULL)
,(12458,3,1,'၂။ ရှားပင်။','‘ကြက်လကံ’ ရှု။')
,(12459,3,1,'၁။ ကွင်း။ ကကြိုး။',NULL)
,(12459,3,1,'၂။ လက်ကောက်။','“သၞေက်မၞိက်၊ ပ္ကဴထဝ်၊ လစိန်စရံက်၊ လကံက်ထဝ်၊—။” (ဇ—၂၈၉။ အစွောံ။) = “ပတ္တမြားနားဍောင်း၊ ဦးခေါင်းတန်ဆာရွှေပန်း၊ ဝတ်စရာလက်စွပ်၊ ရွှေလက်ကောက်—။”')
,(12460,3,1,'စွပ်တပ်စရာအပေါက်။ စရွေးပေါက်။','‘စရုဲ’ (န) လည်းရှု။')
,(12461,3,1,'ခြေကျင်း။',NULL)
,(12462,3,1,'လက်ကောက်။',NULL)
,(12463,3,4,'ကြေမွသည်။ မှုန့်မှုန့်ညက်ညက်ကြေသည်။','“(ကၠဵုဂြိုပ်ဂှ်) ပ္ဍဲဇိုၚ်စိၚ်ဟေၚ်ဒတုံစှ်ေ စိၚ်ပၚ်ဇိုၚ်တုဲ ဇေဟ်စုတ်က္ဍိုပ်ကၠဵုရ။ ဇုတ်က္ဍိုပ်လကောတ်အာ—။” (ဇ—၁၄၃။ အစွောံ။) =“မြေခွေးသည် ဆင်ခြေ­ကျသည်ရှိသော် ဆင်ကခြေကိုပင့်၍ မြေခွေးဦးခေါင်းကို ဆောင့်နင်းလိုက်ရာ မြေခွေး၏ဦးခေါင်းရိုးသည် မှုန့်မှုန့်ညက်ညက်ကြေသွား၏။”')
,(12463,3,1,'၁။ အမှုန့်။','“ဗြဲလကောတ်စလန်ဒိပ်ဗဂူဖျိဟ်။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “နတ်နံ့သာမှုန့်မိုးရွာချ၏။” || ‘ကြကောတ်’ (ကြိ/န) နှင့်အတူတူ။')
,(12463,3,1,'၂။ အနည်။ အနည်အနှစ်။','“(မိၚ်ဂလာန်ဗတာဲဂှ်တုဲ) ဂကောံသတ်ဇိုၚ်ပန်ဂမၠိုၚ် လကိုတ်တုဲ ဒြေပ်ဒဴအာအိုတ်ရ။” (ဇ—၃၂၂။ အစွောံ။) = “ထိုယုန်၏စကားကိုကြား၍ အခြေလေးချောင်းရှိသောသတ္တဝါအပေါင်းတို့သည် လန့်၍ထွက်ပြေးကြကုန်၏။”')
,(12465,3,4,'(အိပ်ပျော်နေရာမှ) လန့်နိုးသည်။','“မှာလီသြၚ်တုန် ပ္ဍဲပယာံပထမအရှိုန်မတိုန်ဂှ် လကိုတ်ၚုဟ်တုဲ ရံၚ်ၚဳမွဲသၟန်နက်သတ်။” (ဇ—၂။ အစွောံ။) = “ကြည်းကြောင်းခရီးလမ်းပြသည် အရုဏ်တက်သောအခါ လန့်နိုး၍ နက္ခတ်ကိုကြည့်၏။”')
,(12466,3,4,'ထိတ်လန့်သည်။ စိတ်တုန်လှုပ်သည်။','“သေဋ္ဌဳမိၚ်ဂလာန်ဂှ် လကိုတ်တိုန်စိုတ်—။” (ဇ—၇၈။ အစွောံ။) = “ထိုဣလ္လိသသူဋ္ဌေးသည် အသံကိုကြား၍ ကြောက်လန့်သည်ဖြစ်၍—။” (ညောင်ကန်) || “အဲဖေက်ဗှ်ေ အဲလကိုတ်အာစိုတ်တုဲရ။” (ဇ—၃၆၅။ အစွောံ။) =“သင့်ကိုငါကြောက်၍ ငါထိတ်လန့်သွားလေပြီ။” || “ဖေက်လကိုတ်စိုတ်တုဲ ကောန်သၟိၚ်ဒြေပ်ဒဴအာကၠေံရ။” (ဇ—၃၇၃။ အစွောံ။) = “မင်းသားသည် ကြောက်လန့်၍ ထွက်ပြေးသွား၏။”')
,(12467,3,4,'သွေးလန့်သည်။ ရုတ်တရက် ကြောက်ရွံ့တုန်လှုပ်သည်။',NULL)
,(12468,3,4,'လန့်ဖျတ်သည်။',NULL)
,(12469,3,4,'မကောင်းမှုပြုရမည်ကို ကြောက်တတ်သည်။','‘ဖေက်ပါပ်’ နှင့်အတူတူ။')
,(12470,3,4,'သံသရာဘေးမှ ကြောက်ရွံ့ထိတ်လန့်သည်။',NULL)
,(12471,3,1,'ခြေသန်း။','“ကဵုလကေန်ဇိုၚ်၊ ေၚပ်ဂိုၚ်ကေတ်ဏာ။” (လိက်ဇိဝှစက္က) = “ခြေသန်းဖြင့်ညှပ်၍ သုတ်ချီယူသွား၏။”')
,(12472,3,1,'လက်သန်း။',NULL)
,(12473,3,1,'ကြာစွယ်။ ကြာမြစ်မှထွက်သောအတက်၊ အစို့အညှောက်။','“တြုံမွဲဂှ် ဍေံစှ်ေဂၠံက်စလကိုန်တုဲ ဍေံၜဟ်ဏာပ္ကဴဒကှ်။” (ဇ—၃၉၂။ အစွောံ။) = “တစ်ယောက်သောယောကျာ်းသည်ထိုအိုၚ်­ ကြာစွယ်တို့ကိုလည်း တူး၏။ ပုဏ္ဍရိတ်တို့ကိုလည်း ချိုး၏။” (ညောင်ကန်) || “ကာမဂုန်မသုန်ပြကာဂှ် ထောံကၠေံတုဲ တိတ်ပဂမှဳတုဲဂှ် ဆဗၞတ်လကိုန်ညိကီုဂှ် မဒးကၠတ်စဍေံဂှ် ဟွံဂပ်ဂဝ်သွံ။” (ဇ—၄၈၈။ အစွောံ။) = “ကာမတို့ကိုစွန့်၍ ရဟန်းပြုကုန်သောသူတို့အား ကြာစွယ်မျှကို (ခိုး) ယူခြင်းငှာ မလျောက်ပတ်။” (ညောင်ကန်) || လဝါလကိုန် = ကြာစွယ်ကြာရင်း။')
,(12474,3,12,'(န) ဘီလူး။','“လကိုဟ်လုပ်ကၠုၚ်ဍုၚ်ရောၚ်သွံ။” (ဇ—၄၆၉။ အစွောံ။) =“မြို့ကို ဘီလူးဝၚ်စီးသည်တကား။”')
,(12475,3,1,'ကျွန်း။','‘တ္ကအ်’ ရှု။')
,(12476,3,1,'ဘုန်းကြီး။ ရဟန်း။','ဘာလကျာ် = ဘုန်းကြီးကျောင်း။')
,(12477,3,1,'ဘုန်းကြီးလူထွက်။',NULL)
,(12478,3,1,'လျှို။ ချိုင့်ဝှမ်း။ (?)','“ထောံလှာဆဵုလ္ဂောဝ်၊ ထောံလ္ဂောဝ်ဆဵုလ္ဂာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အိုင်ကိုစွန့်ခွာပြီး တောင်မြောင်ကိုတွေ့၏၊ တောင်မြောင်ကိုစွန့်ခွာပြီး ချိုင့်ဝှမ်းကိုတွေ့၏။”')
,(12479,3,4,'၁။ ဖြောင့်မတ်သည်။ တည့်မတ်သည်။','“ညံၚ်လတာ်သၠဒကေဝ် မဒတဴလ္ဂူဒၟံၚ်အကြာဝတ္ထုၜါမတုပ်ကီု စိုတ်ဒ္ဂူဒၟံၚ်အကြာညးၜါ—။” (ဇ—၇၈။ အစွောံ။) = “ချိန်ခွင်လျှာသည်ဝတ္ထုနှစ်ခုတို့အကြား­ တည့်မတ်စွာတည်သကဲ့သို့ နှစ်ဖက်သောသူအကြား­ စိတ်ဖြောင့်မှန်နေ၏။”')
,(12479,3,4,'၂။ သစ္စာစောင့်သိသည်။','“ဗြဴမၞုံစိုတ်လ္ဂူကဵုတၠသ္ၚိဂှ်လေဝ် သ္ဇိုၚ်သ္ဂောအ်သန်။” (ဇ—၅၁၉။အစွောံ။) = “လၚ်­သစ္စာရှိသောမိန်းမကိုလည်း ရခဲ၏။” || ‘ဍိက်မလ္ဂူကဵုတၠ။’ (အကြီုရာဇာဓိရာဇ်) = ‘သခင်­သစ္စာစောင့်သိသောကျွန်။’')
,(12479,3,4,'၃။ ရှေးရှုသည်။ မျက်နှာမူသည်။','“သၟိၚ်စိုပ်လ္ဂူကဵုတၞံဇြဲသုံဂှ် လုပ်အာသၟဝ်ဇြဲဂှ်ရ။” = “ဘုရင်သည် ပညောင်ပင်နှင့် ရှေးရှုရာသို့ရောက်၍ ထိုပညောင်ပင်အောက်သို့ ဝင်သွား၏။” || “ယွံမရာတ်၊ ညးခမဳတံဝွံ ညးဟၟဲကဵုကိလေသတဏှာ ညးမၞုံတြဴမလ္ဂူကဵုစဴနိဗ္ဗာန်ရောၚ်။” (ဇ—၃၉၁။ အစွောံ။) = “မင်းမြတ်၊ ကိလေသာတဏှာကင်းကုန်သော ရဟန်းတို့သည် နိဗ္ဗာန်သို့ ရှေးရှုသောခရီးရှိကုန်၏။”')
,(12479,3,4,'၄။ ကူညီသည်။ စောၚ်မသည်။','“ဒေဝတဴတံ မလဂူမၚ်မွဲမံၚ် သတ်တၠကုသဵု။” (အကြီုရာဇာဓိရာဇ်) = “နတ်တို့သည် ကုသိုလ်ရှင်အား စောင့်မစောင့်ရှောက်နေကုန်၏။” || ‘ဒဂူ’ လည်းရှု။')
,(12480,3,4,'ဖြောင့်သောစိတ်ထားသည်။ ကြည်ညိုသဒ္ဓါပွားသည်။','“ယွံမဒ္ဒဳ၊ — (ဗမၞးမွဲ) အာတ်ဏာကောန်ၜါ အဲဒးကဵုဒါန်ကဵုဗမၞးတုဲရ။ ဂၞကျာ်လဂူစိုတ်ပ္ဍဲဒါန်ရ” သၟိၚ်ဝေသန္တဝ်ဂး။ (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အဘယ်မဒ္ဒီ၊ တစ်ယောက်သောပုဏ္ဏားသည် ငါတို့သားသမီးနှစ်ယောက်ကိုတောင်း၍ ငါပေးလှူလိုက်ပြီးပြီ။ သင်သည် ကြည်ညိုသဒ္ဓါစိတ်ပွားလော့” ဟုဝေဿန္တရာမင်းဆို၏။')
,(12481,3,4,'ဖြောင့်မှန်သည်။','‘ဒဂူစၟတ်’ ရှု။')
,(12482,3,4,'ဖြောင့်မတ်သည်။ ဖြောင့်မှန်သည်။ ရိုးသားသည်။','“အဲဍိက်ပဟိုတ်သစာနာဲ ဟွံဂွံဝေၚ်ဒစေၚ် လ္ဂူတၚ်ဂှ်ရ နာဲအဲဍိက်ခုတ်ယၟုအမာတ်ဒိန်။” (အကြီုရာဇာဓိရာဇ်) =“ကျွန်တော်မျိုးသည် သခင့်သစ္စာကို မတိမ်းမစောင်း ဖြောင့်မှန်စွာစောင့်သိသောကြောင့် သခင်သည် ကျွန်တော်မျိုးအား အမတ်ဒိန်ဟုအမည်ပေး၏။” || “ယွံဂမှဳတအ်၊ မဇၟအ်ပညာ။ — သၠောမ်ပံၚ်သကူ၊ ဒေပ်စိုတ်လ္ဂူသ္တၚ်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ပညာကြီးကုန်သော ပံ့သကူသင်္ကန်းကိုဝတ်ရုံ၍ ဖြောင့်မှန်သောစိတ်ရှိကုန်သော အိုရဟန်းတို့—။”')
,(12483,3,4,'သစ္စာစောင့်သိသည်။ ကျိန်ဆိုထားသောသစ္စာ­ မှန်ကန်စွာတည်သည်။',NULL)
,(12484,3,5,'ရိုးရိုးသားသား။ ဖြောင့်မတ်စွာ။ တည့်မတ်စွာ။','“ဗမာဒဴလၟုဟ်ဝွံ လ္ဂူလ္ဂူရဟာ။ လ္ၚဵုဒဴ လ္ၚဵုအောပ်ဗဒး ကၞပ်ဒၟံၚ်ဂှ်ရောဟွံတီ။” (အကြီုကမြဴလွဳရာဇာဓိရာဇ်) = “ယခုဗမာတို့ဆုတ်ခွာသည်မှာ ရိုးရိုးသားသားပၚ်လော။ အချို့ပြေး၍ အချို့ပုန်းခိုအောင်းနေလေသလောမသိ။”')
,(12485,3,3,'ရိုးသားဖြောင့်မတ်သော။',NULL)
,(12486,3,4,'စောင့်ရှောက်သည်။ စောၚ်မသည်။','“သြဝ်ကဵုဒေဝတဴတံညးဂမၠိုၚ် ဗိုၚ်လ္ဂူသၞေဝ်တုဲ ကဵုကောန်သ္ဍိုက်အဲ ဂွံကလေၚ်စဴကဵုယာဲညိရ။” (ဇ—၅၁၃။ အစွောံ) = “နတ်ဒေဝါအပေါင်းတို့ စောင့်ရှောက်စောၚ်မသည်ဖြစ်၍ ငါ၏ချစ်သားသည် အမေ့ဆီပြန်လာရပါစေသတည်း။” || “အိုတ်ကဵုဒေဝတဴတံညးဂမၠိုၚ် ဗိုၚ်သ္ဂူသဏေဝ်တုဲ ထ္ၜးကဵုတၠသ္ၚိအဲညိရအဴ”ဂးတုဲ သမ္ဘူလာကောန်သၟိၚ်ဂှ် ယာံတဴရ။ (ဇ—၅၁၉။ အစွောံ။) = “အားလုံးသောနတ်အပေါင်းတို့သည် စောင့်ရှောက်စောၚ်မ၍ အကျွန်ုပ်၏လၚ်အား ပြပေးကြပါကုန်လော့” ဟုဆို၍ သမ္ဘူလမိဖုယားသည် ငိုကြွေး၏။ || ‘ဒ္ဂူသၞေဝ်’ (ကြိ) နှင့်အတူတူ။')
,(12487,3,4,'ကန့်လန့်ဖြတ်တည်ရှိသည်။—ထားသည်။','“ကာလတောံပုၚ် လ္ပလဂုၚ်ဂၞော်။” (သၚ်္ခါရလိုက်) = “ထမင်းချက်သောအခါ ယောက်မကို ထမင်းအိုးပေါ် ကန့်လန့်မထားပါနှင့်။”')
,(12488,3,4,'ဖီလာကန့်လန့်လုပ်သည်။ ဆန့်ကျင်ဘက်လုပ်သည်။ ကာဆီးသည်။','“ခါရတၠညးရာဇာဓိရာဇ် ဒပ်ဇၞော်သဗက်အာ — ဒဵုစိုပ်တြၚ်ဍုၚ်အၚ်ဝ ညးမွဲသ္ဂံၚ်ဒုၚ်လဂုၚ်လၞၚ်ဟွံမွဲရ။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်ရာဇာဓိရာဇ်က တပ်ကြီးချီလိုက်သွားရာ အင်းဝမြို့တံခါးသို့ ရောက်သည့်တိုင်အောင် ဖီလာဆန့်ကျင် ကာဆီးဝံ့သူဟူ၍မရှိ။”')
,(12489,3,4,'အချင်းများသည်။ ငြင်းခုံသည်။','“(ညးဍုၚ်ကဵုညးရးတံဂှ်) ဟီုပၠန်ဂတးကုရၚ်သ္ကံ ဗဗွဲလၟေၚ် လ္ဂုၚ်ဝါတ်ဂါတ်သွေက်ဇဵုဇၞော်အာရ။” (ဇ—၄၉။ အစွောံ။) =“မြို့သားနှင့်တောသားတို့သည် အပြန်အလှန် ပြောဆိုကြကုန်သည်ရှိသော် အစဉ်သဖြင့် အချင်းများ၍ ငြင်းခုံခိုက်ရန်သည် ကြီးထွားလာ၏။”')
,(12490,3,1,'ပြဇာတ်။ ပွဲပြဇာတ်။','“ဖံမံၚ်လဒု၊ ဗရုနာနာ။ စံၚ်ဂြောဝ်သေဲကျာံ၊ ရာဂံါခရာ။လလောၚ်ပြာထာ၊ ညံၚ်တာဝတိၚ်။ ပယျာံတ္ၚဲသဝ်၊ ဖံထဝ်ဂမြိၚ်။ လ္ဂန်တဆိၚ်၊ ဂမြိၚ်ဟောဂြာ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ညနေအချိန်­ ပြဇာတ်အငြိမ့်အကတို့နှင့်အတူ အိုးစည်ဒိုးပတ်အစရှိသော တူရိယာအမျိုးမျိုးတို့၏အသံများဖြင့် ခြိမ့်ခြိမ့်သဲရှိသည်မှာ တာဝၚ်္တံသာနတ် ပြည်တမျှဖြစ်၏။” || “လက်ပၠုဲလက်ဗန်၊ လဂန်လဆိၚ်။” (လိက်တပူတဗဝ်။ အစွောံ။) =“လက်ဝှေ့ပွဲ၊ နပန်းပွဲ၊ ပြဇာတ်ပွဲနှင့် အငြိမ့်ပွဲများ။” || “ပေဲါဇာတ်လဂန်၊ မန်ဗမာကၠုၚ်။” (လိက်မိဍောၚ်ကှ်ေထဝ်) = “ဇာတ်ပွဲပြဇာတ်သို့ မွန်ဗမာများလာကြ၏။” || “ဝေၚ်သဘၚ်ပၠန်၊ လဂန်ဂလာ။” (လိက်ဇိဝှစက္က) = “ကုလားပြဇာတ်ပွဲနှင့် ပွဲသဘင်စကားသည်။”')
,(12491,3,1,'ခြေလှမ်း။','“မွဲတ္ၚဲမွဲလဂံါ၊ ဗုကာံအာစိုပ်မာန်။” = “တစ်နေ့တစ်လံ ပုဂံဘယ်ပြေး။')
,(12492,3,1,'လှမ်းပုံလျှောက်ပုံ။ လှမ်းဟန်လျှောက်ဟန်။','“သၟတ်ဗြဴဝုတ်ဂှ် မၞုံကဵုလဂံါတဝါ်မဆာဲရ။” = “ထိုမိန်းမပျိုသည် တင့်တယ်စမ္ပယ်သော လှမ်းဟန်လျှောက်ဟန်ရှိသည်။” || “(ချေံမ္ၚဵုဂှ်) ညံၚ်လဂံါတွာ်ဍေံတြေံကၠာတေံ ဍေံထောံကၠေံတုဲ ညံၚ်လဂံါတွာ်ဂမာချေံတၠညးခ္ဍဴဟေၚ် ဍေံကွာ်ခ္ဍဴအာရောၚ်အဴ။” (ဇ—၁၈၄။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ မင်္ဂလာမြင်းတော်သည် မိမိ၏ယခင်မူလလှမ်းပုံလျှောက်ပုံကိုစွန့်၍ အရှင်မင်းကြီး၏ ခြေခွင်သောမြင်းထိန်း၏ လှမ်းပုံလျှောက်ပုံကို အတုလိုက်၍ ခြေခွင်သွားခြင်းဖြစ်၏။”')
,(12493,3,1,'တောအုပ်ငယ်။ တောတန်းကလေး။','“ဇၞတ်ဇၞတ်မအာ၊ ကြာဂြိုပ်လဂီု။” (လိက်သောဝါနနဟောၚ်) = “တောအုပ်ကြီးတောအုပ်ငယ်အကြား သွားရင်းသွားရင်း သွားသည်ရှိသော်။” || “အကြာဂြိုပ်ဇီု၊ လဂီုဇိုၚ်ဝါ။” (လိက်ပဒုမဝတဳ) = “ကွင်းပြၚ်အနီးတောတန်းကလေးနှင့် ရေလွှမ်းဒေသရွှံ့ညွန်တောအကြား­။”')
,(12494,3,1,'ဂျင်း။',NULL)
,(12495,3,1,'၁။ စမ်းချောင်း။ ချောင်းငယ်။','ဍာ်လဂေါဝ် = စမ်းရေ။ || “ဂၞကျာ်အာဂၠာဲသတ်ဆု (ပ္ဍဲဂြိုပ်) ဂှ်ဂွံတုဲ ကာလကလေၚ်စဴဂှ် ဆဵုဒးလဂေါဝ်မွဲ (ဂှ်တုဲ) — စှ်ေဟုံဍာ်ရ။” (ဇ—၅၁၉။ အစွောံ။) = “တော­ သစ်သီးကြီးငယ်တို့ကို ဆောင်သည်ရှိသော် တခုသောချောင်းငယ်ကိုမြင်၍ (ရေဆင်းချိုး၏။)” (ညောင်ကန်)')
,(12495,3,1,'၂။ တောင်မြောင်။ ချောက်။ ချိုင့်ဝှမ်း။ (ကုန်းမြင့်နှစ်ခုအကြားအလျားရှည်၍ အနံကျဉ်းသောချိုင့်ဝှမ်း။)','“ဗောဓိသတ်ဒှ်ပြေၚ် ပ္ဍဲဂြိုပ်ဟေမဝန် ဒှ်ဗၠာဲတုဲ ဇကုဇၞော်ထတ်စောံလောန် ပ္ဍဲဇရေၚ်လဂေါဝ်ဇိုၚ်တၟံ တဍတ်ဂြိုပ်မွဲဂှ် ဂ္ၚေၚ်စတုဲ—။” (ဇ—၂၇၈။ အစွောံ။) = “ဘုရားလောင်းသည် ဟိမဝန္တာအရပ်ဝယ် ကျွဲမျိုး­ဖြစ်၍ အရွယ်သို့ရောက်လတ်သော်အားနှင့်ပြည့်စုံ၏။ ကြီးသောကိုယ်ရှိ၏။ တောင်ခြေရင်း ချိုင့်ဝှမ်းရာ ခဲယဉ်းသောတောအုပ်တို့­ကျက်စားလျက်လှည့်လည်သော်—။” (ညောင်ကန်) || “ပ္ဍဲမကလေၚ်ကၠုၚ်ဂှ် (သၟိၚ်) ညာတ်လဂေါဝ်မွဲပ္ဍဲဋ္ဌာန်မညန်ကဵုကွာန်ဒမၠဂှ်ရ။” (ဇ—၅ဝ၃။ အစွောံ။) = “(မင်းသည်) ပြန်လတ်သော် ခိုးသူရွာအနီး­ — တောင်မြောင်ချောက်ကြားကိုမြင်၍—။” (ညောင်ကန်)')
,(12496,3,1,'တောင်မြောင်။ တောင်ချောက်။ (ပါဠိ—ပဗ္ဗတကန္ဒရ)','“(ဗောဓိသတ်သၟိၚ်ဖရာပ်) ဂ္ၚေၚ်တဴပ္ဍဲဇရေၚ်အဿမာပိုတ်ဂှ်တုဲ ပ္ဍဲဇရေၚ်လဂေါဝ်တၟံမွဲဂှ် ဂ္ၚေၚ်ဂၠာဲစတုဲ စဴအာဋ္ဌာန်ဒၟံၚ်ဇကုရ။” (ဇ—၂၇၇။ အစွောံ။) = “(ဘုရားလောင်းခိုမင်းသည်) ကျောင်း­ကျက်စား၍ တောင်မြောင်ချောက်ကြား၏အနီး­ အစာယူ၍ ညအခါ မိမိနေရာသို့သွား၏။” (ညောင်ကန်) || “ကလေၚ်စဴစိုပ်ဒေါဝ်တြဴ — ဆဵုလ္ဂောဝ်တၟံမွဲတုဲ—။” (ဇ—၃၅၆။ အစွောံ။) = “ပြန်လတ်သော် လမ်းအကြား­ တစ်ခုသောချောက်ကိုမြင်၍—။” (ညောင်ကန်)')
,(12497,3,1,'အနက်။ အဓိပ္ပါယ်။','“ပ္ဍဲဂါထာဝွံ ကဗျကဵုဗန္ဓဂှ် လဂွံတုပ်ပ်ရ။” (တြာဲအလၚ်္ကာ) =“ဤဂါထာ­ ‘ကဗျ’ နှင့် ‘ဗန္ဓ’ သည် အနက်တူတူပၚ်ဖြစ်သည်။”')
,(12498,3,6,'လျော်ညီကြောင်းပြသောစကားလုံး။ အရ။','“လဂွံကဵုဂလာန်ဍေံဂှ် နွံအဓိပ္ပါယ်ၜါသာ်ရ။” = “သူ့စကားအရ အဓိပ္ပါယ်နှစ်မျိုးရှိသည်။” || “အတိုၚ်လဂွံကဵုအရထဝွံ သမ္မသိတၛာန်ဣၚုဟ်ဂပ်ဂဝ်သ္ဂးရ။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ဤဘာသာပြန်အနက်အရ သမ္မသိတဈာန်ဟု ဤသို့ဆိုအပ်၏။”')
,(12498,3,9,'—မည်သည်ကို။ —ဟူသည်ကို။','“လဂွံကဵုမွဲအန္တရကပ်ဂှ် နနဲသ္ဂးကဵုဂတဝွံ ဂပ်ဂဝ်သမ္တီရ။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “တစ်အန္တရကပ်ဟူသည်ကို ရှေ့တွင်ဆိုအံ့သောနည်းဖြင့် မှတ်သားအပ်၏။” || “လဂွံကဵုသာ်ပိပြကာဂှ် — သာ်လမ္စံက်က္ဍိုပ်က္ဍဴ၊ သာ်ဍာဲဗကေတ်၊ သာ်မိတ်ဖျိုဟ် ရဴသာ်ဝွံဂိုၚ်ကေတ် သာ်ပိပြကာဝွံညိ။” (တြာဲအလၚ်္ကာ) = “အဆင်းအရောင်သုံးမျိုးဟူသည်ကို စိမ်းညိုရောၚ်၊ အနီရောင်၊ ဝါဖျော့ဖျော့အရောင်ဟု ယူပါ။”')
,(12499,3,1,'အညစ်အကြေး။','“ဗၠိုပ်ဟုံလှာဲၜး စအးကၠေံလေငင်ပလက်တုဲ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ရေချိုးအဝတ်လဲကာ ချွေးအညစ်အကြေးကို သန့်စင်စေပြီးသော်။” || ‘ကၠိုက်လ္ၚေၚ်’ (န) လည်းရှု။')
,(12500,3,1,'‘အၚပ်’ နှင့်အတူတူ။',NULL)
,(12501,3,1,'အိုင်။','လစအနုတတ် = အနောတတ်အိုင်။ || “ပ္ဍဲဂြိုပ်ဂှ် လစဇၞော်မွဲနွံ။ နိဿဲကဵုလစတုဲ ကၠိက်ဂမၠိုၚ်နွံ။” (ဇ—၁၅၃။ အစွောံ။) = “ထိုတော­ တခုသောအိုင်ကြီးသည်ရှိ၏။ ထိုအိုၚ်ကိုမှီကုန်၍ များစွာကုန်သောဝက်တို့သည် နေကုန်၏။”')
,(12502,3,1,'သဘာဝအလျောက် အလိုလိုဖြစ်သောအိုင်ကြီး။','“ပ္ဍဲဋ္ဌာန်ဂှ် လစသြာၚ်မွဲနွံ စပ်ဒၟံၚ်ကဵုကြုၚ်ဇၞော်။” (ဇ—၁၇၈။ အစွောံ။) = “(ထိုအရပ်­) မြစ်ကြီးနှင့်တကွ တစပ်ထည်းသော အလိုလိုဖြစ်သောအိုင်ကြီးသည်ရှိ၏။” (ညောင်ကန်)')
,(12503,3,4,'ထွန်းလင်းသည်။ တောက်ပသည်။ အရောင်ဖိတ်ဖိတ်တောက်သည်။','“ကၠေပ်ထဝ်ဗာန်ထဝ်၊ သၠိုၚ်ထဝ်လစး။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ရွှေကျိုင်း၊ ရွှေလၚ်ပန်း၊ ရွှေခွက်တို့သည် အရောင်ဖိတ်ဖိတ်တောက်ကုန်၏။”')
,(12504,3,4,'ထွန်းလင်းသည်။ ထိန်လင်းသည်။ ထွန်းတောက်သည်။','“ညံၚ်မၞိက်ဝိပူလပဝ်ကဵုထဝ်ဇမ္မုနတ် — လစးလမးရာၚ်ဆာဲ။” (အာန်ဇုနာန်) = “ဝိပူလပတ္တမြားနှင့်ဇမ္ဗူရစ်ရွှေကဲ့သို့အရောင်ဖိတ်ဖိတ်တောက်ကာ တင့်တယ်၏။” || “ခါသၟိၚ်စန္ဒြး၊ ပၠလျးတူကျာ။ လစးလမး၊ ဂၠးဇံမုနာ။” (လိက်ဇိဝှစက္က) = “လမင်းစန္ဒာသည် အာကာသထက်တွင် အလင်းဆောင်သောအခါဇမ္ဗူဒိပ်အလုံးထိန်လင်း၏။” || “လျးကျာ်တြဲသၟတ်၊ ဒဵုကၞတ်ဗြီု။ လစးလမး၊ ဒးရးက္ဍၚ်က္ဍီု။” (လိက်ဂါထာလ္ၚောဝ်ကျာ်) = “မြတ်စွာဘုရား၏ရောင်ခြည်တော်သည် အထွတ်ဗြဟ္မာပြည်တိုင်အောင်ထွန်းလင်း၍ အလွန်အမင်းတင့်တယ်၏။”')
,(12505,3,4,'ထပ်လောင်းသည်။ ထပ်ဆင့်သည်။ ထပ်ပေါင်းသည်။','“သမ္ဘာဇၞော်လေဝ် နွံတဴရ၊ဒးလစံက်စုတ်သမ္ဘာဍောတ်မွဲပၠန်တုဲ မဒးသြိုၚ်သ္ၚိသမ္ဘာဍောတ်ဂှ်ပၠန်ရောၚ်အဴ။” (ဇ—၅၁၅။ အစွောံ) = “မယားကြီးရှိလျက် မယားငယ်တစ်ယောက်ကို ထပ်ယူပြန်သဖြင့် မယားငယ်အတွက် အိမ်ကိုဆောက်လုပ်ပေးရပြန်၏။”')
,(12506,3,16,'‘လမ္စံက်’ ရှု။',NULL)
,(12507,3,4,'‘လမ္စံက်ဍာပ်ဍဴ’ ရှု။',NULL)
,(12508,3,3,'‘လမ္စံက်ဒဝါန်’ ရှု။',NULL)
,(12509,3,3,'မည်းတူးသော။','“ခရီုပေၚ်ကၞိၚ်၊ ဂြိၚ်လစံက်အေဲ။” (လိက်တြုံကၟာဲဗြဴကၟာဲ) =“ပါးပြင်အနှံ့ ရွံ့ဗွက်ပေကျံလျက် အိုးမဲဖြင့် မည်းတူးနေ၏။ ”')
,(12510,3,4,'‘ဒစၚ်ဗၜၚ်’ ရှု။',NULL)
,(12511,3,1,'မျောက်တစ်မျိုး။ (?)','“(ဂြိုပ်ဂှ်) မတ္ၜန်တ္ၜောဲတဴကဵုကၠိက်ဒြာဲဗတာဲကၞုဲလစေၚ်တံဂှ်ရောၚ်။” (ဇ—၅ဝ၄။ အစွောံ။) || “ပြိပ်ယန်လစေၚ်၊ ပၠေအ်ဝေၚ်မံၚ်အဵု။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။)')
,(12512,3,1,'ကြာသိမ်။ (ကြာတစ်မျိုး) (ပါဠိ—ဒကသဳတလိက','သောဂန္ဓိက)')
,(12513,3,4,'တောက်ပသည်။','“ကၞိၚ်စက်ဂိတု၊ သ္ဇုၚ်ဂွုလစတ်။” (လိက်သၚ်ဂဒါ။သဳလဝန္တ။) = “(ချစ်နှမ၏ပါးပြင်သည်) လဝန်းပမာ စၚ်ကြည်ဖြူဖွေးတောက်ပနေ၏။” || “လျးစရာဲသၞံၚ်၊ ဂဵုမံၚ်လစတ်။” (လိက်မာဃဒေဝါန်) = “ကြယ်၏အလင်းရောင်သည် ထွန်းလင်းတောက်ပနေ၏။”')
,(12514,3,4,'ပြွတ်သိပ်သည်။ (?)','“တၞံဆုကျာ်သြဳ၊ အနဳဂြိုပ်ဗြာတ်။ သတ်တၟာဒြၚ်စိၚ်၊ ပေၚ် သၞိၚ်လစာတ်။” (လိက်ရာဇာဟတ္ထိ) = “ကျက်သရေရှိသော ငှက်ပျောတောသည် အသီးဆင်စွယ်ပမာဏရှိ၍ အခိုၚ်ပြည့်ပြွတ်သိပ်သီးနေ၏။”')
,(12515,3,9,'အကြိမ်၊ အချက်ကို ရေတွက်ရာတွင် သုံးသောစကား။','“သပါတဲအဲၜါ ကဵုညးရပ်လဝ်တုဲ ပိလစုတ်အ္စာမတက်အဲရောၚ်။” (ဇ—၂၅၂။ အစွောံ။) = “(ဆရာသည်) ငါ့ကို မောင်း­ကိုင်စေ၍ သုံးကြိမ်ရိုက်၏။” (ညောင်ကန်)')
,(12516,3,4,'နူးညံ့သည်။ ပျော့ပျောင်းသည်။','“ဥပးတြုံဗြဴတံ မၞုံစိုတ်ဍိုန်ဍောတ်လစောတ်လမောဝ်—။” (ပြကိုဟ်ဓမ္မဒေသနာ။ မာံရွှေငိုး။) =“ဒကာဒကာမတို့သည် နူးညံ့ပျော့ပျောင်းသောစိတ်ရှိကုန်၏။” || “ပွမဟီုဂလာန် သီုမဍိုန်ဍောတ်လစောတ်လမောဝ်။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “ပျော့ပျောင်းနူးညံ့သောစကားကို ပြောဆိုခြင်း။” || “(သၟိၚ်ဝေသန္တဝ် ကဵုဒါန်ကောန်ၜါတုဲ တိချဳတုဲ တၟအ်သိနနရာတ်တုန်) ရဴတ္ၜဝ်ဒပံၚ်ညးမစံၚ်တမ်ကၞတ်ကီု ဍိုန်လယတ် လစတ်လၟောဝ် တယောဝ်စှ်ေဂတမုက် တၟအ်ဝၚ်ဂပဝ်ရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ဝေဿန္တရာမင်းသည် သားသမီးတို့ကို အလှူပေးသည်ရှိသော် မြေၚလျှင်လှုပ်၍ မြင်းမိုရ်တောင်သည် ကြိမ်မီးအုံးသကဲ့သို့ ပျော့ပျောင်းနူးညံ့၍ ဝၚ်္ကပါတောင်ဘက်ဆီသို့ ညွတ်ကျလာ၏။” || “တိချဳၜဳစလိုက် တၟအ်သိနနရာတ်လဇောတ်လမောဝ် တယောဝ်ဖျေံဒဵုပါဒဟေၚ်။” (သၠပတ်ဂမ္စာဲဓါတ်) = “မြေင်လျှင်လှုပ်ခတ်၍ ပင်လယ်ရေဘောင်ဘၚ်ခတ်၍ မြင်းမိုရ်တောင်သည် ပျော့ပျောင်းနူးညံ့၍ ခြေတော်အထိညွတ်ကျလာ၏။”')
,(12517,3,1,'လက်စွပ်။',NULL)
,(12518,3,1,'ဝတ်စရာလက်စွပ်။','“သၞေက်မၞိက်၊ ပ္ကဴထဝ်၊ လစိန်စရံက်၊ လကံက်ထဝ်၊—။” (ဇ—၂၈၉။ အစွောံ။) = “ပတ္တမြားနားဍောင်း၊ ဦးခေါင်းတန်ဆာရွှေပန်း၊ ဝတ်စရာလက်စွပ်၊ ရွှေလက်ကောက်—။” || “လစိန်စရံက်၊ သီုလကံက်ဂွါ။” (လိက်ခၠေဝ်ရော်ဂုန်မိ)')
,(12519,3,1,'(= လစိန်မၞုံကဵုတဆိပ်) (ချိပ်တံဆိပ်နှိပ်ရန်) ကိုယ်ပိုၚ်သၚ်္ကေတ၊ အမည်အတိုကောက် စသည်ထွင်းထားသည့် တံဆိပ်ပါလက်စွပ်။ (signet-ring) (ပါဠိ—အင်္ဂုလိမုဒ္ဒိကာ)','“ယွံတၠညး၊ ဂၠံဂဝ်အဲဍိက်တန်အာရအဴ” သၟတ်ဗြဴဂး။ သၟိၚ်မိၚ်တုဲ လစိန်စၞန်တဲမွဲ သၟိၚ်ကဵုလဝ်ရ။ (ဇ—၇။ အစွောံ။) (မှတ်ချက်။ မွန်ဝေါဟာရ ‘စၞန်တဲ’ || ‘စၞောန်တဲ’ သည် ‘လက်ညှိုး’ဟု အဓိပ္ပါယ်ရသဖြင့် ‘လစိန်စၞန်တဲ’ ဟူသော ပေါင်းစပ်ဝေါဟာရကို ‘လက်ညှိုးတွင်ဝတ်သောလက်စွပ်’ မျှသာဟု အထင်မရောက်စေလိုပါ။ ‘တံဆိပ်ပါသောလက်စွပ်’ ဟုယူပါ။)')
,(12520,3,1,'အထွတ်အထိပ်။ အထွတ်အမြတ်။ အထွတ်အခေါင်။','“ပါရမဳကာန်၊ လိက်ဋ္ဌာန်လစောန်။ ဗမာတံသၟတ်၊ ပပြာကတ်လောန်။” (လိက်ပတံပါရမဳ။ အစွောံ။) = “အထွတ်အမြတ် ဖြစ်သော ပါရမီခန်းပျို့ကို ဗမာတို့သည် အလွန်အထင်အရှားပြုကြကုန်၏။” || “(သၟိၚ်ဇၞော်တီဒဒှ်လျးကျာ်တြဲတုဲ) ပဳတိလစောန်၊ သ္ဍိုက်လောန်သၟဟ်။ သမ္ၚုဒမြဴ၊ ကမြဴစိုတ်ဒှ်။” (လိက်ပ္တံပါရမဳ။အစွောံ။) = “မြတ်စွာဘုရားရောင်ခြည်တော်မှန်း မင်းကြီးသိသောအခါ ပီတိအထွတ်အထိပ်ရောက်၍ အလွန်နှစ်သက်၏။ ကြက်သီးမွေးညှၚ်ထမျှ စိတ်ရွှင်လန်း၏။” || “ဒုက္ခလစောန်၊ ဒဒိုက်လောန်လာန်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ဒုက္ခအထွတ်အထိပ်ရောက်၍ အလွန်အမင်းဆင်းရဲပူပန်၏။” || “အဵုရုပ်လစောန်၊ ကောန်ရာဇာဝၚ်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) =“အထွတ်အခေါင်ရုပ်အဆင်းရှိသော အို—ဘုရင့်သားတော်။”')
,(12520,3,3,'ကောင်းမွန်သော။','“ကြုက်မွဲတၞံကၠာ၊ တၟာတာဗၠာဲ။ သတ်ဍုဟ်လစောန်၊ တ္ဍာတ်မိပ်လောန်ကာဲ။” (လိက်ဟတ္ထိပါလ။အစွောံ။) = “သရက်တစ်ပင်သည် ထန်းပင်ပျိုပမာဏရှိ၍ အသီးမှည့်ကောင်းမွန်၍ အလွန်ချိုမြိန်လှ၏။”')
,(12521,3,4,'၁။ သာယာစွာမြည်သည်။','“ဗရုမဖျိုက်ကဵုကတောဝ်အဲသာ်ဝွံဂှ် ဍေံဟီုဒက်ဒေါန်လစောန်ရဏောန် မိပ်သ္ၚိပ်လောန်သန်သွံ။ မူဗရုဂှ်သ္ဂးရော။” (ဇ—၅ဝ၇။ အစွောံ။) = “ငါ၏နားကိုချမ်းသာစေသောသာယာစွာဆိုမြည်တမ်းသော ဤအသံသည်ကား မွေ့လျော်ဖွယ်ရှိစွ။ အဘယ်မည်သောအသံပါနည်း။” || “ခဍာ်မဗြုလစောန်ကဏောန်ဂှ် ကလောဆာန်မရှာဲအာလအ်ဂှ် ကၠုၚ်စိုပ်ရ။” (ဇ—၂၁၄။အစွောံ။) = “ကျီးသည် သာယာစွာမြည်ကြွေးလတ်သော် ကြာမြင့်စွာကွဲကွာနေသောဆွေမျိုးများလာရောက်လိမ့်မည်။” || “ဂစေံဂမၠိုၚ်ဗြုလစောန်တဏောန် ညံၚ်တွိၚ်တွိုက် ညးမသ္ဍိုက်ဒၟံၚ်ကတောဝ်ကီု။” (အာန်ဇုနာန်) = “ကျေးငှက်သာရကာများ သာယာစွာမြည်ကြွေးနေသေည်မှာနားဝင်ချိုစေသောတူရိယာသံကဲ့သို့ဖြစ်၏။”')
,(12521,3,4,'၂။ ပျက်စီးသည်။ ဆွေးမြည့်သည်။ (?)','“ဂၠာဲဆဵုသၠပတ်မန်တြေံပၠန်ရဂှ်လေဝ် ပိုတ်ဒကုတ်ပြးဆာဲ မှာဲမှမံၚ်လစောန်လဏောန်။” (သုဓမ္မဒေသနာ။ဂရိုက်သာံ။) = “မွန်စာပေဟောင်းပေရွက်စာတို့ကို ရှာတွေ့ပြန်ပါသော်လည်း စုတ်ပြတ်လျက်တစ်စစီကွဲကာ ဆွေးမြည့်ပျက်စီးနေကုန်၏။”')
,(12521,3,4,'၃။ ဒုက္ခပင်လယ်ဝေသည်။ အလွန်ဆင်းရဲသည်။','“လစောန်လဏောန်၊ ဂၠိုၚ်သန်ဒုက္ခ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) || “လစောန်လဏောန်၊အောန်စိုတ်လောန်ဗၞတ်။ ပတ္တစာရဳ၊ ပၠဳဍာ်ရမတ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ဒုက္ခပင်လယ်ဝေနေသော ပဋာစာရီသည် အလွန်အမင်း ဝမ်းနည်းပူဆွေး၍ မျက်ရည်ဖြိုင်ဖြိုင်ကျ၏။” || မွဲလစှ်ေ = တစ်စိတ်တစ်ဒေသ။ || အဝဲလစှ်ေ = အစိတ်အပိုင်း။အၚ်္ဂါအစိတ်အပိုင်း။')
,(12522,3,1,'၁။ အစိတ်အပိုင်း။','“ပ္ဍဲဂြိုပ်ဂှ်တုန်လေဝ် ပ္ဍဲလစှ်ေမွဲလပါ်ဂှ် ဒှ်ဇိုၚ်တၟံ၊ ဒှ်ကြုၚ် ဗွဲသ္ကဲဇိုၚ်တၟံမွဲဒိုဟ်ဂှ်ဒှ်ကွာန်ပစ္စန္တရးရ။” (ဇ—၃၁၆။ အစွောံ။) = “တော၏တဘက်မှ တောင်ခြေ၊ တဘက်မှမြစ်၊တဘက်မှ ပစ္စန္တရစ်ရွာသည်ရှိ၏။” (ညောင်ကန်)')
,(12522,3,1,'၂။ အရပ်ဒေသ။','“ဗောဓိသတ်ပိုဲ ဒှ်ပ္ဍဲဂၠံဂဝ်ဒြာဲ ပ္ဍဲလစှ်ေဂြိုပ်ဟေမဝန်တေံရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “ဘုရားလောင်းသည် ဟိမဝန္တာအရပ်­ သမင်မျိုးဝယ်ဖြစ်၍—။” (ညောင်ကန်) || “ဥဒျာန်ကြုက်ဂှ် မၞုံပ္ဍဲလစှ်ေဂြိုပ်ဟေမဝန် ပ္ဍဲဇရေၚ်ဂၚ်မွဲဂှ်ရ။” (ဇ—၅၁၁။ အစွောံ။) = “ထိုသရက်ဥယျာဉ်သည် ဟိမဝန္တာအရပ်­ တစ်ခုသောမြစ်ကမ်းနား­ရှိ၏။” || ‘ဒစှ်ေ’ ဟုလည်းရေးသည်။ || “ဗောဓိသတ်ဒှ်ဇၞော်သ္ကံစိၚ် — ပဒတဴဒစှ်ေဂြိုပ်ဟေမဝန်—။” (ဇ—၂၂၁။ အစွောံ။) || ‘ဒစှ်ေ’ (န) လည်းရှု။')
,(12523,3,5,'တစ်စိတ်တစ်ဒေသအားဖြင့်။','“တၠညးရာဇာဓိရာဇ် ဨကရာတ်တၠကြဳဇှ် စမုၚ်တုပ်ဗောဓိသတ် ဗွဲလစှ်ေညိ။” (သၠပတ်ရာဇာဓိရာဇ်) = “သူ့ရှင်ရာဇာဓိရာဇ်သည် တန်ခိုးရှင်ဧကရာဇ်ဖြစ်ပြီး ဘုရားလောင်းနှင့် တစ်စိတ်တစ်ဒေသအားဖြင့် ဆင်တူ၏။”')
,(12524,3,4,'‘တဆူ’ ရှု။',NULL)
,(12525,3,4,'‘ကဆံ’ နှင့်အတူတူ။',NULL)
,(12526,3,1,'‘တဆိၚ်’ ရှု။',NULL)
,(12527,3,4,'ကျယ်လောင်စွာမြည်သည်။ ခြိမ့်ခြိမ့်သဲမြည်သည်။','“ဖံမံၚ်ဂမြိၚ်၊ လဆိၚ်လဆန်။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “အိုးစည်ဗုံမောင်းသံတို့သည် ခြိမ့်ခြိမ့်သဲမြည်ဟည်းနေ၏။”')
,(12528,3,4,'လျှော်ဖွပ်သည်။','“ယာတ်ဗွိုက်လတက်၊ ကၠိခ္ဍက်ပၠ။ လဆံၚ်ကြာတ်ကြဴ၊ ရဴဂဴတဴရ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “(မိဘတို့၏) အဝတ်အစား ပေကျံညစ်နွမ်းသောအခါ ရိုသေစွာလျှော်ဖွပ်ဆေးကြော၏။” || ‘ကဆံၚ်’ ဟုလည်းရေးသည်။')
,(12529,3,5,'တစ်ခါတစ်ရံ။ ရံဖန်ရံခါ။','“ဗောဓိသတ်ပိုဲ နကွဳစောတ်မသုန်ကၠံဂှ် လဆောဝ်နူဗၟံက်အာပလိုတ်ရ။ လဆောဝ်နူပလိုတ်အာဗၞိက်ဗၟံက်ရ။” (ဇ—၁။ အစွောံ။) = “ဘုရားလောင်းသည် လှည်းငါးရာတို့ဖြင့် တစ်ခါတစ်ရံ အရှေ့အရပ်မှ အနောက်အရပ်သို့ ကုန်သွယ်ရန်သွား၏၊တစ်ခါတစ်ရံ အနောက်အရပ်မှ အရှေ့အရပ်သို့ ကုန်သွယ်ရန်သွား၏။” || “(ခမဳဂှ်) လဆောဝ်လဆောဝ် ပ္ဍဲပဋ္ဌမယာံဂှ်လေဝ် ကော်ပၚုဟ်ညးကီု။” (ဇ—၁၁၉။ အစွောံ။) = “ထိုရဟန်းသည်တစ်ခါတစ်ရံ ပထမယာံ­လည်း သူတစ်ပါးတို့ကို ခေါ်နှိုး၏။” || “လဆောဝ်ဂှ်ဇကုဂျိုၚ်တဴ ပိုန် ဒြပ်တံဂှ် ဍေံကၠေံဒဴအာကၠာကီု။ လဆောဝ်ပိုန်ဒြပ်ဂှ်နွံတဴ ဇကုချိုတ်ဒဴအာကၠာလေဝ်ဒှ်ကီု။” (ဇ—၃၅၁။ အစွောံ။) = “တစ်ခါတစ်ရံ မိမိသည်အသက်ရှင်လျက် ဥစ္စာတို့သည် အလျင်ကွယ်ပျောက်စွန့်ခွါသွားတတ်၏။ တစ်ခါတစ်ရံ ဥစ္စာတို့သည်ကျန်ရှိလျက် မိမိသည် အလျင်သေလွန်စွန့်ခွါသွားရတတ်၏။”')
,(12530,3,5,'အကြား။ စပ်ကြား။ ရံဖန်ရံခါ။','“အန္တရသနနိပါတေဝါ။ ပ္ဍဲဋ္ဌာန်သၚ်မကောံဓရီု လဆောဝ်လဗှ်ကီု။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “သံဃာများ ရံဖန်ရံခါ (စပ်ကြားစပ်ကြား) စည်းဝေးတိုင်ပင်ရာအရပ်။”')
,(12531,3,4,'(မြင်း၊ နွားစသည်) ကဆုန်ပေါက်ပြေးသည်။','“ကဵုချေံလဆဟ်၊ ပြဟ်ပြဟ်ညိနာဲ။”= “ချစ်သူရယ်၊ မြင်းကို မြန်မြန်ပြေးပါစေတော့လား။” || “ၜါတိုန်မွဲချေံ၊ ပြဟ်ပြေဟ်ခါဂှ်၊ ဍိုက်လဆဟ်အာ။” (ကောန်ဖေန်ကောန်ၛၚ်) = “နှစ်ဦးသားတို့သည် တစ်ခုတည်းသောမြင်းကိုတက်စီးပြီးလျှင် မြင်းကိုအမြန်ပြေးစေ၏။”')
,(12532,3,4,'နှောင့်နှေးစေသည်။ ဆိုင်းင့ံသည်။ ၚံ့လင့်သည်။','“ယွံမရာတ်၊ လဇညိကၠာ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မင်းမြတ်၊ ၚံ့လင့်တော်မူပါဦး။” || “တၠညးလ္ပလဇညိရ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “အရှင်မင်းကြီး မဆိုင်းၚံ့ပါလေနှင့်။” || “(ၜိုပ်သုမုခ) ပဝ်တိုန်အာဂတတေံတုဲ လဇဒိုအ်ဂၠာဲရံၚ်သ္ၚဳဂၠိတ်တဴရ။” (ဇ—၅၃၄။ အစွောံ။) = “သုမုခဟင်္သာစစ်သူကြီးသည်ရှေ့သို့ပျံတက်သွားပြီးလျှင် ဆိုင်းၚံ့၍ရပ်လျက် ရှာဖွေစုံစမ်း၏။”')
,(12533,3,5,'ဖြည်းဖြည်းနှေးနှေး။','“ကော်ဍိက်သ္ကအ်သ္တုံဇွိ မိမိန်ၝဲဂမာကျိုၚ်ကျဝ်ဗွဲမဒးရးတုဲ ဂၠောဲအာဍိုန်ဍိုန်လျလျ လဇလဇသာသာ။” (သၠပတ်စန္ဒဝတဳ) = “လက်ဝဲရံလက်ယာရံကျွန်အပေါင်းနှင့် အထိန်းတော်မတို့ကိုခေါ်ကာ လျောက်ပတ်စွာဝတ်စားဆင်ယင်၍ညင်ညင်သာသာ ဖြည်းဖြည်းနှေးနှေး စီတန်းလျှောက်သွား၏။”')
,(12534,3,1,'အဘိုး။','(လ + ဇု) ဤနေရာ­ ‘ဇု’ သည် ‘ချစ်လှစွာသော’ ဟူသောအနက်ရှိသည်။ (လဇု = ချစ်လှစွာသောအဘိုး) || ‘ဇု’ တွင်ရှု။ || “မဇကုကီု လဇုကီု ဗ္တောန်ကဵုကွတ်တုဲ ကောန်ဂှ် ဂွံလေပ်ကွတ်အိုတ်ရ။” (ဇ—၄၇၉။ အစွောံ။) = “ထိုမင်းသားသည် — ခမည်းတော်၊ ဘိုးတော်တို့၏အထံ­ အလုံးစုံသောအတတ်တို့ကိုသၚ်၍—။” (ညောင်ကန်) || “လဇုဍေံဂှ် ပကၠေံကာဂစိုတ်ရ။” (ဇ—၃၅၂။ အစွောံ။) = “အဘိုးသည် သေလွန်၏။” (ညောင်ကန်)')
,(12535,3,4,'ဆင့်တၚ်သည်။','“ထၟာဲသွဂှ် လဇံက်လဝ်လ္တူထၟာဲပုၚ်ညိ။” = “ဟင်းအိုးကို ထမင်းအိုးပေါ်တွင် ဆင့်တင်ထားပါ။” || လဇံက်က္ဍိုၚ်ကျာ် = ဘုရားထီးတော်တင်သည်။ || “ဂနပ်ကျာ်အဵု၊သၟိက်ကဵုဒှ်မွဲ။ ကျာ်လဇံက်ပၠန်၊ သီုပန်ထပ်ဂၠောဲ။ အဒိဋ္ဌာန်ကၠာ၊ စေတနာမွဲ။ ဗဗေၚ်ပန်ပြဲ၊ ဒှ်အာမွဲရ။” (လိက်တပူတဗဝ်) = “သပိတ်လေးလုံးတို့ကို တစ်လုံးတည်းဖြစ်စေတော်မူလို၍ မြတ်စွာဘုရားသည် သပိတ်လေးလုံးစလုံးကို ထပ်၍ဆင့်တင်ကာ အဓိဋ္ဌာန်တော်မူသည်ရှိသော် သပိတ်လေးလုံးတို့သည် သပိတ်တစ်လုံးတည်းဖြစ်သွား၏။”')
,(12536,3,4,'‘လစောတ်လမောဝ်’ ရှု။',NULL)
,(12537,3,3,'၁။ ဝဖြိုးသော။ ဝလုံး၍ကြည့်ကောင်းသော။ (ပလုမပ)','‘ဗြဴဝုတ်လဇာဲ/ဗြဴလဇာဲ’ (ဇ—၃ဝ။ အစွောံ။) = ‘ဝဖြိုး၍ကြည့်ကောင်းသောမိန်းမ။’ (မှတ်ချက်။ မြန်မာညောင်ကန်ဆရာတော်မူ­ ‘ဗြဴဝုတ်လဇာဲ’/‘ဗြဴလဇာဲ’ ကို ‘အပျိုကြီး’ ဟုပြန်ဆိုထားသည်မှာ အဓိပ္ပါယ်လွဲနေပါသည်။အင်္ဂလိပ်ဘာသာမူ­ ္ၜအ ပလုမပ ယုံနဂ ဝံမအန္ၜ ဟုလာသည်။ စင်စစ် ‘အပျိုကြီး’ မဟုတ်၊ ‘အပျိုငယ်’ သာဖြစ်ပါသည်။) || “ပဟိုတ်ကဵုခမဳမွဲ ညာတ်ဗြဴဝုတ်လဇာဲ ပ္ဍဲစိုတ်စပ်အာတုဲ ကသပ်သၟိက်ဂွံရာံဂှ်ဒှ်တုဲ — ကျာ်တြဲမတွံ။” = ဝဖြိုးကြည့်ကောင်းသော မိန်းမပျိုတစ်ယောက်ကိုမြင်၍ စိတ်­တပ်မက်သွားကာ လူထွက်ရန်အကြံဖြစ်သော ရဟန်းတစ်ယောက်ကို အကြောင်းပြု၍ မြတ်စွာဘုရားဟောတော်မူ၏။')
,(12537,3,3,'၂။ နှေးသော။ နှေးကွေးသော။','“ဟးဟဇ္ဇနဲ၊ ချေံသၟိၚ်တ္ၚဲဗၠာဲ။ လဂံါလဇာဲ၊ ချေံနာဲဍောၚ်ၜိုတ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “နေမျိုးနွယ်မင်းပျို၏ စီးတော်မြင်းဖြစ်သော အိုအာဇာနည်မြင်း၊ ပင်ပန်းမောပန်း၍ ခြေလှမ်းနှေးကွေးလာ၏။”')
,(12538,3,4,'နှေးသည်။ နောက်ကျသည်။','“တ္ၚဲဏအ် ဍေံလ္ဇုဲဘာရ။” = “သည်နေ့ သူကျောင်းနောက်ကျသည်။”')
,(12539,3,3,'ခေတ်မမီဖြစ်သော။ ခေတ်နောက်ကျသော။',NULL)
,(12540,3,4,'နှောင့်နှေးသည်။ ကြန့်ကြာသည်။',NULL)
,(12541,3,4,'နောက်ကျကျန်ရစ်သည်။','“မၞိဟ်လဇုဲလလုဲအာဟွံမာန် သီုစိၚ်ချေံတံဂှ် ရဲပိဒပ်တံလပှ်ရပ်သီဂွံနၚ်ဗွဲမဂၠိုၚ်။” (အကြီုရာဇာဓိရာဇ်) = “မသွားနိုင်ဘဲ နောက်ကျကျန်ရစ်သော လူများနှင့်ဆင်မြင်းတို့ကို ထိုတပ်သုံးတပ်တို့က များစွာကောက်သိမ်းယူဆောင်လာ၏။”')
,(12542,3,4,'နောက်ကျသည်။ ဖင့်နွှဲသည်။ နှောင့်နှေးသည်။','“ကုသဵုညးမပ္တုဲ လဇုဲသၞုဲဂဒေက်အာဂှ် ဇိုန်ကဵုဖဵုလေဝ် လဇုဲသၞုဲအာကီုရ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ကုသိုလ်ပြုရာ­ နှောင့်နှေးဖင့်နွှဲပါက အကျိုးပေးလည်း နှောင့်နှေးနောက်ကျသွားလိမ့်မည်။”')
,(12543,3,1,'၁။ အမြင်။ ထင်မြင်ယုံကြည်ချက်။','“လညာတ်အဲဗၠေတ်အာဟာ။” = “ကျွန်တော်၏အမြင် လွဲမှားသွားသလား။” || ‘သမ္မာဒိဋ္ဌိ၊ မၞုံလညာတ်ဒးရး။’ (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = ‘မှန်သောအမြင်ရှိသည်။’')
,(12543,3,1,'၂။ မြင်ကွင်း။','“ကလော်တံဂှ် ဍေံအာလောန်အာညိ ဗၠးနူလညာတ်မၞိဟ်တုဲ ဍေံစဴအာဍုၚ်ကလော်ဒမံၚ်ဍေံရ။” (ဇ—၁။ အစွောံ။) = “ဘီလူးတို့သည် အတန်ငယ်သွား၍ လူမြင်ကွင်းမှကွယ်သည်နှင့် သူတို့၏နေရပ်ဘီလူးမြို့သို့ ပြန်သွားကြကုန်၏။”')
,(12544,3,4,'တိုက်ခိုက်သည်။ ထိခတ်သည်။ ထိခိုက်သည်။','‘ထဍဳလယတ်/ခဍဳလယတ်’နှင့်အတူတူ။')
,(12545,3,3,'ကောက်သော။ ကော့လန်သော။','“ဆုကြိက်ဟၟဲကဵုဇလ ဟၟဲကဵုခမှံက်သၟာဲသၟ ဟွံလဍိုဟ်ဟွံလဍေၚ် သ္တပ်သ္တေၚ်ဒၟံၚ်—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ထိုလက်ပံပင်သည် ဆူးမရှိ၊ အခေါင်းအပေါက် အပုပ်အဆွေးမရှိ၊ မကောက်မကော့ ဖြောင့်တန်း၏။”')
,(12546,3,3,'ကောက်သော။','“မာတ်ဨကရာတ်မကဵုဂၠာဲဆုသြိုၚ်နန် ဆုဟွံလဍိုဟ် ဒးဗၞတ်ခိုဟ်က္ဍၚ်သန် ညးကေတ်ဖျဴဏာ ဂကောံဆုဂမၠိုၚ်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ဘုရင်က နန်းအိမ်ဆောက်ရန် သစ်ကိုရှာစေရာ မကောက်သော အရွယ်တော်ဖြစ်သော အလွန်ကောင်းသောသစ်ကို သစ်များနှင့်အတူ ယူဆောင်သွား၏။” || “(သေဋ္ဌဳဣလိသဂှ်) နွံကဵုဒုဟ်တြုံ ဇိုၚ်ထဍဴ တဲလဍိုဟ် မတ်ဟွံသၟဟ်။” (ဇ—၇၈။ အစွောံ။) = “ထိုဣလ္လိသသူဋ္ဌေးသည် ယောကျာ်းယုတ်တို့၏အပြစ်နှင့်ပြည့်စုံ၏။ ခွင်သောခြေရှိ၏၊ ကောက်သောလက်ရှိ၏၊ စွေသောမျက်စိရှိ၏။” (ညောင်ကန်)')
,(12547,3,3,'ကောက်သော။ ကောက်ကွေ့သော။','“အိုတ်ကြုၚ်ၜဳဂမၠိုၚ် နွံတဴသဘဴမလဍိုဟ်တၚံက်။” (သၠပတ်ကုလဇာတ်) =“အလုံးစုံသောမြစ်ပင်လယ်တို့သည် ကောက်ကွေ့သောသဘောရှိ၏။”')
,(12548,3,6,'အပေါ်။',NULL)
,(12549,3,1,'၁။ အပေါ်ယံသဘော။ အပြင်ပန်း။','“အပေါတ်ဏအ်ဂှ် ရံၚ်လတူကျာမ္ဂး ညံၚ်ခိုဟ်တဴကီုလေဝ် ရံၚ်ချိုတ်တ်ပၠိုတ်တ်မ္ဂး ဍေံဟွံခိုဟ်ကွေံကွေံရ။” = “ဤပစ္စည်းသည် အပြင်ပန်းကြည့်လျှင် ကောင်းသလိုရှိသော်လည်း အသေအချာကြည့်လျှင်ကား တကယ်မကောင်းပါ။”')
,(12549,3,1,'၂။လေညာ။ လေ၏အထက်အရပ်။','“ဟာဲခါခဏဳ၊ (ဗှ်ေဒှ်ဂကူစဏာ) ဗှ်ေလ္ပဒၟံၚ်လတူကျာအဲ။” (ဇ—၃၇၇။ အစွောံ။) = “သင်သည် စဏ္ဍာလယုတ်တည်း။ လေညာ­ မနေလင့်။” (ညောင်ကန်)')
,(12550,3,1,'နို့ညှာ။ နို့စို့ကလေး၏ အထက်ဖြစ်သောကလေး။','‘ကောန်တှ်’ လည်းရှု။')
,(12551,3,1,'လည်ကုပ်။',NULL)
,(12551,3,4,'ဝတ်သည်။','လတက်ပလောအ် = အင်းကျီဝတ်သည်။')
,(12552,3,4,'ဝတ်ဆင်သည်။','“ယာတ်ကၠိခ္ဍက်၊ ဒးလတက်ကြာဲ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ညစ်နွမ်းသောအဝတ်ကို ဝတ်ဆင်ရ၏။”')
,(12553,3,1,'လျှာ။','“ရုပ်သၟတ်ဗြဴ ဗောဓိသတ်မကၠောန်လဝ်ဂှ် နလတာ်လ္ၚီကီု ဟီုထိုၚ်သးဟွံမာန်ဟေၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “ဘုရားလောင်းလုပ်သော မိန်းမရွှေစင်ရုပ်ကို တစ်ထောင်သောလျှာတို့ဖြင့်လည်း ပြောဆိုချီးမွမ်းခြင်းငှာ မတတ်နိုင်။”')
,(12554,3,1,'ရှားစောင်းလက်ပတ်။ (ဆေးဘက်ဝင်)',NULL)
,(12555,3,4,'လျှာပါးသည်။ လျှာသွက်သည်။ စကားသွက်သည်။',NULL)
,(12556,3,4,'ဖတ်ရဆိုရ ခက်ခဲသည်။ လျှာမသွက်ဖြစ်သည်။ စကားမပီမသဖြစ်သည်။',NULL)
,(12557,3,4,'လျှာလေးသည်။ နှုတ်လေးသည်။ ရွတ်ဆိုသင်ကြားရန်ခက်သည်။',NULL)
,(12558,3,4,'(ဥပစာ) လျှာထွက်လောက်အောင် ပင်ပန်းသည်။',NULL)
,(12559,3,1,'လေမှုတ်တူရိယာ၏လျှာခင်။ ခရာ၏လျှာခင်။',NULL)
,(12560,3,4,'လျှာပေါ့သည်။ စကားသွက်သည်။ သင်ကြားရွတ်ဆိုရလွယ်သည်။',NULL)
,(12561,3,1,'ချိန်ခွင်လျှာ။',NULL)
,(12562,3,1,'၁။ ကျောက်ပွင့်။',NULL)
,(12562,3,1,'၂။ သမုဒ္ဒရာရေမြှုပ်ကျောက်။ ပင်လယ်ရေမြှုပ်။ (ပါဠိ—သမုဒ္ဒဖေဏကဍိဏ္ဍိရ)',NULL)
,(12563,3,1,'သစ်ဆွေးများကြားတွင် ပိုးမွှားများရှာစားလေ့ရှိသော များသောအားဖြင့် ကိုယ်အစိမ်းရောင်ရှိသော အမည်မဖော်နိုင်သောငှက်တစ်မျိုး။','“မိၚ်လတုက်ဂြဴ၊ မိၚ်ကဴဝဴဗြု။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်)')
,(12564,3,1,'၁။ အကြော။ (ပါဠိ—နှာရု။)','“မံၚ်သံၚ်ဂးဖျုန်ဝွံ၊ နာရုတွံလတေၚ်။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော) = “မံသမည်သည် အသားဟုဆို၍ နှာရုမည်သည် အကြောဟုဟော၏။” || လတေၚ်ဆီ = သွေးကြော။ || “ကြာန်လဝ်ဇကု၊ နှာရုဟီုလဝ်။ လတေၚ်ဇၞော်မောဝ်၊ လဝ်နာမတွံ။ဇၞော်သွတ်အိုဿီု၊ ဂၠာဲဟီုလဖှ်။ ဒပှ်လက်ကၠာ၊ ၜါလ္ၚီရေၚ်သၟဟ်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “ကိုယ်ကိုယှက်သန်းထားသော အကြောကြီးငယ်အပေါင်းသည် ရေတွက်မည်ဆိုပါက ခုနစ်သောင်းနှစ်ထောၚ်ရှိ၏။”')
,(12564,3,1,'၂။ အမြှေး။ အမြှေးသား။ ကြွက်သားကြောမျှင်။ (ပါဠိ—ကိလောမ)','“ယွံသဟာဲပိုဲ၊ လဟီုတၠအဲဂှ် ကြံၚ်သ္ကာတ်လောန်သန်သွံ။ ဍေံမတုပ်ကဵုလတေၚ်တမြံၚ်ရောၚ်။ ယွံသဟာဲ၊ လတေၚ်တမြံၚ် ဍေံမတုပ်ကဵုဂလာန်မသ္ကာတ်မြဟ်ဂှ် အဲကဵုကုတၠအဲရ” လၟဂး။ (ဇ—၃၁၅။အစွောံ။) = “အဆွေ၊ သင်သည် အမဲကို တောင်းသည်ဖြစ်၏။ သင်၏စကားသည် စင်စစ်ကြမ်း၏။ သင်၏စကားသည် အမြှေးနှင့်တူ၏။ အဆွေ၊ သင့်အား အမြှေးကို ပေးအံ့” ဟုမုဆိုးဆို၏။ (ညောင်ကန်)')
,(12565,3,1,'သွေးကြော။',NULL)
,(12566,3,1,'သွေးပြန်ကြော။ နှလုံးသို့ သွေးပြန်လည်စီးဝင်ရာအကြော။',NULL)
,(12567,3,1,'သွေးလွှတ်ကြော။ နှလုံးမှ ကိုယ်အၚ်္ဂါအသီးသီးသို့ သွေးပို့ဆောင်ပေးသောအကြော။',NULL)
,(12568,3,1,'အာရုံကြော။',NULL)
,(12569,3,4,'(အပေါ်သို့) ပစ်တၚ်သည်။ မြှောက်တၚ်သည်။','“(မၚ်ဗၠာဲဂှ်) လတိုၚ်ဝေၚ်နုၚ်ဂှ်တုဲခမ်ကေတ်ရ။ လတိုၚ်ၜါဝါပိဝါဂှ် ခမ်ဂွံရ။ လတိုၚ်မွဲဝါပၠန်ဂှ် ခမ်ဟွံဂွံ—။” (ဇ—၂၉၁။ အစွောံ။) =“လုလင်သည် အိုးကို ကောင်းကင်သို့ မြှောက်ကစား၍ (လက်ဖြင့်) ဖမ်းယူ၏။ နှစ်ကြိမ်သုံးကြိမ်မြှောက်သော် ဖမ်း၍ရ၏။ နောက်တစ်ကြိမ်မြှောက်ပြန်သော် ဖမ်း၍မရ။” || “ကမၚ်ကဝ်ဇၞော်မွဲဂှ်ဍေံသၠာ်တိုန် လတိုၚ်ဇကုတုဲ—။” (ဇ—၃၆ဝ။ အစွောံ။) = “တစ်ခုသောမကန်းသည် (ရေမှ) ခုန်တက်ကာ (လေတွင်) ကိုယ်ကိုမြှောက်၍—။” || “ပစ္စေဂဗုတ်လတိုၚ်ပ္တိုန်ဗဗေၚ် ပ္ဍဲလတူအာကာသ။” (ဇ—၄ဝ။ အစွောံ။) = “အရှင်ပစ္စေကဗုဒ္ဓာသည် သပိတ်တော်ကို ကောင်းကင်သို့ မြှောက်တၚ်တော်မူ၏။”')
,(12570,3,4,'‘ကတိုၚ်ကမှ်’ ရှု။',NULL)
,(12571,3,9,'အခေါက်။ အကြိမ်။','“(သၟိၚ်အိန်) ကလာၚ်ရေတ်ကၠေံဍုၚ်ဂှ် ပိလတုန်—။” (ဇ—၃၉၁။ အစွောံ။) = “သိကြားမင်းသည် ကောင်းကင်­ပျံလျက် ထိုမြို့ကို သုံးကြိမ်လှည့်ပတ်၏။”')
,(12572,3,5,'ဤအကြိမ်တော့ဖြင့်။ ဤအချီတော့ဖြင့်။','“လတုန်ဝါဝွံ သြိုဟ်မိဒးဒကးအာၜါလွးရသွံကောဂၞဴအဲ။” (ဇ—၄၈၅။ အစွောံ။) = “ဤအချီတော့ဖြင့် နှမခမျာ ရၚ်နှစ်ခြမ်းကွဲရရှာပြီပေါ့လား မယ့်မောင်ကြီးရဲ့။” || “သြ—လတုန်ဝါဝွံ မိသ္ဒးပကာဂစိုတ် သ္ဒးအိုတ်ခန္ဓ ဒးဒှ်ဇွဗိုန်န်ရကောန်ပိ။” (သၠပတ်ဗြဟ္မဒတ္တ ဂၞကျာ်ခေမာဝတဳ) = “အိုချစ်သားချစ်သမီးသုံးဦးတို့၊ ဤအကြိမ်တော့ဖြင့် မိခင်သည် ခန္ဓာစဲ၍သေ၍ အလောင်းကောင်ဖြစ်ရတော့မည် မလွဲပြီတကား။”')
,(12573,3,1,'ဆီးနှင်း။','‘ဍာ်လတိုပ်ဂှ် ဂၠုဟုပ်ကၠုၚ်—။’ (ဇ—၃ဝဝ။ အစွောံ။) = ‘ဆီးနှင်းရေသည်ထူထဲစွာလာ၏။’ || “လတိုပ်ဗရဲ၊ သၟဟ်မဗြဲပၠန်။” (လိက်ဇိဝှစက္က) = “မိုးပေါက်ပမာ ဆီးနှင်းဆွတ်ဖျန်းသည်။”')
,(12574,3,1,'ဆီးနှင်း။ ဆီးနှင်းပေါက်။',NULL)
,(12575,3,1,'အကိုင်းအခက်။ အခက်အလက်။','“ကျာလမုဟ်ဆံၚ်၊ ပိုက်မံၚ်သြဳသြဳ။ သၠဆုဂရာၚ်၊ လတှ်ကၞာၚ်ချဳ။” (လိက်မာဃဒေဝါန်) = “လေအေးထပ်ဆင့်၍ ဖြည်းဖြည်းညင်းညင်း တိုက်ခတ်သည်ရှိသော် သစ်ရွက်နှင့်အကိုင်းအခက်များ လှုပ်ရှားနေ၏။”')
,(12575,3,4,'မောက်မာသည်။ ထောင်လွှားသည်။ ကြုံးဝါးသည်။','“ကြီုကြလတှ်၊ ဒှ်ဒၟံၚ်ဏီဟာ။ ကြီုဟွံမာန်ရ၊ ခန္ဓဇရာ။” (လိက်အနုသာသန) = “မောက်မာထောင်လွှား ကြုံးဝါးနိုင်ပါသေးသလား။ ခန္ဓာအိုမင်း၍ မကြုံးဝါးနိုင်တော့ပါ။” || “ဍာ်လစကီု၊ သီုမြမောဝ်စှ်။ ဖုံဗလိုပ်ရ၊ တလကြဳဇှ်။ ကြီုဇာလတှ်၊ ကာလဂှ်ကၠာ။” (လိက်ထေအနန်) = “နံ့သာမျိုးဆယ်ပါးဖြင့်ထုံထားသော အိုၚ်မှရေဖြင့် ရေချိုးစေပြီးသော် အစွမ်းအာနုဘော်အရှင် (ဘုရားလောင်းတော်) သည် ထိုအခါ­ ကြုံးဝါးတော်မူ၏။”')
,(12576,3,5,'ထိုနေရာမှာ။ ဟိုမှာ။','“လတေံ စန္ဒဝတဳပၠန်တုန်လေဝ် လုကဴမွဲဗ္တံ မံၚ်ပ္ဍဲဂၠံဂါပ်ဆု။” (သၠပတ်စန္ဒဝတဳ) = “ဟိုမှာ စန္ဒဝတီသည်လည်း တစ်ညပတ်လုံး သစ်ပင်ခွကြား­နေ၏။”')
,(12577,3,1,'၁။ အလယ်အလတ်အရွယ်ယောကျာ်း။ မဇ္ဈိမအရွယ်ယောကျာ်း။ (အသက် (၃ဝ) မှ (၆ဝ) အထိ အရွယ်ရှိသောယောကျာ်း။ လူ့သက်တမ်း (၉ဝ) ဖြင့် တွက်ထားသည်။ အသက်အပိုင်းအခြားကို သုံးပိုင်းအညီအမျှ ပိုင်းခြားသည်။)','‘ယထဴ’ နှင့် ‘သၟတ်တြုံ’ တို့လည်းရှု။')
,(12577,3,1,'၂။ အိမ်ထောင်ပြုပြီးသောယောကျာ်း။','“ဂကောံလထဴကဵုဂကောံဗၠာဲ ဝေၚ်တေအ်ကရောဲ (မခ္ဍမ်ကျာ) ရ။”= “အိမ်ထောင်ပြုပြီးသော ယောကျာ်းအသင်းနှင့် လူပျိုအသင်းတို့ ဘောလုံးကစားကြသည်။”')
,(12578,3,4,'ဖုံးကွယ်သည်။ အကာအကွယ်ပေးသည်။',NULL)
,(12579,3,4,'ကျယ်လောင်သောအသံပြုသည်။ ခြိမ့်ခြိမ့်သဲမြည်သည်။','“(တွိၚ်တွိုက်နာနာသာ်) သကဵုလဒုဒၟံၚ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “တူရိယာအမျိုးမျိုးကို ခြိမ့်ခြိမ့်သဲမြည်နေစေ၏။” || “ဓါပ်ဆာၚ်လဒု၊ ဖောၚ်မံၚ်ဗြုလောန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “အိုးစည်၊ လၚ်ကွင်း၊ ဗုံ၊မောင်းတို့သည် ခြိမ့်ခြိမ့်သဲမြည်ကုန်၏။” || “ဒြီုဒြီုလဒု၊ ကဵုသာဓုကာ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “တစ်ကွနက်သောအသံဖြင့် ကျယ်လောင်စွာကောင်းချီးပေး၏။” || “ခမဳဍောတ်အဇိတထေရ် ကြက်သ္ဂောံဒှ်ကျာ်တြဲအရဳယျဂတဝွံရောၚ် ကျာ်တြဲဂးတုဲ သီုခမဳဂမၠိုၚ်လလောၚ်လဒု ကဵုတဴသာဓုကာအိုတ်ရ။” (အဓါန်မသုန်။ အစွောံ။) = “အဇိတမည်သောရဟန်းငယ်သည် ရှေ့အနာဂတ်တွင် အရိယျမေတ္တေယျမည်သော မြတ်စွာဘုရားဖြစ်လတ္တံ့ဟု မြတ်စွာဘုရားမိန့်တော်မူသည်ရှိသော် ရဟန်းများသည် ပဲ့တၚ်ထပ်မျှ ကျယ်လောင်စွာသောအသံဖြင့် ချီးမွမ်းသြဘာပေးကြကုန်၏။” || “ကောန်ဒေဝတဴတံယာံတဴဒြီုဒြီု — ဒဥလဒုတမ္ညဝ်တဴ အလုံဍုၚ်သွဝ်ဂှ်အိုတ်ရ။” (ဇ—နေမိ။အစွောံ။) = “နတ်သားတို့သည် ကျယ်လောင်သောအသံဖြင့် ငိုကြွေးကြကုန်၍ နတ်ပြည်အလုံးမြည်ဟည်းဆူညံသွား၏။”')
,(12580,3,4,'အနှံ့ကျော်ကြားသည်။ ကျော်စောသည်။','“(ကျာ်တြဲ) မဒှ်အ္စာမၞိဟ်ဒေဝတဴ လလောၚ်ထဥ လဒုကမြဴဒၟံၚ်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ပဲ့တၚ်ထပ်မျှ အနှံ့အပြားကျော်ကြားနေသော လူနတ်တို့၏ဆရာဖြစ်တော်မူသော မြတ်စွာဘုရား။”')
,(12581,3,4,'နှိမ်နင်းသည်။ ငြိမ်သက်အောင်ပြုသည်။ ငြိမ်းစေသည်။','“ပ္ဍဲမုဟ်ရးတေံ က္တဵုဒှ်ဗပုန် သၟိၚ်စဳရေၚ်ပၞာန် ဇက်အာလဒံရးရ။” (ဇ—၄၇၂။ အစွောံ။) = “ပစ္စန္တရစ်­ သူပုန်ထသည်ကို ငြိမ်းအံ့သောငှာ မင်းသည် စစ်ကိုစီရင်၍ ချီတက်သွား၏။” || “ခမဳဂမၠိုၚ် — က္တဵုဗဒှ်သွေက်ဇဵုဖရဳဖဇးရၚ်သ္ကံတုဲ ဂ္ဇအ်ဒၟံၚ်ရ။ ကျာ်ကော်မုဂ္ဂလာန်တုဲ သ္ဂးရ၊ ‘ယွံမုဂ္ဂလာန်၊ လဒံကၠေံခမဳတံဂှ်ညိ’ကျာ်တြဲဂး။” (ဇ—၂၉၉။ အစွောံ။) = “ရဟန်းတို့သည် ငြင်းခုံခြင်းကို၄င်း ပြောင်လှောင်ခြင်းကို၄င်း ပြုကုန်၍နေကုန်၏။ မြတ်စွာဘုရားသည် မောဂ္ဂလာန်ကို ခေါ်တော်မူ၍ ‘ထိုရဟန်းတို့ကိုငြိမ်သက်အောင်ပြုလော့’ ဟုမိန့်တော်မူ၏။” || “သမ္ၚေဟ်ဂှ် သၟိက်လဒံကၠေံယဝံါကောန်ဂှ်တုဲယိုက်ပၠောပ်ဏာပ္ဍဲသ္ၚိရ။ (ဇ—၅၃၇။ အစွောံ။) = “သူကြွယ်သည် ကလေးငိုခြင်းကို ငြိမ်သက်စိမ့်သောငှာ ကလေးကိုချီ၍ အိမ်ထဲသို့ယူဆောင်၏။ || “မဂွံလဒံ၊ လလံဒေါသ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ဒေါသကို ငြိမ်းစိမ့်သောငှာ နှိပ်ကွပ်သည်။”')
,(12582,3,4,'(စိုးရိမ်ပူပန်စိတ်ကို) ငြိမ်းစေသည်။ ကုစားသည်။','“ဣသိမယာံစံၚ်တူဒၟံၚ်ဂှ်သၟိၚ်ဣန်ဒလောံဗ္တောန် လဒံကၠေံစိုတ်ဣသိရ။” (ဇ—၄၁ဝ။ အစွောံ။) = “ငိုကြွေးပူဆွေးနေသောရသေ့ကို သိကြားမင်းဆုံးမ၍ ရသေ့၏စိတ်ကို ငြိမ်းအောင်ကုစား၏။”')
,(12583,3,4,'အမောအပန်းဖြေသည်။ အမောကိုငြိမ်းပျောက်စေသည်။',NULL)
,(12584,3,4,'အော်မြည်သည်။ ဟစ်ကြွေးသည်။ မြည်တမ်းသည်။ (ကျေးငှက်) မြည်ကြွေးသည်။','“တၞံဆုတံဂှ် မတၟုဲတဴနရှ်ပ္ကဴသတ်ရောၚ်။ မၞုံကဵုဂစေံမဂြဴလဒက်သ္အဝ်တဴနာနာသာ်။” (ဇ—၅ဝ၄။ အစွောံ။) = “သစ်ပင်တို့သည် အရသာရှိသောအသီးအပွင့်နှင့် ပြည့်စုံကုန်၏။ ကျေးငှက်တို့သည် အထူးထူးအပြားပြား တွန်ကျူးမြည်ကြွေးကုန်၏။” || “သတ်တၠသၞေၚ်ဖျေၚ်စၟဴ ဂြဴလဒက်သ္အဝ်ဒၟံၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ကျေးငှက်များသည် နှုတ်သီးကိုလှည့်ချီလျက် တွန်ကျူးမြည်ကြွေးနေကုန်၏။” || “ပ္ဍဲဂြိုပ်မၞုံကဵုဂစေံမြာ်ကွဴ မဂြဴလဒက်လအဝ်တဴ မဂပ်ဂဝ်လှိၚ်စိုတ်ရောၚ်။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “သာယာစွာတွန်ကျူးမြည်ကြွေးသော ဥဒေါင်းဥသြငှက်တို့ရှိရာတောသည် နှလုံးမွေ့လျော်ဖွယ်ရှိ၏။” || “နဗရုဖံပၞာန်၊ ကရေဲစိၚ်၊ ကမြေတ်ကွဳတံဂှ် ဍေံကြီုကြလဒက်လအဝ် ဂမြံဒဥဂၠုသကိုပ်တဴ ညံၚ်ရဴမတ်ဗြဲဂှ်ဒှ်တုဲ—။” (ဇ—၂၂၉။ အစွောံ။) = “စစ်အောင်စည်အောင်မောင်းသံ၊ တိုက်ဆင်များဟည်းသံ၊ စစ်လှည်းရထားမြည်သံတို့ဖြင့် ကြုံးဝါးဟစ်ကြွေးမြည်ဟိန်းလျက် (စစ်သည်ဗိုလ်ထုသည်) မိုးတိမ်ထုကဲ့သို့ စုရုံးညို့မှိုင်းလျက်ရှိကုန်၏။” || “သာ်ဝွံဂၞကျာ်မဒ္ဒဳ ယာံလဒက်သအဝ် ပ္ဍဲကာလဂှ်ရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ထိုအခါ­ ဤသို့မဒ္ဒီမိဖုရား ငိုကြွေးမြည်တမ်းလေ၏။”')
,(12585,3,4,'ဉာဏ်ထိုင်းသည်။ ပညာနုံ့သည်။ (ပါဠိ—မန္ဒ)','‘ဂဒေက်’/‘ဂဒိုက်’ ရှု။ || “မန္ဒော။ၚ်မဓီုဂှ်ဒှ်တုဲ။ ဝါ။ ၚ်လဒေက်ဂှ်ဒှ်တုဲ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “ပညာနုံ့သည်ဖြစ်၍။”')
,(12586,3,4,'ဥဝပ်သည်။','‘ဂဒပ်’ ရှု။')
,(12587,3,1,'အလယ်။','‘အဒေါဝ်’ နှင့်အတူတူ။ || “ညံၚ်ရဴဇြဲလဒေါဝ်ဝါဂှ်ကီု။” (လိက်ပရေၚ်ခန္ဓ) = “ကွင်းပြောင်အလယ်ရှိ ညောင်ပင်ကဲ့သို့။” || “လဒေါဝ်ၜဳဂှ်၊ က္ၜၚ်ထပှ်ပၠန်။” (လိက်မၚ်ဗၠာဲဟောံလွဳ)')
,(12588,3,4,'ဖုံးသည်။','‘ဂဒဵု’ ရှု။')
,(12589,3,4,'အော်မြည်သည်။','“ဝုတ်အဵုလဒိုဟ်၊ မိၚ်ဂြိုဟ်ညံၚ်ချဳ။” (လိက်ပဒုမဝတဳ) =“မျောက်လွှဲကျော်အော်မြည်သည်ကိုကြား၍ နှလုံးတုန်သကဲ့သို့ဖြစ်၏။”')
,(12590,3,1,'ပဟေဠိ။ စကားထာ။','အရေဝ်လဒိုဟ် = စကားထာ။')
,(12590,3,4,'စကားထာဝှက်သည်။','“အဲလဒိုဟ်ဗှ်ေမွဲသာ် ဗှ်ေသှ်ဒးဟာ။” = “နင့်ကို တစ်ခုစကားထာဝှက်၍ ငါမေးမည်။နၚ်ဖြေနိုင်မလား။”')
,(12591,3,16,'ညင်သာစွာ။ ကြင်နာစွာ။','“ဂၞကျာ်ဖဳဒွါ၊ ခါသၟိၚ်မညာတ်။ မိန်လဝ်လဒိုဟ်၊ ပ္ဍဲသြိုဟ်ခပ်ပြာတ်။” (လိက်ရတနပဇ္ဇောတ) = “ပူပန်နေသောမိဖုရားကို မင်းမြင်သောအခါ ကြင်နာစွာပွေ့ပိုက်၍ ရင်ခွင်­မြဲစွာထား၏။”')
,(12592,3,1,'အရိပ်အခြည်။ အရိပ်အကဲ။',NULL)
,(12593,3,4,'လမ်းညွှန်သည်။ လမ်းပြသည်။','“ညံၚ်ပၞာၚ်တိုၚ်ဇၞော် မပျးလျးကဵုညးမနွံဂၞပ်ကုလျးကီု (ညးရသၟာန်စိုပ်) မှတ်သှ်လဒိုဟ်ပ္ညုၚ်ကဵုညးညိ။” (ဇ—၈၄။ အစွောံ။) = “မီးရှူးတိုၚ်ကြီးသည်အလင်းရောင်ကို အလိုရှိသောသူအား အလင်းရောင်ပေးသကဲ့သို့ သူတစ်ပါးရောက်လာမေးမြန်းပါက မဖြစ်မနေ ဖြေဆိုလမ်းပြပေးပါလေ။” || “အ္စာသၟိက်ကဵုစဳကၠးတုဲ— ပ္တိတ်ဒြဟတ်ပကေၚ်ပကတ်လဒိုဟ်ပ္ညုၚ်တဴကီုဂှ်လေဝ် (ဟိုတ်ကွးဂှ်ဂဒိုက်ညာန်တုဲ) ဟွံညာတ်ဒတုဲဖဵုညိသက်က်။” (ဇ—၁၂၃။အစွောံ။) = “ဆရာက တပည့်အား လိမ္မာတတ်သိစေလို၍ အားထုတ်၍ လေ့ကျင့်သင်ကြားလမ်းညွှန်ပေးငြားသော်လည်း တပည့်သည် ညာဏ်နုန့်နှေးသောကြောင့် အနည်းငယ်သော အကျိုးဖြစ်ထွန်းမှုကိုမျှ မမြင်ရ။” || “လဒိုဟ်ပ္ညုၚ်ဥပ္ပါယ်ဒွးကဵုညးတုဲ ပ္တန်လဝ်တသိုက်ညးညိ။” (ဇ—၁ဝ၉။ အစွောံ။) = “သူတစ်ပါးအား မှန်ကန်သောအကြောင်းဥပါယ်ကို လမ်းပြညွှန်၍ ချမ်းသာသုခ­ တည်ထားပါလေ။”')
,(12594,3,4,'သာယာစွာမြည်သည်။ (ကျေးငှက်) မြည်ကြွေးသည်။ သာယာသောအသံဖြင့်ပြောဆိုသည်။','“ဂစေံဍေဝ်ကၠိုက်ဂဂီုမြာ်ကွဴ ဂြဴကြီုလဒိုဟ်လဒဲါ—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “တောကြက်၊ ရစ်၊ ချိုးစိမ်း၊ ဒေါင်း၊ ဥသြစသောငှက်များ တွန်ကျူးမြည်ကြွေးနေကုန်၏။” || “ဇၞတ်မဗဵုအာ၊ ၜါဍိက်ကဵုနာဲ။ လဒိုဟ်လဒဲါ၊ မိဂၠာဲသၟာန်ပၠန်။” (လိက်ပဒုမဝတဳ) = “ကျွန်နှင့်သခင်နှစ်ဦးသားတို့သည် ကြည့်ရင်းသွားရင်း သခင်မသည် သာယာစွာသောအသံဖြင့် ပြောဆိုရှာကြံမေးမြန်း၏။” || “ပေဝ်ထဍေဝ်ၜိုဟ်၊ လဒိုဟ်လဒဲါ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ခရာစည်းဝါးသံတို့သည် နားမှာအေး၍ သာယာစွာမြည်၏။”')
,(12595,3,1,'အဘိုးကြီး။',NULL)
,(12596,3,4,'‘ရနုက်’ ရှု။',NULL)
,(12597,3,4,'‘လၞၚ်’ ရှု။',NULL)
,(12598,3,1,'စွန်ငှက်။','‘လၞေၚ်’ ရှု။')
,(12599,3,4,'‘လၞိန်’ ရှု။',NULL)
,(12600,3,4,'‘လၞိန်ဗပိန်’ ရှု။',NULL)
,(12601,3,9,'တားမြစ်ခြင်းကိုပြသော ကြိယာရှေ့ဆက်စကားလုံး။','လ္ပအာ = မသွားနှင့်။ || လ္ပစ =မစားနှင့်။ || လ္ပဖေက် = မကြောက်နှင့်။')
,(12602,3,1,'ပေ။ ပေတုံး။ (ပန်းပဲ၊ ပန်းထိမ် စသည့်လုပ်ငန်း­သုံးသော ထုရိုက်ရာအောက်ခံသံတုံး။) (ပါဠိ—အဓိကရဏဳ)','“လပးမွဲ တြုံတၠဇြဟတ်မထ္ၜလဝ်မာန်ဂှ်လေဝ် ကေတ်နၚ်မွဲ။” (ဇ—၃၈၇။ အစွောံ။) = “ခွန်အားကောင်းသောယောကျာ်း ပင့်ထားနိုင်သော ပေတုံးတစ်ခုကို ယူလာပါ။”')
,(12603,3,1,'၁။ ဘက်တစ်ဘက်။','သြၚ်လ္ပာ်တေံ = ဟိုမှာဘက်ကမ်း။ || သြၚ်လ္ပာ်ဏအ် =ဤမှာဘက်ကမ်း။')
,(12603,3,1,'၂။ တစ်ပိဿာ၏တစ်ဝက်။ ငါးဆယ်သား။',NULL)
,(12603,3,1,'၃။ တစ်ဝက်။ ထက်ဝက်။','လပါ်ဂိတု = လဝက်။ လခွဲ။')
,(12604,3,1,'တောင်ကမ်းပါးပြတ်။',NULL)
,(12605,3,4,'ဖွင့်သည်။ ပွင့်သည်၊ (ဖုံးကွယ်ရာမှ) ပေါ်သည်။','“ဗြဴကျာ်သြဳဍုၚ်ဂှ် ထ္ၜးဥပ္ပဲါဗြဴကဵုတြုံဂှ်ညိဂးတုဲ က္တဵုဗဒှ်ဂရိုၚ်ဂအီ ၚေက်လ္ပံက်အာရ။” = “ထိုပြည့်တန်ဆာမသည် ထိုယောကျာ်းအား မိန်းမတို့၏စမ္ပယ်ခြင်းကိုပြအံ့ဟု ပြုံးရယ်ခြင်းကိုပြုရာ သွားပေါ်သွား၏။” || “ဟာဲဗဂေါဝ်၊ — ဗှ်ေလပံက်လဝ်ဂၞေဟ်တုဲ ဗှ်ေသတိက်ဂှ် မူသတြုမွဲ မကၠုၚ်စိုပ်ရော။” (ဇ—၁၆၅။ အစွောံ။) = “အိုမြွေပါ၊ သင်သည် အစွယ်ကိုဖွင့်လျက်အိပ်၏။ အဘယ်မည်သောရန်သူသည် လာရောက်ပါသနည်း။” || “သၟိၚ်လ္ပံက်ကၠေံဗတၚ်ကျာပြာသာဒ်။” (ဇ—၅၁၄။ အစွောံ။) = “မင်းသည် နန်းတော်ပြာသာဒ်၏ လေသာပြတင်းကို ဖွင့်လိုက်၏။” || “အမာတ်ကဵုလပံက်ကၠေံတရၚ် (ဍုၚ်) တုဲ—။” (ဇ—၃ဝ၁။ အစွောံ။) = “အမတ်သည် မြို့တံခါးကို ဖွင့်စေပြီးလျှင်—။”')
,(12606,3,1,'၁။ မမြင်အပ်သောအရာ။ ဖုံးကွယ်အပ်သော ကိုယ်အၚ်္ဂါအစိတ်အပိုင်း။ မိန်းမအၚ်္ဂါဇာတ်။ ဝိသဘာဂအာရုံ။','“ဗွဲမပြဟ်ဂၞကျာ်က္တဵုနူသၞာတုဲဂှ် ဂ္ညိဂ္ညာတ်ဂၞကျာ်ဂှ် သရောဟ်သဏုဲအာ၊ လပံက်လမာဲဂၞကျာ်ဂှ် ဗောဓိသတ် (ဣသိ) ညာတ်တုဲ—။” (ဇ—၂၅၁။ အစွောံ။) = “မိဖုရားသည် ကမန်းကတန်းထလိုက်ရာ မိဖုရား၏အဝတ်တန်ဆာသည် လျှော၍ပြေကျသွား၏။ မိဖုရား၏ဖုံးကွယ်သောကိုယ်အၚ်္ဂါကို ဘုရားလောင်းရသေ့မြင်လေသော်—။”')
,(12606,3,1,'၂။ ချို့ယွင်းချက်။ အားနည်းချက်။ ဟာကွက်။ ပျော့ကွက်။ အပြစ်အနာအဆာ။ အခွင့်အပေါက်။ လစ်ဟင်းခြင်း။','ဒမံၚ်ဒတဴလပံက်လမာဲပၞာန်ညး (ဇ—၂၂၆။ အစွောံ။) = ရန်သူ့စစ်တပ်၏ အနေအထားနှင့် ဟာကွက်ပျော့ကွက်။ || “ကုသမၠီုမဟွံတီဂုန်ညး မပ္တုဲလဝ်ကုဇကုဂှ် မဂၠာဲသ္ၚဳဒၟံၚ်လပံက်လမာဲဒုဟ်ညးလၟိုန်။” (ဇ—၇၂။ အစွောံ။) = “မိမိအားပြုအပ်သောကျေးဇူးကို မသိတတ်သောသူမိုက်သည် (ကျေးဇူးရှင်၏) အပြစ်အနာကိုသာ အမြဲရှုာလေ့ရှိ၏။” || “(ဗမၞးဂှ် ဒက်လဝ်ဝဲပ္ဍဲစန္ဒကုမာတုဲ) ဍေံဂၠာဲၚဳတဴလပံက်လၟာဲဒုဟ်စန္ဒကုမာရ။” (ဇ—စန္ဒကုမာ။ အစွောံ။) = “ထိုပုဏ္ဏားသည်စန္ဒကုမာအား ရန်ငြိုးဖွဲ့၍ (ဒုက္ခပေးရန်) အခွင့်အပေါက်ကို ရှာလျက်နေ၏။” || “ယွံသၟိၚ်တံညးဂမၠိုၚ်၊ ယာံညးတံဂွံသၟဟ်သၟန်ကေုာံရၚ်သ္ကံတုဲ ညးသ္အာၚ်တေံဂှ် တၞဟ်နညာတ်လပံက်လမာဲသ္ဂောံစၞေဟ်ဂှ် ဟွံသၟဟ်ရထရ။” (ဇ—၅၃၆။ အစွောံ။) = “မင်းအပေါင်းတို့၊ သင့်တင့်ညီညွတ်ကုန်သောသူတို့အား တစ်ပါးသောသူတို့သည် တိုက်ခိုက်ရန် ပျော့ကွက်ဟာကွက်ကို မမြင်နိုင်။” || “ယွံမၞးတံ၊ ပွသမဏဂေါတမ မလုတ်အာကဵုသုန္ဓရဳတုဲ ဖေက်ညးတီအာလပံက်လမာဲဂှ်တုဲ ကဵုၜုၚ်ဂစိုတ်ကၠေံသုန္ဓရဳတုဲ ကဵုကွးတိုပ်လဝ်ပ္ဍဲဇမြပ္ကဴ ဇိုၚ်ကၟာၚ်ဘာဇေတဝန်ဂှ်ရောၚ်” အ္စာတဳတံဂး။ (ဇ—၂၈၅။ အစွောံ။) = “အချင်းတို့၊ ရဟန်းဂေါတမသည် သုန္ဒရီနှင့်တကွ လွန်ကျူးပြီးလျှင် ထိုအပြစ်အနာကို သူတကာတို့သိသွားမည်စိုး၍ သုန္ဒရီအား ရိုက်သတ်စေပြီးနောက် ဇေတဝန်ကျောင်းတံတိုင်းအနီး ပန်းအမှိုက်ကြား­ တပည့်တို့ကို မြှုပ်စေ၏” ဟုတိတ္ထိတို့ဆိုကုန်၏။ || “လပံက်လၟာဲမၞးတံဟွံမွဲတုဲ ဍေံဂြိုဟ်ကဵုမၞးတံ ဟွံသၟဟ်ရထရ။” (ဇ—၄၃၇။ အစွောံ။) = “သင်တို့၏ပျော့ကွက်အားနည်းချက်မရှိသဖြင့် ရန်သူသည် သင်တို့အား မနှိက်စက်နိုင်။”')
,(12606,3,1,'၃။ ဖောက်ပြန်ခြင်း။မူမမှန်ခြင်း။ (ပါဠိ—ဝိကာရ)','လပံက်လမာဲဣန်ရဳ = ဣန္ဒြေဖောက်ပြန်ခြင်း။ (ပါဠိ—ဣန္ဒြိယဝိကာရ/ဣန္ဒြိယဝိပ္ပကာရ)')
,(12607,3,4,'ဟင်းလင်းပွင့်သည်။',NULL)
,(12608,3,4,'လှစ်ဟဖွင့်ပြသည်။','“(သၟတ်ကောန်ဗြဴသၟိၚ်ဂှ်) ဂရောပ်ယာတ်ကြာထဝ်မစိစောန်ဂှ် ဖာဲကၠေံတုဲ လပံက်လအာ်ကၠေံဒဳက္ၜံၚ်တုဲ ဟွံဂွံဂြောပ်ဗဒန်ဇကုရ။” (ဇ—၅၂၆။ အစွောံ။) = “ထိုမင်းသမီးသည် ဆန်းကြယ်စွာသော ရွှေပြားစီသောအဝတ်ကို ဖယ်ရှား၍ ဒူးပေါင်တို့ကိုလှစ်ဖွင့်လိုက်ကာ ကိုယ်အၚ်္ဂါကို မဖုံးကွယ်တော့။”')
,(12609,3,1,'နှုတ်ဖွင့်ဟခြင်း၊ မျက်စိဖွင့်၍ကြည့်ခြင်း။ အဖွင့်အကြည့်။','“ၜိုန်စံၜတ်တဴ (သၟတ်တေမဳ) ကီု လပံက်လမၠာ် ညိညဟွံဂွံဟေၚ်။” (ဇ—တေမဳ။ အစွောံ။) = “တေမိယသူငယ်ကို အမျိုးမျိုးစမ်းသော်လည်း အနည်းငယ်သော အဖွင့်အကြည့်ကိုမျှလည်း မရလေကုန်။”')
,(12610,3,4,'၁။ ဆောင့်သည်။ တိုက်သည်။ ပုတ်ခတ်သည်။','“ဇမောဝ်ဍာ်ဇီုလပိုက်ဂၠိုၚ်တုဲ သြၚ်ဂှ်လာ်အာရ။” = “ရေစီးကြောင်းတိုက်ခတ်ပါများ၍ ကမ်းပြိုသွားသည်။” || “(စိၚ်ဂှ်) ဍေံလပိုက်ဂစိုတ်ကၠေံဂၟာစိၚ်ရောၚ်။” (ဇ—၂၆။ အစွောံ။) = “ထိုဆင်သည် ဆင်ထိန်းအား ပုတ်ခတ်သတ်ပစ်လိုက်၏။” || “(လၟာဲဂှ်) ဍေံရပ်ကေတ်ဗတဗောဓိသတ် (သၟိၚ်နာ်) တုဲ ဍေံလပိုက်ရ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “အလမ္ပာယ်သည် ဘုရားလောင်းနဂါးမင်း၏ အမြီးကိုကိုင်၍ ဆောင့်ရိုက်ပုတ်ခတ်၏။”')
,(12610,3,4,'၂။ လျှော်ဖွပ်သည်။','လပိုက်ပလောအ် = အင်းကျီလျှော်ဖွပ်သည်။')
,(12611,3,4,'ဆောင့်အောင့်သည်။','“ကောန်ဗြဴဂှ် ထေဲကဵုမိတုဲ လပိုက်ကဆံၚ်ဒၟံၚ်ရ။” =“သမီးသည် မိခင်နှင့်စိတ်ဆိုးပြီး ဆောင့်အောင့်နေသည်။”')
,(12612,3,4,'သိမ်ကိုပယ်နုတ်သည်။ ပယ်ခွါနုတ်ပစ်သည်။ (ပါဠိ—သဳမာသမူဟန)','“သဘဴပွမလပိုက်သီမ္ဂးဝွံတုန်လေဝ် သ္ဇိုၚ်သ္ပသန်။” (သၠပတ်ဝၚ်သီသၟိၚ်ဓမ္မစေတဳ) = “သိမ်နုတ်ပယ်ခြင်းမည်သည်ကိုလည်း ပြုရန်ခဲယဉ်း၏။”')
,(12613,3,1,'ဆားချက်သောမြေအိုး။',NULL)
,(12614,3,1,'တူးမြောင်း။ (a canal)',NULL)
,(12615,3,1,'၁။ စင်ရော်ငှက်။ (ပါဠိ—အာဋိ','အာဍိ/စၚ်္ကောရ)')
,(12615,3,1,'၂။ အပွင့်များသောစံပယ်ပန်းတစ်မျိုး။',NULL)
,(12616,3,1,'၁။ လှိုင်း။','လပှ်ၜဳ = ပင်လယ်လှိုင်း။')
,(12616,3,1,'၂။ (ဆင်) နှာမောင်း။','လပှ်စိၚ် =ဆင်နှာမောင်း။')
,(12616,3,4,'ကောက်သည်။','“သတ်ကြေၚ်လမုဟ်တံဂှ် ဒတုံပြဟ်စှ်ေတုဲ ကၠဵုဂြိုပ်ဂှ် လပှ်စရ။” (ဇ—၂၉၄။ အစွောံ။) = “ကြွေကျသောသပြေသီးမှည့်တို့ကို မြေခွေးသည် ကောက်စား၏။”')
,(12617,3,1,'မြေငလျင်လှိုင်း။',NULL)
,(12618,3,1,'လေလှိုင်း။ ရေဒီယိုအသံလွှင့်သောလေလှိုင်း။',NULL)
,(12619,3,4,'(အစီအစဉ်မကျ ပြန့်ကြဲနေသည်များကို သူ့နေရာနှင့်သူ အစီအစဉ်တကျဖြစ်အောင်) ကောက်သိမ်းသည်။','“ကောန်ၚာ်တအ်ဝေၚ်ပရးလဝ်ဂှ် လပှ်ဂိုၚ်ထောံညိ။” = “ကလေးတွေ ဖွကစားထားသည်ကို ကောက်သိမ်းလိုက်ပါ။”')
,(12620,3,4,'(ကလေး) ကောက်ယူမွေးစားသည်။','“ကောန်ကွးဂှ်မွဲ ကောန်မလပှ်ဗစဂှ်မွဲ ကောန်မဒှ်နူဇကုဂှ်မွဲ ဣဝွံကောန်ပိသာ်ရ။” (ဇ—၅၁၈။ အစွောံ။) = “တပည့်သားလည်းတစ်ယောက်၊မွေးစားသားလည်းတစ်ယောက်၊ မိမိမှဖြစ်သောသားလည်းတစ်ယောက်၊ ဤသည်မှာ သားသုံးမျိုးတို့တည်း။”')
,(12621,3,1,'လက်ချောင်း။ ခြေချောင်း။',NULL)
,(12621,3,9,'တစ်လက်သစ်။','ပိလပုဟ် = သုံးလက်သစ်။ || “မိမတအ်ဂှ် မၚ်မွဲဝဳပရာကၠုၚ်ကောန် နူဂတာဇိုၚ်ၜါလပုဟ်ရ။” = “မိဘတို့သည် သားသမီးများကို ဖဝါးနှစ်လက်သစ်ကတည်းက မွေးမြူစောင့်ရှောက်လာခဲ့သည်။”')
,(12622,3,1,'ခြေချောင်း။',NULL)
,(12623,3,1,'လက်ချောင်း။','‘လပုဟ်တဲမသုန်တၞုၚ်။’ = ‘လက်ချောင်းငါးချောင်း။’')
,(12623,3,9,'တစ်လက်သစ်။','ပိလပုဟ်တဲ = သုံးလက်သစ်။')
,(12624,3,1,'လက်သူကြွယ်။ (ပါဠိ—အနာမိကာ)',NULL)
,(12625,3,1,'လက်ခလယ်။',NULL)
,(12626,3,1,'အိပ်မက်။',NULL)
,(12626,3,4,'အိပ်မက်သည်။',NULL)
,(12627,3,4,'အိပ်မက်မြင်မက်သည်။','“ပ္ဍဲဓဝ်မေထုန်ဂှ် ဆသွပ်လ္ပအ်ကီုလေဝ် အဲဟွံလ္ပအ်ညာတ်မွဲလှ်ေ။” (ဇ—၄၈၈။ အစွောံ။) = “အကျွန်ုပ်သည် အိပ်မက်ဖြင့်သော်လည်း မေထုန်အကျင့်ကို မမြင်မက်စဘူး။” (ညောင်ကန်)')
,(12628,3,4,'ချသည်။ ချထားသည်။','‘တဖဝ်’ ရှု။')
,(12629,3,4,'(ကဗျာသုံး) ဦးချသည်။ ဦးညွတ်သည်။',NULL)
,(12630,3,4,'အောက်မေ့သည်။ သတိရသည်။ ပြန်ပြောင်းတသသည်။','“(သၟိၚ်ဝေသန္တဝ်ကဵုဂၞကျာ်မဒ္ဒဳ) ထိုၚ်သးကြီုဒၟံၚ် ပ္ဍဲဒါန်ကောန်ၜါ လဖှ်ဗှ်သၞာဟွံဝိုတ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) =“ဝေဿန္တရာမင်းနှင့် မဒ္ဒီမိဖုရားတို့သည် သားသမီးအလှူ­ ချီးမွမ်းဥဒါန်းကျုး၍ မမေ့စတမ်း ပြန်ပြောင်းတသ အောက်မေ့ကြ၏။” || “ယြဴပူဂဵုမွဲ ဂလာန်မ္ဂးဗုဒ္ဓေါဗုဒ္ဓေါဂှ် ဂွံဟီုလဖှ်တဴရ။ ပ္ဍဲဇကုပူဂဵုမဟီုဂှ် ယြဴဓဝ်ပဳတိမွဲက္တဵုဒှ်ရ။ ဓဝ်ပဳတိဂှ် ပြဲလောန်—။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ဗုဒ္ဓေါဗုဒ္ဓေါဟူသောစကားကို အောက်မေ့ပြောဆိုသောသူသည် မိမိကိုယ်­ ပီတိဖြစ်ပေါ်၏။ ထိုပီတိသည် အလွန်မြတ်၏။”')
,(12631,3,4,'မြင်ဖူးကြားဖူးသည်တို့ကို ပြောဆိုသည်။ မြင်ခဲ့ကြားခဲ့ရသည်တို့ကို ပြောဆိုသည်။ အတိတ်အကြောင်း ပြန်ပြောင်းတသပြောဆိုသည်။','“ကောန်သေဋ္ဌဳပန် — ပ္ဍဲဋ္ဌာန်မညန်ကဵုတြဴဇၞော်ဂှ် ဂ္ဇံဒၟံၚ်တုဲ ဂၠာဲဟီုလဖှ်ဒၟံၚ်ကဵုရၚ်သ္ကံရ။” (ဇ—၃၁၅။ အစွောံ။) =“လေးယောက်ကုန်သောသူဋ္ဌေးသားတို့သည် — လမ်း၏အဆုံ­ (ထိုၚ်၍) တစုံတခုမြင်ဘူးကြားဘူးသည်တို့ကို ပြောဆိုကုန်လျက်နေကုန်၏။” (ညောင်ကန်) || “ပရိုၚ်သၟိၚ်သာဂလနာဂဵုဂှ်ကီု ပရိုၚ်လၟဂှ်ကီု (သၟိၚ်ၜိုပ်ထဝ်) ဟီုဂၠာဲလဖှ်အိုတ်တုဲ ၜိုပ်ဂမၠိုၚ်မိပ်စိုတ်။” (ဇ—၅၃၃။ အစွောံ။) = “ရွှေဟင်္သာမင်းသည် မြင်ခဲ့ကြားခဲ့ရသော သာဂလနဂိုရ်ပြည့်ရှင်မင်း၏ အကြောင်းသတင်းကို၄င်း၊ မုဆိုး၏အကြောင်းသတင်းကို၄င်း အလုံးစုံပြန်ပြောင်းပြောပြ၍ ဟင်္သာများဝမ်းသာကြကုန်၏။” || “ခမဳၜါဒှ်သဟာဲ — စှ်ေဟုံဍာ်ကြုၚ်အစဳရဝတဳတုဲ တိုန်ၜံၚ်တ္ၚဲပ္ဍဲဗတဳ ဟီုဂၠာဲလဖှ်တဴရ။” (ဇ—၂၇၆။အစွောံ။) = “(အဆွေခင်ပွန်းဖြစ်ကုန်သော ရဟန်းနှစ်ယောက်တို့သည်) အစီရဝတဳမြစ်သို့သွား၍ရေချိုး၍ သဲပြၚ်­ နေပူခံကုန်လျက် အသက်ထက်ဆုံး အောက်မေ့အပ်သော စကားကိုပြောဆို၍နေကြကုန်၏။” (ညောင်ကန်)')
,(12632,3,4,'ကြံအောက်မေ့သည်။ ဆင်ခြင်အောက်မေ့သည်။','“ယွံကောန်သ္ဍိုက်အဲ၊ ဒုဟ်ကောန်ဂှ် အဲမဂၠာဲဂၠိုက်လဖှ်ဗၞုဟ်ဂှ် ဟွံညာတ်မွဲရ။” (ဇ—၅၁၃။ အစွောံ။) = “ချစ်သား၊သင်၏အပြစ်ကို ငါရှာကြံအောက်မေ့သော်လည်း တစ်စုံတစ်ခုသောအပြစ်ကိုမျှ မတွေ့။” || “ယွံမၞးတံ၊ နဓဝ်မေတ္တာဘာဝနာဂှ် သီုဓဝ်သတိ အဲမလဖှ်ဗှ်ဒၟံၚ်သၞာရောၚ်သွံ။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “အချင်းတို့၊ ငါသည် မေတ္တာဘာဝနာကို သတိတရားဖြင့် ဆင်ခြင်အောက်မေ့လျက်နေသည်တကား။”')
,(12633,3,4,'ဟိုဟိုဒီဒီမေးမြန်းသည်။ သိလိုရာရာ မေးမြန်းသည်။','“ထေသၟာန်လဖှ်၊ ကျာ်တြဲတွံတုန်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “သိလိုရာရာ မထေရ်မေးမြန်းသည်ကို မြတ်စွာဖြေကြားတော်မူ၏။”')
,(12634,3,1,'၁။ ညီညာသောမြေမျက်နှာပြင်။ မြေပြန့်။','‘လဗးဂြိုပ်ဝါ။’ = ‘မြေပြန့်တောအရပ်။’ || “ဂၠံၚ်ထာန်လဗး။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ညီညာသောလမ်းခရီး။” || လဗးပထဝဳ =မြေပြန့်ဒေသ။')
,(12634,3,1,'၂။ အခြံအရံ။ ခြွေရံသင်းပင်း။','“ပိစှ်ောၜါပၠန်၊ ရးဍုၚ် (မန်) ခန်လွာ။ —၊ သ္အဳဗ္ဂာတ္ၜန်တ္ၜောဲ၊ ကၠံမွဲဘာသာ။ ဂၠိုၚ်ကဵုလဗး၊ ဇၞော်ကၠးအညာ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “မွန်ပြည်သုံးဆဲ့နှစ်မြို့သည် တစ်ရာ့တစ်ပါးကုန်သော လူမျိုးဘာသာတို့ဖြင့် ပြည့်နှက်ရောပြွမ်းလျက် များစွာသောအခြံအရံတို့နှင့်တကွ ကြီးကျယ်ကျော်ကြား၏။”')
,(12635,3,4,'၁။ (ဘေးပတ်လည်သို့) ပြန့်ထွက်သည်။ ဖြာထွက်သည်။ အနှံ့လိမ်းကျံသည်။','“(ကအနန်ဂှ်) ဆီဗတဂှ်တိတ်လဗးအာတုဲ ကဂမၠိုၚ်ဂွံအမြာဲဆီဂှ်တုဲ ဟွံတီကဇၞော်သၟတ် ဟုပ်ကၠုၚ်တုဲ ဗိုၚ်ကိတ်စ (အိုတ်ရ) ။” (ဇ—၅၃၇။ အစွောံ။) = “ထိုငါးကြီးအာနန္ဒာ၏ အမြီးမှထွက်သောသွေးသည် ဘေးပတ်လည်အနှံ့ပြန့်ထွက်၍ ငါးအပေါင်းတို့သည် ထိုသွေးနံ့ရသည်ရှိသော် ငါးကြီးငါးငယ်မဟူ ဝိုင်းအုံလာ၍ ထိုငါးကြီးကို ဝိုင်းကိုက်စားကြကုန်၏။” || “(သုဝဏ္ဏသာံဒးကံလဴဂျိတုဲ) ဆီလဗးဒၟံၚ်အလုံဇကုရ။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “သုဝဏ္ဏသာမသည် မြားချက်ထိမှန်၍ကိုယ်လုံးအနှံ့ သွေးတို့ဖြင့်လိမ်းကျံနေ၏။” || “လျးကျာ်တြဲရ၊ ဒြေပ်ထလၟော။ လုံဍုၚ်လဗး၊ ဂဵုစလးဟော။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “မြတ်စွာဘုရား၏ရောင်ခြည်တော်တို့ ဖြာထွက်သည်ရှိသော် မြို့လုံးအနှံ့ပြန့်၍ လင်းထိန်သွား၏။”')
,(12635,3,4,'၂။ ထိစပ်ရောယှက်သည်။ ပြည့်ယှက်သည်။','“ပၞဴခတိုက်၊ သတ်ပရိုက်ကၠာ။ တၞးကဵုတၞး၊ လဗးရေၚ်ဗ္ဂာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “သံပုရာသီးရှောက်သီးတို့သည် အတွဲလိုက်သီးကုန်၍ အရွက်အရွက်ချင်း ထိစပ်ရောယှက်စီတန်းနေ၏။”')
,(12636,3,1,'၁။ ပူဇော်ပသသောပွဲ။','“ဣစဳအာပေဲါယူကဏာ ဂွံဖျဴနၚ်မွဲလဗံက်ကီုဟာ။” = “အဒေါ်ကြီး နတ်ကပွဲသွားတာ အပြန်မှာ (အုန်းငှက်ပျော) တစ်ပွဲ ရခဲ့ပါသလား။”')
,(12636,3,1,'၂။ စားပွဲခုံ။',NULL)
,(12637,3,1,'အပျော်အပါးလိုက်စားလွန်း၍ ပျက်စီးသူ။ မကောင်းသောအမှုတစ်ခုခုတွင် အပျော်ကြူးသောသူ။ အကျင့်ပျက်သောသူ။ (ပါဠိ—ဓုတ္တ)','“အဲမၞုံကဵုစိုတ်စၞာဲ ယြဴတြုံမွဲမဒှ်လဗၚ်ဂှ် အဲသ္ဒးဂၞပ်ထဏေန်စိုတ်တုဲ သိပ်ဂၠိပ်ရ” ဒေဝတဴဗြဴဂှ်ဂး။ (ဇ—၃၈၂။ အစွောံ။) = “ငါသည် ကောက်ကျစ်သောစိတ်ရှိ၍ အကျင့်ပျက်သူယောကျာ်းကို နှစ်သက်တပ်မက်၍ မှီဝဲဆည်းကပ်၏” ဟုထိုနတ်သမီးဆို၏။ || “ဗြဴတံလဗၚ်ရောၚ် တၠအဲဟီုဂှ် ဒှ်ကွေံရ။” (ဇ—၅၃၆။ အစွောံ။) = “မိန်းမတို့သည် အကျင့်ပျက်သူများဟု သၚ်ဆိုသည်မှာ မှန်လှ၏။” || “ဟာဲဣဗြဴကမၠတ်တံ၊ ဟာဲဣဗြဴလဗၚ်တံ၊ ဟာဲဣဗြဴစိုတ်ကၞုဲတံ၊ ဗှ်ေတံဒှ်ဗြဴဒွိုက်ရောၚ်။” (ဇ—၅၃၆။ အစွောံ။) = “ဟယ်သူခိုးမတို့၊ ဟယ်မိန်းမပျက်တို့၊ ဟယ်မျောက်စိတ်ရှိသောမိန်းမတို့၊ သင်တို့ကား မိန်းမယုတ်များပင်တည်း။” || “ကွေတ်ဒ္ဂေတ်လဗၚ်ပးစာၚ်ခတ်၊ လဗၚ်ဗြဴ၊ လဗၚ်သုရာတံဂှ် တၠပညာတံဂှ် ဗျိလောန်ရ။” (ဇ—၅၂၁။ အစွောံ။) = “ကြွေအန်ကြက်တိုက်ကြူးသူ မိန်းမကြူးသူ အရက်သောက်ကြူးသူ အစရှိသောသူတို့၏အကျင့်ကို ပညာရှိတို့သည် ကဲ့ရဲ့ကုန်၏။” || “လ္ပာ်ဗြဴလဗၚ်ဂှ် ပိုဲဟွံရီုရ။” (အကြီုရာဇာဓိရာဇ်) = “ထိုမိန်းမပျက်ဘက်ကို ငါတို့မကူ။”')
,(12638,3,1,'သေသောက်ကြူး။ အရက်သေရည်ကို အလွန်အမင်းသောက်သုံးလေ့ရှိသူ။ အရက်သမား။','“အ္စာတဳတံ ကဵုကသာပ်ကဵုလဗၚ်သမုၚ်တံဂှ်တုဲ (ကဵုဍေံတံအာၜုၚ်ဂစိုတ်ကၠေံ သၟတ်ဗြဴသုန္ဓရဳဂှ်ရ။)” (ဇ—၂၈၅။ အစွောံ။) = “(တိတ္ထိတို့သည်) သေသောက်ကြူးတို့အား အသပြာပေး၍ သုန္ဒရီကို (ရိုက်သတ်ပစ်စေ၏။)” (ညောင်ကန်) || “လဗၚ်သမုၚ်တံကၠုၚ်ရာန်သုရာ။” (ဇ—၄၇။ အစွောံ။) = “အရက်သမားတို့ အရက်လာဝယ်၏။”')
,(12639,3,1,'မိန်းမများနှင့် ရှုပ်ပွေအပျော်ကြူးသောယောကျာ်း။','“လဗၚ်ဗြဴလဗၚ်ပးတံဂှ်ကီု သမုၚ်ဍာ်တာ သမုၚ်သုရာတံဂှ်ကီု။” (ဇ—၃၁၇။ အစွောံ။) = “မနှင့်အပျော်ကြူးသူကြွေအန်လောင်းကစားကြူးသူတို့သည်၄င်း ထန်းရည်သမား အရက်သမားတို့သည်၄င်း။”')
,(12640,3,1,'ယောကျာ်းများနှင့် ရောယှက်ရှုပ်ပွေ၍ အပျော်ကြူးသောမိန်းမ။','“ဗြဴလဗၚ်တြုံဂှ် အဲစဴနူဏအ်တုဲ အဲဂေက်တက်တုဲ အဲဗက်ထောံကၠေံဍေံရ” ဗမၞးချပ်။ (ဇ—၁၉၁။အစွောံ။) = “ယောကျာ်းတကာတို့နှင့် အပျော်ကြူးလေ့ရှိသော ဤမိန်းမပျက်အား ငါအိမ်ပြန်ရောက်လျှင် ရိုက်ပုတ်၍ အိမ်မှနှင်ထုတ်ပစ်အံ့” ဟုပုဏ္ဏားကြံ၏။')
,(12641,3,1,'ကြက်တိုက်ခြင်းဖြင့် အချိန်ကုန်သောသူ။ ကြက်တိုက်သမား။',NULL)
,(12642,3,1,'ကြွေအန်လောင်းကစားကြူးသူ။ (ပါဠိ—အက္ခဓုတ္တ)',NULL)
,(12643,3,1,'ညစ်ညမ်းသောစိတ်။ ဖောက်ပြားသောစိတ်။ အကျင့်ပျက်နှင့်ယှဉ်သောစိတ်။','ဗမၞိဟ်ဗြဴနွံတဴကဵုစိုတ်လဗၚ်။” (ဇ—၁၉၁။ အစွောံ။) = “ထိုပုဏ္ဏေးမသည်ကား အတန်ငယ်ပျက်သောအကျင့်နှင့်ယှဉ်၏။” (ညောင်ကန်)')
,(12644,3,4,'ဖောက်ပြားသောအကျင့်ကို ပြုကျင့်သည်။','“ဗမၞိဟ်ဗြဴ သမ္ဘာဗမၞးဂှ် ဍေံဝဵုမတ်ဗမၞးဍေံပလဗေၚ်ရောၚ်။” (ဇ—၁၉၈။ အစွောံ။) = “ပုဏ္ဏား၏ဇနီး ပုဏ္ဏေးမသည် ပုဏ္ဏားအားလှည့်စား၍ ဖောက်ပြားသောအကျင့်ကိုကျင့်၏။”')
,(12645,3,1,'ရက်၊ လ၊ နှစ်ကိုဖော်ပြသောဇယား။',NULL)
,(12646,3,1,'၁။ သစ်ပင်၏အကိုင်းကြီး။',NULL)
,(12646,3,1,'၂။ မတ်စောက်သောကျောက်ဆောင်ကမ်းပါး။',NULL)
,(12647,3,4,'ဝန်းရံသည်။ ပြိုၚ်တူဖြစ်သည်။ အပြိုၚ်ဖြစ်သည်။','“ဒပ်ပၞာန်လ္ဂန်အိန်ကဵုဒပ်ဥပါကံၚ် ဇက်လောန်တိုန်အာ ဂပ်မသ္ၚောဲ၊ ဒပ်တၠညး သီုဒပ်ဒကိုပ်ပၞာန်ဂမၠိုၚ် ဇက်လဗာၚ်တိုန်ဍိုန်န်။” (အကြီုရာဇာဓိရာဇ်) = “လဂွန်းအိန်တပ်နှင့်ဥပါကောင်းတပ်တို့ အတော်ဝေးအောင် ချီတက်လွန်သွားပြီးနောက် ဘုရင်ရာဇာဓိရာဇ်တပ်နှင့်တကွ စစ်အကြီးအကဲများ၏တပ်တို့သည် ဖြည်းဖြည်းနှေးနှေး ပြိုၚ်တူဝန်းရံချီတက်သွားကြ၏။” || “က္ဍိုၚ်ဇၞောဝ်သြံက်ဗျာံ၊ အလာံသဝှဝ်။ ဍောၚ်ပ္ကဴထဝ်ဗျာၚ်၊ ရေၚ်လဗာၚ်လဝ်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “ထီးတံခွန်တို့ကိုစိုက်ထူလျက် အလံတို့သည်လည်း လေထဲတွင်လွင့်ဝဲနေ၏။ ရွှေပန်းပွင့်တို့ကိုလည်း စီရရီအပြိုၚ်စီတန်းထားကုန်၏။” || “စိၚ်ဗောဓိသတ်၊ တြုံကၞောတ်သာ။ ဒစာံစှ်ောလ္ၚီ၊ ခပ်သီပြဝါ။ မွဲဟာန်ဍီုဍီု၊ သီုစိၚ်ဗြဴၜါ။ သ္ကဲသတုံဇွိ၊ ဒမၠိဟွံခြာ။ လဗာၚ်လုပ်အာ၊ ဂြိုပ်မာလာရ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ဘုရားလောင်းဆင်မင်းသည် ရှစ်သောင်းကုန်သော လက်ဝဲလက်ယာ အခြံအရံဆင်များနှင့်အတူ နှစ်ခုသောဆင်မိဖုရားတို့နှင့်တကွ စုံစုံညီညီ ပန်းတောသို့ အပြိုင်ဝင်သွားကြကုန်၏။” || ‘ဂဗာၚ်’ (ကြိ) လည်းရှု။')
,(12648,3,1,'အရပ်အမောင်း။ အလုံးအထည်။ အလုံးအဖန်။ (?)','“ပါရမဳပြေၚ်၊ တၟေၚ်နူစိၚ်သ္အာၚ်။ ဇၞော်သၠုၚ်လဗာၚ်၊ နွံသာၚ်ဇြဟတ်။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ပါရမီကြောင့် (ဆဒ္ဒန်ဆင်မင်းသည်) အခြားဆင်များထက်ထူး၏။ အရပ်အမောင်း အလုံးအဖန်ကြီး၍ခွန်အားအစွမ်းနှင့်ပြည့်စုံ၏။”')
,(12649,3,4,'၁။ (ချစ်သူတို့) ကြင်နာပေါင်းဖက်သည်။','“ယဝ်စုတိအာ၊ ပိုဲညးၜါသွံ၊ ကဵုဂွံလဗိၚ်။” (ဇၟန်လိက်မန်တြေံတြဟ်) = “အကယ်၍သေသွားသည်ရှိသော် ငါတို့နှစ်ဦးသည် (ဘဝတစ်ပါး­) ကြင်နာပေါင်းဖက်ရပါစေသတည်း။”')
,(12649,3,4,'၂။ (သုခချမ်းသာကို) မွေ့လျော်စံစားသည်။','“စဟွံဒးဂွိၚ်ကဵုဂွံသိုခ်သၠိၚ် လဗိၚ်သုခ။” (ပြကိုဟ်မ္ၚိုလ်ပိစှ်ောဒစာံ) = “စားဝတ်နေရေးအတွက် မပူပၚ်ရဘဲစည်းစိမ်ချမ်းသာကို မွေ့လျော်စံစားရပါစေသတည်း။” || “ကျိုၚ်ကျဝ်လဗိၚ်၊ သၟိၚ်ကဵုဗြဴသွဝ်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “အလှပြင်ဆင်ယင်၍ မင်းနှင့်တကွ နတ်သမီးနှင့်တူသောမိဖုရားများသည် သုခချမ်းသာကို မွေ့လျော်စံစားကြကုန်၏။” || “ဖိုလ်ဒါန်ဂှ်ပ္ညုၚ်၊ ချိုတ်ဂွံဍုၚ်သွဝ်။ တိုန်ဂွံဗဵုဒ္ၚောဝ်၊ သွဝ်တာဝတိၚ်။ ကယျိုၚ်ညးသွဝ်၊ ကျိုၚ်ကျဝ်လဗိၚ်။ ဂွံတိုန်သိုက်လှိၚ်၊ သမၞိၚ်ကြက်လှဴ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) || “ဂၞကျာ်ကဵုသၟိၚ်၊ လဗိၚ်မွဲဖုန်။” (လိက်သၟိၚ်ဇဲယဒတ္တ) =“မိဖုရားနှင့်မင်းတို့သည် တစ်ခုတည်းသောမွေ့ရာ­ အတူမွေ့လျော်ကြ၏။”')
,(12650,3,4,'‘သ္ဍံက်လဗိၚ်’ (ကြိ) နှင့်အတူတူ။','“ညးၜါသၟဟ်သၟန်၊ တန်မွဲသၞာ။ လဗိၚ်သဍံက်၊ဟီုဇီုချံက်ချာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။)')
,(12651,3,1,'ရွှ့ံညွန်။','“ဒှ်ဒၟံၚ်ဂြိုပ်လဗေၚ်သရီုသ္ဇိုဟ်နက်။” (အကြီုရာဇာဓိရာဇ်) = “နက်သောရွှံ့ညွန်တောဖြစ်နေ၏။”')
,(12652,3,1,'မုန်တိုင်း။','လဗိုတ်ကျာ = လေမုန်တိုင်း။')
,(12652,3,4,'ပစ်သည်။','“ကၞုဲနွံလ္တူကၞာၚ်ဆုဂှ်ဗြာတ်မွဲမ ညးလဗိုတ်ပ္တိုန်ဏာကဵုကၞုဲဂှ်ရ။” = “သစ်ကိုင်းပေါ်ရှိမျောက်ကို ငှက်ပျောသီးတစ်လုံးသူပစ်တၚ်ပေးလိုက်သည်။”')
,(12653,3,4,'ပြည့်စုံသည်။ တင့်တယ်သည်။ (?)','“မိဗောဓိသတ်၊ ကၞတ်ကျာ်သြဳ။ လျးထဝ်အရံၚ်၊ ရုပ်ညံၚ်ဗစဳ။ တ္ၜတ်လကတ်ပ္ညဳ၊ ကျာ်သြဳလဗာန်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ဘုရားလောင်း၏မိခင်သည် အထွတ်အခေါင်ကျက်သရနှင့် ရွှေရောၚ်ရုပ်အဆင်းဝင်းပလျက် အလွန်တင့်တယ်လှပါပေ၏။”')
,(12654,3,4,'ခိုင်မြဲအောင်လုပ်သည်။ အခိုင်အခံ့ပြုသည်။','‘ချေံဒမြိုဟ်ဂှ် ညးဒက်လဗိုန်လဝ် နကဵုဇုက်ရ။’ = ‘မြင်းဆိုးကို ကြိုးဖြင့်ခိုင်မြဲစွာ ချည်နှောင်ထားသည်။’ || “တၞဟ်နတဝ်စၞေဟ်ကဵုဗဵုပၞာန်သတြုဂှ် သၟိၚ်ဗာရာဏသဳ မၚ်မွဲလဗိုန်လဝ်ဍုၚ်ရ။” = “ရန်သူစစ်တပ်နှင့် ယှဉ်ပြိုင်တိုက်ခိုက်ရန်ဗာရာဏသီမင်းသည် မြို့ကိုအခိုင်အခံ့ပြု၍ စောင့်ကြပ်လျက်နေ၏။” || “ကေုာံညးမၞုံသ္ဇိုၚ်ဗၞိက်တိုက်ကီု (ညးမၞုံသ္ဇိုၚ်ဗၞိက်က္ၜၚ်ကီု) မၚ်ဗၠာဲဒက်မိတ် လဗိုန်လဝ်ဒဒှ်ေဒယှ်ရ။” (ဇ—၄။ အစွောံ။) = “လုလင်သည် ကြည်းကြောင်းအမှုကို ဆောင်သောသူနှင့်၄င်း၊ ရေကြောင်းအမှုကို ဆောင်သောသူနှင့်၄င်း မိတ်ဖွဲ့၍ အကျွမ်းဝင်ရင်းနှီးမှုကို ခိုင်မြဲအောင်ပြုထား၏။” || ‘ဗဗိုန်’ ဟုလည်းရေးသည်။ || ‘ဗိုန်’ (ကြိ) လည်းရှု။')
,(12655,3,4,'ခိုင်ခံ့စေသည်။ ခိုင်မာစေသည်။ ခိုင်မြဲစေသည်။',NULL)
,(12656,3,4,'စကားကိုမြဲအောင် အတည်ပြုပြောဆိုသည်။',NULL)
,(12657,3,4,'၁။ (ယှဉ်ပြိုင်တိုက်ခိုက်ရန်ဖြစ်စေ၊ အန္တရာယ်ကိုရင်ဆိုင်ရန်ဖြစ်စေ) မိမိကိုယ်ကိုအဆင်သင့်အနေအထားဖြစ်အောင် ပြင်ဆင်သည်။','“ညာတ်ကၠဗြန်ဂှ်တုဲ ဗ္ၜေံဂှ်လဗိုန်ဇကုပၚ်ကအ်တုဲ သၠာ်ဒြေပ်တိတ်အာရ။” (ဇ—၄၂၆။ အစွောံ။) = “ဆိတ်သည် ကျားသစ်ကိုမြင်သည်ရှိသော်ကိုယ်ကိုအသင့်ဖြစ်အောင်ပြၚ်၍ လည်ကိုမော့လျက် ပြေးထွက်သွား၏။”')
,(12657,3,4,'၂။ မိမိကိုယ်ကို ခိုင်ခံ့အောင်ပြုသည်။ မိမိအားနည်းချက် မိမိအမှားစသည်ကို ပြုပြင်သည်။','“အိုတ်မၞိဟ်ကီု တိရစ္ဆာန်ကီု ချဴလက်တ္ၜေဟ်လက်အဲဖအိုတ်သွံ” ဂးတုဲ သၟိၚ်ကလေၚ်စဴစိုပ်ဍုၚ်တုဲ မၚ်မွဲလဗိုန်ဇကုဗဗွဲဓဝ်တုဲဒ္ဂေတ်ဗက်ဒၠောအ်ဗ္တောန်ဒေဝတဴ—။ (ဇ—၅၂ဝ။ အစွောံ။) = “လူတို့သည်၄င်း တိရစ္ဆာန်တို့သည်၄င်း သူအားလုံးတို့သည် ငါ့ကိုသာလျှင် ကျိန်ဆိုဆဲရေးကြကုန်၏” ဟုမင်းသည် မြို့သို့ပြန်ရောက်သောအခါ မိမိကိုယ်ကိုစောင့်စည်း၍ တရားနှင့်အညီ ခိုင်ခံ့အောင်ပြု၍ နတ်၏အဆုံးအမကို လိုက်နာကျင့်သုံးလေ၏။')
,(12658,3,4,'သစ္စာခိုင်မြဲစေသည်။',NULL)
,(12659,3,4,'ကဲ့ရဲ့သည်။ ဆဲရေးသည်။ ရှုတ်ချသည်။ (ပါဠိ—ခုံသေတိ/ပရိဘာသတိ)','“လ္ပဇၞော်သၠုၚ်မာန်၊ လ္ပဗျိပၠုတ် လ္ပလဗပ်ပကီုပျုတ်ဗဒေက်ညး (ညိ) ။” (ဇ—၁၂၅။ အစွောံ။) = “မာနမထောင်လွှားလေနှင့်။ သူတစ်ပါးအား မကဲ့ရဲ့မရှုတ်ချလေနှင့်၊ မဆဲရေးလေနှင့်၊ မထီမဲ့မြင်မပြုလေနှင့်။” || “ဟွံတ္ၜေဟ်လက်လဗပ်ပကီုကဵုအဲ နဂလာန်သ္ဍိုက်မၠိုက် မပမှဝ်ကဵုစိုတ်အဲဂှ်ရောၚ် မဟီုတဴသွံ။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “ငါ့ကို မဆဲရေးမရေရွတ် ငါ၏နှလုံးကို ဆုပ်နယ်ဘိသကဲ့သို့ ချစ်ဖွယ်သောစကားကိုသာ ဆို၏။” (မင်းပူးဦးသြဘာသ) || “နဂလာန်သ္ကာတ်မြဟ်သ္ကေဝ်ကတောဝ် ညးဟီုတ္ၜေဟ်လဗပ်ပ္ကီုတၠအဲ ဗွဲမလောန်သန်ရအဴ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) =“ရင့်သီးရုန့်ရင်းသော နားမခံသာသောစကားဖြင့် သူတို့သည် အရှင့်ကို အလွန်အမင်း ပြောဆိုဆဲရေးရှုတ်ချကုန်၏။”')
,(12660,3,4,'ငိုက်မျဉ်းသည်။ အိပ်ငိုက်သည်။','“ပဟိုတ်ကွိုၚ်ကွုဲ၊ သၠိၚ်လဗုဲသ္ၚဳ။” (လိက်ပတ္တစာရဳ။နာဲထဝ်စိုပ်။) = “ညောင်းညာသောကြောင့် ငိုက်မျဉ်းအိပ်ပျော်သည်။” || လဗုဲဒကုဲ = ငိုက်မျဉ်းသည်။ || လဗုဲလှိၚ် = ငိုက်မျဉ်းအိပ်ပျော်သည်။ || “သီုချေံသီုသၟိၚ်၊ လဗုဲလှိၚ်အာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “မြင်းရောမင်းရော ငိုက်မျဉ်းအိပ်ပျော်သွား၏။” || “မတ်ဟွံလဗုဲ၊ ဟွံဇကုဲလှိၚ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “မျက်စိမငိုက်မျဉ်း အိပ်မငိုက်အိပ်မပျော်။”')
,(12661,3,4,'‘ဗဗေဝ်’ ရှု။',NULL)
,(12662,3,4,'မြူးထူးသည်။ ရွှင်ပျသည်။','“ပၞာန်ပန်ကၞိပ်၊ ပေၚ်သိပ်သ္အဳဗ္ဂာ။ သရာဲတအ်မာ၊ဟာန်ဇာလဗဵု။ တက်ဖံထအု၊ ဍုၚ်ဗရုကြဵု။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “စစ်ကြောင်းလေးကြောင်းတို့ဖြင့် သေသပ်စွာပြည့်နှက်နေ၏။ သူရဲတို့သည် ရွှင်ပျမြူးထူးနေကုန်၏၊ အိုးစည်တို့ကို တီးခတ်လျက်ရှိသည်မှာ မြို့အလုံးကို ခြိမ့်ခြိမ့်သဲမြည်သံလွှမ်းမိုးနေ၏။”')
,(12663,3,4,'သုတ်လိမ်းသည်။','“(ဒဇဲတံ) နစလန် လဗောဟ်စုတ်လပုဟ်တဲမသုန်တုဲ ဒါတ်လဝ်တၞံဆုဂှ်ရ။” (ဇ—၄၆၅။ အစွောံ။) = “လက်သမားတို့သည် ထိုသစ်ပင်ကို နံ့သာဖြင့်သုတ်လိမ်း၍ လက်ငါးချောင်းရာကို ပေးပြီးလျှင်ပုတ်ထား၏။”')
,(12664,3,1,'လပို့။','လဗအ်ဂၠဴ = နွားလပို့။ || “ဂၠဴဥဿဘမွဲ မနွံသဗအ်မသၠုၚ်လောန်။” (ဇ—၂၃၂။ အစွောံ။) = “အလွန်မြင့်သောလပို့ရှိသောဥဿဘနွား။”')
,(12665,3,1,'အလယ်အလတ်အရွယ်မိန်းမ။ မဇ္ဈိမအရွယ်မိန်းမ။ မိန်းမအို။ (အသက် (၃ဝ) မှ (၆ဝ) အထိအရွယ်ရှိသောမိန်းမ။ မှတ်ချက်။ လူ့သက်တမ်း (၉ဝ) ဖြင့် တွက်ထားသည်။ လူ့အရွယ်အပိုင်းအ ခြားကို သုံးပိုင်းအညီအမျှ ပိုင်းခြားသည်။)','“လဗြဴဒိုက်ဂတ်မွဲဂှ်—။” (ဇ—၂၅၄။ အစွောံ။) =“တယောက်သောဆင်းရဲစွာသော မိန်းမအိုသည်—။” (ညောင်ကန်) || “သမ္ဘာဗမၞးဂှ် လဗြဴဟာဝုတ်ဟာ။” (ဇ—၄ဝ၂။ အစွောံ။) = “ပုဏ္ဏား၊ သင့်မယားသည် မိန်းမအိုလော အပျိုလော။” || ‘ယဗြဴ’ နှင့် ‘သၟတ်ဗြဴ’ တို့လည်းရှု။')
,(12666,3,4,'ဝေဆာသည်။ များပြားသည်။ ပြည့်နှက်သည်။','“တၞးဆုလဘိုက်၊ ဘမြိုက်ပ္ကဴသတ်။” (လိက်မေဃကောန်ဒြာဲ) = “သစ်ရွက်များဝေဆာ၍ အသီးအပွင့်များပြွတ်သိပ်နေ၏။” || “တူပြာသာတ်ထဝ်၊ ဍုၚ်သွဝ်ကမြဴ။ ပုၚ်ဒိပ်ဍာ်ဒိပ်၊ အမာဲဒိပ်အဴ။ ကဝ်လဗမြိုက်၊ လဘိုက်ဂ္ညိဂၠဴ။” (လိက်လၞုဟ်ပန်) = “နတ်ပြည်ရှိ ရွှေပြာသာဒ်ထက်­နေ၍ နတ်­ဖြစ်သောထမင်း၊ အဖျော်၊ဟင်းလျာအမည်တို့သည် နတ်ပဒေသာပင်­ ဝေဆာပြည့်နှက်တင့်တယ်နေကုန်၏။”')
,(12667,3,1,'၁။ ရင်နှစ်သည်းချာ။ ရၚ်သွေး။','“အဵုလမာဂၞဴယာဲဟိုဲ။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “အိုမယ်မယ့်ရၚ်သွေးသည်းချာရဲ့။” || “အဵုမဂေါဝ်လောန်၊ ကောန်လမာဂၞဴ။ ပပ္တေဟ်ဂလာန်၊ ပဆာန်ဍေံအဴ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ရုပ်အဆင်းတင့်တယ်သော ရၚ်နှစ်သည်းချာ အို—ချစ်သား၊ သူ့ကိုမယုံလေနှင့် မချစ်လေနှင့်။” || “ယာဲချိုတ်ဂုန်မ၊ ရလမာဂၞဴ။” (လိက်သၚ်ဂဒါ) = “အိုချစ်သား၊ သင့်ကြောင့် မယ်မယ်သေပွဲဝင်ရရှာတော့မည်။”')
,(12667,3,1,'၂။ သားထွေး။ သမီးထွေး။','“အဵုကောန်အဲပိ ကောန်ဂၠု၊ ကောန်ခဍဲ ကောန်လၟာဂၞဴ။” (သၠပတ်ဗြဟ္မဒတ္တဂၞကျာ်ခေမာဝတဳ) = “အိုငါ့သားသမီးသုံးဦး သားကြီး၊ သားလတ်၊ သားထွေးတို့။”')
,(12668,3,1,'(အိုးစသည်၏) အဖုံး။ စလောင်းဖုံး။','‘(ဂြောဝ်ဂှ်) ဂဒဵုလဝ်လမဳဂှ်တုဲ—။’ (ဇ—၃၇၅။ အစွောံ။) = ‘စားဖိုသည်သည် အိုးအဖုံးကို ဖုံးထားပြီးလျှင်—။’ || “ထၟာဲဂှ်ဟွံကတဴလမဳဂှ်ရောၚ်ကတဴ။” = “အိုးကမပူ စလောင်းကပူသည်။” || “(ခ္ဍာ်) ပဝ်စှ်ေဍုန်ပ္ဍဲက္ဍိုပ်ဂၟဳဂှ်တုဲ ၜံက်စဖျုန်တံဂှ်ရ။” (ဇ—၂၇၄။ အစွောံ။) = “ကျီးသည် ပျံဆင်းလာကာ စလောင်းဖုံးပေါ်­နား၍ အမဲသားတို့ကို စား၏။”')
,(12669,3,1,'၁။ ပင်စည်။ (ပါဠိ—ခန္ဓ)','“ဆုဗောဓိပလောဟ်ကျာ်ဂှ် နွံတဴလမှဳဂွုသ္အးညံၚ်သၟးဂၠးသြန်၊ နွံကဵုလမှဳမဒ္ဂူ။” (သၠပတ်ဂမ္စာဲဓါတ်) = “ဘုရားပွင့်တော်မူရာဗောဓိပင်သည် ငွေသားကဲ့သို့ ဖြူစင်သောပင်စည်ရှိ၏။ ဖြောင့်တန်းသောပင်စည်ရှိ၏။” || “ဆုဂှ် လမှဳ၊ ကၞာၚ်၊ သၠ၊ပ္ကဴ၊ သတ် သီုဖအိုတ်တုပ်သတ်ကြုက်ရ။” (ဇ—၅၄။ အစွောံ။) = “ထိုၚ်္ကံဖလသစ်ပင်၏ ပင်စည်အခက်တို့သည်၄င်း အရွက်အပွင့်အသီးတို့သည်၄င်း အလုံးစုံတို့သည် သရက်နှင့်တူသည်သာလျှင်ဖြစ်ကုန်၏။” (ညောင်ကန်) || “ညံၚ်ကၞာၚ်မနိဿဲကဵုလမဳ ခမဳ (ကၟဳ) ဗ္ဒန်လဝ်လမဳတုဲ—။” (ဇ—၁၃၁။အစွောံ။) = “အကိုင်းသည် ပင်စည်ကိုအမှီပြု၍ ပင်စည်ကို အုပ်မိုးကွယ်ကာထားသကဲ့သို့။” || “ညံၚ်တၞံဆုမတဝ်ဒၟံၚ်မုက်ကျာရ။ ကၞာၚ်သၠရောၚ်မချဳ လမှဳတၞံဆုဂှ် မဟွံဂွံချဳကီု။” (ဇ—ဝိဓုရ။ အစွောံ။) = “လေမျက်နှာစာနှင့် တည့်နေသောသစ်ပင်ကဲ့သို့ အခက်အရွက်တို့သာလျှင်လှုပ်၏။သစ်ပင်၏ပင်စည်သည်ကား မလှုပ်။”')
,(12669,3,1,'၂။ သစ်ပင်၏ပင်စည်လုံးကဲ့သို့ လုံးရှည်သောအရာ။','“(ညးဗၞိက်လီုသမၠီုဂှ် ဟုတ်အာနူထးထဝ် ၚုဟ်မွဲလက်ဂှ်တုဲ) ညံၚ်လမဳကြက်တၟံမဇၞော်မဒေါမ်ဍိုက်ကီု ယဲပူမဟ်မဇၞော်က္တဵုဒှ်ရ။ သှ်ပ္တဴသတိဟွံမာန်သ္ၚဳအာ။” (ဇ—၃။ အစွောံ။) = “ရွဲကုန်သည်မိုက်သည် အဖိုးတစ်သိန်းထိုက်သော ရွှေခွက်မှဆုံးရှုံး၍ မိမိကိုယ်ပေါ်သို့ ကျောက်တိုင်လုံးကြီးလဲပြိုဖိကျဘိသကဲ့သို့ဖြစ်ကာ အလွန်စိုးရိမ်ပူပန်သည်ဖြစ်၍ သတိတရားကို မထိန်းနိုင်ဘဲ မိန်းမောသွားလေ၏။” || “လမဳထဝ်မွဲ ဇလိၚ်ပန်ဟတ် ဇမၞော်တၟာဒဳ တိုပ်လဝ်တုဲ (သေဋ္ဌဳဂှ်) ပကာဂစိုတ်ရ။” (ဇ—၅၆။ အစွောံ။) = “သူဋ္ဌေးသည် လုံးပတ်ပေါင်ပမာဏရှိသော အလျားလေးတောင်ပမာဏရှိသော ရွှေတုံးကိုမြှုပ်၍ သေ၏။” (ညောင်ကန်) || “(နူဍာ်ဂှ် သၟိၚ်နာ်) ဗဂဵုပ္တိုန်သၞပၟတ်တၟာတၟာလမဳတာ။” (ဇ—၁၃၃။ အစွောံ။) = “နဂါးမင်းသည် ရေမှ ထန်းလုံးပမာဏရှိသောမီးလျှံကိုဖြစ်စေ၏။”')
,(12670,3,1,'ရုပ်အဆင်း။ ရုပ်အသရေ။','‘ပြဘာဝတဳ တၠလမဳရုပ်။’ (ဇ—၅၃၁။ အစွောံ) = ‘ရုပ်အဆင်းရှင်ပဘာဝတီ။’ || “ဘဒ္ဒေမဒ္ဒဳ၊ ယွံတၠလမှဳရုပ် မစိုန်ဒှ်တဴအထောတ်ကၞတ်မာတုဂံါဂမၠိုၚ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မိန်းမတကာတို့၏ အထွတ်အခေါင်ဖြစ်သော ရုပ်အဆင်းပိုင်ရှင် အဘယ်မဒ္ဒီ။”')
,(12671,3,4,'လှုပ်ရှားသည်။ ရွေ့လျားသည်။ (?)','“စိုပ်သန်ၛာရော၊ ကျာလမောချဳ။” (လိက်မေဃသန်) = “ဆည်းဆာအချိန်ရောက်သောအခါ လေသည် လှုပ်ရှားတိုက်ခတ်လာ၏။” || “ပက်ပါအလိုန်၊ ဇွိုန်သာဂရော။ ဍာ်ဂၚ်တုန်ရော၊ ထပ်လမောတိုန်။” (လိက်မေဃသန်) =“မြစ်ပင်လယ်ပြၚ်­ ရေလှိုင်းတံပိုးတို့သည် အထပ်ထပ်လှုပ်ရှားဖြစ်ပေါ်လာ၏။” || “ကထိုန်မံက်အဵု၊ မြေက္ကသဵုမြော။ ပုဟ်မာ်လမော၊ ဃောဟေမန္တ။” (လိက်မာဃဒေဝါန်) = “တန်ဆောင်မုန်းလဆန်းမှသည် နတ်တော်လသို့ ထိုမှသည်ပြာသို၊ တပို့တွဲလသို့ ဟေမန္တဥတုအတွင်း အချိန်ကာလသည် ရွေ့လျားပြောင်းလဲ၏။” || “မာ်သ္ဂုတ်အာဗိုန်၊ ဖဝ်ရဂိုန်မြော။ အဒိုတ်တုန်ရော၊ လမောကၠောံမိန်။” (လိက်မာဃဒေဝါန်) || “မူပိုဲမံၚ်ပ၊ ဒုၚ်ဘဝရော။ ဟီုတုဲပေၚ်တး၊ လုံရးလၟော။ ကၞုက်ကၞာဲ၊ လောန်ကာဲယောသော။ ဇက်တိတ်အာရော၊ လၟောဂြိုပ်ဂျ။ စိုပ်ဂကောံဂ္ညိ၊ ဟတ္ထိပါလ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “(ဟတ္ထိပါလမင်းသား တောထွက်ရဟန်းပြုသည်ရှိသော်) တိုင်းနိုင်ငံအလုံးရှိလူတို့သည် ငါတို့သည် ဘဝတွင်နေသဖြင့် အဘယ်ကိုပြုအံ့နည်းဟုဆို၍ လှုပ်လှုပ်ရှားရှား အုတ်အုတ်ကျက်ကျက်ဖြစ်ကာ ဟတ္ထိပါလရှိရာတောသို့ စုရုံးရွေ့လျားထွက်ခွာသွားကြကုန်၏။” || (မှတ်ချက်။ ဤဝေါဟာရသည် မွန်ပျို့ကဗျာလၚ်္ကာများ­ အသုံးများပြီး အခြားအဓိပ္ပါယ်များလည်း ရှိနိုၚ်သေးသည်။)')
,(12672,3,4,'ထွန်းလင်းသည်။ လင်းထိန်သည်။','“(သၞပၟတ်ဂှ်) မဂဵုတိုန်ဒဵုဗဝက် လမးအာအလုံတ္ကအ်ပန်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “ထိုမီးလျှံသည် ဘဝဂ်သို့တိုၚ် လောၚ်တက်သွားကာ လေးကျွန်းအလုံး­ လင်းထိန်သွားလတ္တံ့။”')
,(12673,3,1,'ဖိုးသူတော်။ (ခေါင်းတုံးတုံး၊ ဝတ်ဖြူစင်ကြယ်ဝတ်၍ သီလစောင့်ထိန်းသောယောကျာ်း။)','“အဲဂစိုတ်ထောံကၠေံလမာတ်ဝွံရ။” (သၠပတ်သုရသာ) = “ဤဖိုးသူတော်အား ငါသတ်ပစ်အံ့။”')
,(12674,3,3,'‘လၟေအ်’ ရှု။',NULL)
,(12675,3,1,'‘လၟဳ’ ရှု။',NULL)
,(12676,3,4,'မွှေးပျံ့သည်။','“အသဝ်ဓဝ်သစ္စမရှာတ်ဂှ် ဇၟာပ်ဒိုဟ်လမှာဲအာ ဟွံသေၚ်ဟာ။” (အာန်ဇုနာန်) = “အရှင်မင်းမြတ်၏ အံ့ချီးဖွယ်သစ္စာတရားသည် အရပ်ရပ်သို့ မွှေးပျံ့သွားသည်မဟုတ်လော။”')
,(12677,3,1,'၁။ ဆိုင်း။ ပုခုံးထမ်းဆိုင်း။','လယၜဝ် = ကြိမ်နှင့်လုပ်ထားသောဆိုင်း။ || “(သၟိၚ်ဗပုန်ဂှ်) ရပ်စန်ဒက် (သၟိၚ်ဗာရာဏသဳ) တုဲ စုတ်ကဵုလယတုဲ က္ဍိုပ်ကဵုဗတက်ဖျေံဗွဲသၟဝ်တုဲ ကဵုကွက်လဝ်ပ္ဍဲပြဘိုက်တရၚ်ရ။” (ဇ—၃ဝ၃။ အစွောံ။) = “(ခိုးသူမင်းသည်) ဗာရာဏသီမင်းကိုဘမ်း၍ဆိုင်း­ထည့်စေ၍ မြောက်တံခါးခုံ­ ဦးစောက်ဆွဲစေ၏။” (ညောင်ကန်)')
,(12677,3,1,'၂။ ကြိမ်။ ကြိုး။','“စိၚ်ဂကူမှာတၚ် ညးမဂ္ညိလဝ်နလျထဝ်။” = “ရွှေကြိမ် (ရွှေကြိုး) တို့ဖြင့်လည်း ခက်အပ်ကုန်ထသော မာတၚ်မျိုးလည်းဖြစ်ကုန်ထသော (ဆင်တော်) ။” (ပါဠိ—သုဝဏ္ဏကစ္ဆာ)')
,(12678,3,1,'အလင်းရောင်။','‘လျး’ ရှု။')
,(12679,3,16,'‘လျုၚ်’ ရှု။',NULL)
,(12680,3,4,'‘လျုၚ်စိုတ်’ ရှု။',NULL)
,(12681,3,1,'၁။ အလေးချိန်။','‘ဖျုန်ကၠိက်ဂှ် နွံလျိုၚ်ပိပသာရ။’ = ‘ထိုဝက်သားသည် အလေးချိန်သုံးပိဿာရှိသည်။’ || “ဗၞိက်ဂမၠိုၚ် လယိုင်မသ္ဇိုၚ်လောန်။” (ဇ—နာရဒ။ အစွောံ။) =“အလွန်လေးသောဝန်ရှိသော ကုန်ပစ္စည်းများ။”')
,(12681,3,1,'၂။ တာဝန်။','ကေတ်လျိုၚ်၊ ဒုၚ်လျိုၚ် =တာဝန်ယူသည်။ တာဝန်ခံသည်။ || “(သွက်ဂွံလှေအ်လှန်ကောန်တြုံသၟိၚ်ဂှ်) လယိုင်အဲဍိက်ရအဴ”သၟတ်ဗြဴဂး။ (ဇ—၂၆၃။ အစွောံ။) = “မင်းသားကိုဖြားယောင်းရန် အကျွန်ုပ်တာဝန်တည်း” ဟုမိန်းမပျိုဆို၏။')
,(12681,3,4,'လေးလံအောင်ပြုသည်။ လေးလံစေသည်။','“ဍာ်တံဂှ် သကိုဟ်ထောံကၠေံရ၊ လ္ပပလယိုင်ဝေၚ်ကွဳရ” ကလော်တံဂး။ (ဇ—၁။ အစွောံ။) = “ဤရေတို့ကို သွန်ပစ်လိုက်ပါ။ လှည်းလေးအောင်မပြုပါနှင့်။” || “(သၟိၚ်နာ်ဂှ် ညာတ်သ္ပဝ်တုဲ) ၚိတ်လဝ်တၟံဇၞော်မွဲတုဲလယိုင်လဝ်ဇကုတုဲ ဖျေံကၠေံဗတဗွဲသၟဝ်တုဲ တန်ဒၟံၚ်ရ။” (ဇ—၅၁၈။ အစွောံ။) = “နဂါးမင်းသည်ဂဠုန်ကိုမြင်သည်ရှိသော် တစ်ခုသောကျောက်တုံးကြီးကိုမျို၍ ကိုယ်ကိုလေးလံစေ၍ အမြီးကိုအောက်သို့ချလျက် နေ၏။” || (မှတ်ချက်။ ယနေ့မွန်းစကားတွင် ‘လယိုင်’ (ကြိ) အစား ‘ဗဇြိုၚ်’ဟု ပြောဆိုကြသည်။)')
,(12682,3,1,'ကိုယ်ဝန်။','“ဂၠဴဗြဴမွဲဂှ်တုန် ဍေံနွံတဴကဵုလယိုင်ဂဝ်—။” (ဇ—၃၄၉။ အစွောံ။) = “တစ်ခုသောနွားမသည် ကိုယ်ဝန်ရှိ၏။” || “ဗြဴဍေံဂှ်လေဝ် သီုလယိုင်ဂဝ်ဂၞဴရောၚ်။” (ဇ—၃၇၆။ အစွောံ။) = “သူ့မယားသည်လည်း ကိုယ်ဝန်နှင့်ဖြစ်၏။”')
,(12682,3,1,'ကိုယ်ဝန်။','“ဂၞကျာ်ဇၞော်တုန်လေဝ် ဒှ်တဴလယိုင်ဂၠံဂဝ်ရောၚ်။” (ဇ—၅၂၅။ အစွောံ။)')
,(12683,3,4,'၁။ (စပရင်ကဲ့သို့) အထက်အောက်လှုပ်သည်။—စေသည်။','လယတ်ခရေၚ်= ပုခက်ကိုလှုပ်သည်။ || “ဒဒန်ဆုဂှ် လယတ်ဒၟံၚ်ရ။” = “သစ်သားတံတားသည် စပရၚ်ကဲ့သို့အထက်အောက်လှုပ်နေသည်။”')
,(12683,3,4,'၂။ ခတ်သည်။ တိုက်သည်။ ထိခိုက်သည်။','“ကာလလိုန်ၜါဍေံကောံဒှ်မွဲ ပ္ဍဲကအ်တဲမွဲဂှ်တုဲ ဍေံလယတ်တဴရၚ်သ္ကအ်တုဲ ဍေံဗြုတဴရ။” (ဇ—၄ဝ၈။ အစွောံ။) =“လက်ကောက်နှစ်ကွင်းတို့သည် လက်တစ်ခုတည်း­ စုစည်းမိသောအခါ အချင်းချင်းထိခတ်၍အသံမြည်လေ၏။” || “ညံၚ်တၟံၜါမလယတ်ရၚ်သ္ကံကီု။” (အာန်ဇုနာန်) = “ကျောက်တုံးနှစ်ခုတို့အချင်းချင်းရိုက်ခတ်သကဲ့သို့။”')
,(12683,3,4,'၃။ ကုန်သည်။','“(သတ်ဆုတံဂှ်ဂၠိုၚ်လောန်) သီုညးမသုန်ကၠံစတဴဟွံတီအိုတ်လယတ်ဟေၚ်။” (ဇ—၁၂၄။ အစွောံ။) (လယတ် = အိုတ်) = “သစ်သီးတို့သည် အလွန်များ၏။ ငါးရာကုန်သောသူတို့သည်လည်း စား၍မကုန်နိုင်သည်သာလျှင်တည်း။”')
,(12683,3,4,'၄။ စွန့်ပစ်သည်။ (?)','“သစ္ဆုဗဝ်သအဝ်ဒၟံၚ် ရိုဟ်ဟွံမာန်ရ။ ဣသိမသုန်ကၠံဂှ်စဟွံအိုတ်တုဲ လယတ်ယိုက်ထောံအလုံတိရ။” (ဇ—၁၂၄။ အစွောံ။) = “သစ်သီးတို့သည် ဗုံးပေါလအော အလျှံပယ်များ၏။ ထိုရသေ့ငါးရာတို့သည် စား၍မကုန်ဘဲ မြေအနှံ့စွန့်ပစ်ကြရ၏။”')
,(12684,3,4,'ရိုက်ခတ်သည်။ တိုက်ခတ်သည်။','“နရက်သၚ်္ဃာတ မၞုံဘဲတၟံၜါၜါမဂဵုဒၟံၚ်တုဲဍေံမလယတ်ဒဗတ်ဇကု—။” (ဇ—၅၃ဝ။ အစွောံ။) = “သၚ်္ဃာတငရဲသည်ကား တောက်လောင်နေသော နှစ်ခုနှစ်ခုသော ကျောက်တုံးကြီးတို့သည် ငရဲသားကိုယ်ကို ရိုက်က်ခတ်ကုန်၏။”')
,(12685,3,4,'ထိတွေ့သည်။ ပွတ်တိုက်သည်။ တိုက်ခတ်သည်။',NULL)
,(12686,3,4,'(စပရင်ကဲ့သို့) အထက်အောက်လှုပ်သည်။ ရုန်းပြန်လှုပ်ရှားသည်။','“ညံၚ်ရဴလွာဇုက်ဂြိုပ်လၟတ် မလစံက်ဍိုပ်ဍဴဂှ် ယာံကျာပိုက်မ္ဂး နူတံဒဵုကၞောတ် ချဳလယတ်လၟာဲတဴ—။” (ဇ—၄၁၁။ အစွောံ။) = “စိမ်းလန်းစိုပြည်သော နုသောတောနွယ်ကြိုးသည် လေတိုက်လတ်သော် အရင်းမှအဖျားတိုင် ရုန်းပြန်လှုပ်ရှားဘိသကဲ့သို့။”')
,(12687,3,4,'‘ဗယောတ်’ (ကြိ) ရှု။',NULL)
,(12688,3,4,'ကိုင်းညွတ်သည်။','“အလုံမွဲလှက်၊ ဂၠးစက္ကဝါ။ ချဳဂရိုက်အာ၊ ကာလဂှ်ရ။— ယုဂ္ဂန်သိနနာ၊ နေရုရာဇ။ လစောတ်လမောဝ်၊ လယောဝ်တဴရ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “စကြဝဠာတစ်သောင်းတိုက်လုံး ထိုအခါတုန်လှုပ်သွား၏။ မြင်းမိုရ်တောင်သည် ပျော့ပျောင်းကာ ကိုင်းညွတ်လာ၏။”')
,(12689,3,4,'ကိုင်းညွတ်သည်။ တိမ်းညွတ်သည်။',NULL)
,(12690,3,4,'ခါသည်။','“ဗ္ဂဲဂှ် ဇိုၚ်ဍေံဍုက်အာဍာ်တုဲ လယှ်ကၠေံဍာ်ဂှ်ရ။” =“ထိုကြောင်သည် ခြေထောက်ရေစိုသွား၍ ရေကိုခါထုတ်ပစ်သည်။” || “စိၚ်ဇၟူလကိုတ်တုဲ လယှ်ဖတုံကၠေံသၟိၚ်ကၠဵု ချိုတ်ဒၞာဲဂှ်ရ။” (ဇ—၂၄၁။ အစွောံ။) = “ဆင်ပြောင်သည်လန့်၍ ခွေးမင်းအားလှုပ်ခါချလိုက်ရာ ခွေးမင်းသည် ထိုနေရာ­ပၚ်သေ၏။”')
,(12691,3,4,'(အံ့သြ၍၊ ထိတ်လန့်၍) လက်ဖျားခါသည်။ လက်ချောင်းများကိုလှုပ်ခါသည်။','“သၟတ်ဗြဴဝုတ်ဂှ် ကျေဝ်ဂေါဝ်လောန်၊ ညးဂမၠိုၚ်ဒးလယှ်တဲရ။” = “ထိုမိန်းမပျိုသည် သူတကာလက်ဖျားခါရလောက်အောင် အလွန်လှပတင့်တယ်၏။” || “(လဟီုသၟိၚ်ဂှ်) ဗမၞးတံမိၚ်တုဲ လယှ်လပုဟ်တဲတုဲ သ္ဂးရ။” (ဇ—၃၁၄။ အစွောံ။) = “မင်း၏စကားကို ပုဏ္ဏားတို့ကြားကုန်သည်ရှိသော် (ထိတ်လန့်တုန်လှုပ်သည့်ဟန်ဖြင့်) လက်ချောင်းတို့ကို လှုပ်ခါ၍ဆို၏။”')
,(12692,3,1,'အနက်။','“လျိုဟ်ၜဳဏအ် နွံပိစှ်ောဟတ်ရ။” = “ဤမြစ်၏အနက်သည်အတောင်သုံးဆယ်ရှိသည်။” || “နရက်ဇၞော်မွဲမွဲဂှ် လယိုဟ်ဍေံစှ်လ္ၚီယောဇနာရ။” (ဇ—နေမိ။ အစွောံ။) = “ငရဲကြီးတစ်ခုစီသည် အနက်ယူဇနာတစ်သောင်းရှိ၏။” || ‘လမျိုဟ်’/‘ဒမျိုဟ်’ ဟုလည်းရေးသည်။ || ‘သ္ဇိုဟ်’/‘ဇြိုဟ်’ (ကြိ) လည်းရှု။')
,(12693,3,1,'ထောၚ်ဖမ်းသောညွတ်ကွင်း။ ကျော့ကွင်း။ (ပါဠိ—ဂဏူဌိပါသ)','“ဂစေံမဒိုဟ်၊ဟိုတ်ဂိုဟ်လစ။ — ဝေၚ်အာဂြိုၚ်အာ၊ မှောဝ်ဇာလီၜန်။ ဒးလယအ်ရ၊ ထဴလၟပၠန်။” (လိက်လက္ခဏပိ) = “မိုက်မဲသောငှက်တို့သည် ရေအိုင်ကိုနှမြောသောကြောင့် ကစားရွှင်ပျော်ရင်း စုရုံးရောယှက်နေကြရာ မုဆိုး၏ကျော့ကွင်း­ မိကုန်၏။”')
,(12694,3,4,'၁။ လှုပ်ရှားသည်။','“ကောန်ၚာ်အယုက်စှ်သုန်သၞာံမ္ဂးဂှ် ဃောစိုတ်ဍေံလရုဒၟံၚ်ရ။”= “တစ်ဆဲ့ငါးနှစ်အရွယ်ကလေးသည် စိတ်လှုပ်ရှားတုန်းအရွယ်ဖြစ်သည်။” || “ဟိုတ်နူမဖေက်အဲတုဲ နူဝွံဒဵုတေံ ရဴဗ္ၜေံ (မတ်ကၠက်) ဗှ်ေနရုတဴသွံ။” (ဇ—၃၃၈။ အစွောံ။) = “သင်သည် ဆိတ်ကန်းကဲ့သို့ (ငါ့ကို) ကြောက်ခြင်းကြောင့် အကြင်ထိုမှဤမှ လှုပ်ရှား၏။” (ညောင်ကန်)')
,(12694,3,4,'၂။အုတ်အုတ်ကျက်ကျက်ဖြစ်သည်။ ရုတ်ရုတ်သဲသဲဖြစ်သည်။ ကြောက်လန့်တကြားဖြစ်သည်။','“သၟိၚ်မိၚ်ညာတ်ညးဒြေပ်လုပ် လရုဒၟံၚ်အလုံဍုၚ်ဂှ်တုဲ သၟိၚ်သၟာန်ညး—။” (ဇ—၄၆၉။ အစွောံ။) =“မြို့အလုံးသည် ကြောက်လန့်တကြားဖြစ်နေ၍ လူများပြေးလွှားဝၚ်လာကြသည်ကို မင်းသည်ကြားရမြင်ရ၍ မေး၏။” || “မၞိဟ်ပ္ဍဲဒပ်မိၚ်ဗရု လကိုတ်ကမၠေဝ်ဒၟံၚ် ပ္ဍဲမလရုဒၟံၚ်ဂှ် ညးမသုန်ကောံတုဲ ဗၠးတိတ်အာ—။” (အကြီုရာဇာဓိရာဇ်) = “တပ်တွင်းမှလူများ ထိုအသံကိုကြား၍ ကြောက်လန့်တကြား ဆူညံနေ၏။ ထိုသို့အုတ်အုတ်ကျက်ကျက်ဖြစ်နေစဉ် ငါးယောက်သောသူတို့စု၍လွတ်မြောက်သွား၏။” || “ပၞာန်ဒမၠဂှ်၊ က္တဵုဒှ်နာနာ။ ဖေက်နရုအာ၊ ဍုၚ်ရးဝါဗ္ၚ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ဓါးပြတိုက်ခြင်းအမျိုးမျိုးပေါ်ပေါက်၍ ပြည်ရွာလယ်တောအနှံ့ တုန်လှုပ်ချောက်ချားသွားမည်စိုး၏။”')
,(12695,3,4,'အုတ်အုတ်ကျက်ကျက်ဆူညံသည်။','“မၞိဟ်မၞုံပ္ဍဲဍုၚ် လရုကၠံၚ်ဒၟံၚ်။” (အကြီုရာဇာဓိရာဇ်) = “မြို့တွင်းရှိလူများသည် အုတ်အုတ်ကျက်ကျက် ဆူညံနေ၏။”')
,(12696,3,4,'ဆူပူသည်။ မငြိမ်မသက်ဖြစ်သည်။','“ဍုၚ်ကွာန်လရုလစာ်။” = “မြို့ရွာဆူပူသည်။” || “ဍုၚ်ဒလလရုဒစာ်။” (သၠပတ်ရာဇာဓိရာဇ်) = “ဒလမြို့သည် ဆုပူမငြိမ်မသက်ဖြစ်၏။” || “ပ္ဍဲဍုၚ်လရုလစာ်ကၠံၚ်ဒၟံၚ် စိုပ်လအိတ်။” (အာန်ဇုနာန်) = “မြို့တွင်း­ အလွန်အမင်းဆူပူဆူညံနေ၏။”')
,(12697,3,4,'(လေ) တိုက်သည်။ လှုပ်ခတ်သည်။','“ကျာၜဳလရိုက်၊ မှုဲပိုက်ညှာညှာ။” (လိက်ပဒုမဝတဳ) = “ပင်လယ်လေလှုပ်ခတ်၍ ဖြည်းဖြည်းညှင်းညှင်း တိုက်ခတ်နေ၏။”')
,(12698,3,4,'ခါသည်။ လှုပ်ခါသည်။','“ကၠဵုလရိုက်ဇကု။” = “ခွေးသည် ကိုယ်ကိုလှုပ်ခါသည်။” || “(ယွံသၟိၚ်မပြဲ) ၊ လ္ပအ်ဝွံ သ္ကာတ်ကွေံသွံ” ဂးတုဲ ဗမၞးလရိုက်လပုဟ်တဲရ။ (ဇ—၇၇။အစွောံ။) = “မြတ်သောမင်းကြီး၊ ဤအိပ်မက်သည် အလွန်ကြမ်း၏” ဟုဆိုကာပုဏ္ဏားသည်လက်တို့ကိုခါ၏။ || “ညးက္ၜၚ်တံဂှ် ဂဍတ်တဲတုဲ မြာ်ဂှ် နရိုက်တိုန်သၞေၚ်—။” (ဇ—၃၃၉။ အစွောံ) = “သင်္ဘောသားတို့က လက်ဖျစ်တီးသည်ရှိသော် ဥဒေါင်းသည် အတောင်တို့ကို လှုပ်ခါ၏။”')
,(12699,3,4,'လှုပ်ခါသည်။','“(သၟိၚ်ဇာဒိသိုၚ်) တိတ်နူဂိုဟ်တၟအ်ထဝ် ၜိုတ်နှာတ်ဇကု လရိုက်လရုသ္ဂေဟ်ဒရံၚ် ပၚ်ကအ်ၚဳဒိုဟ်ပန် ဂအတ်လလောၚ်ရမျှာၚ်ကရီုကြီုတုဲ အာဂၠာဲစၞ—။” (ဇ—၁၄၃။အစွောံ။) = “ခြင်္သေ့မင်းသည် ရွှေဂူမှထွက်၍ အပျင်းဆန့်ပြီး အရိုးအဆစ်တို့ကိုလှုပ်ခါ၍ လည်ကိုမော့လျက် အရပ်လေးမျက်နှာတို့ကိုကြည့်ကာ ပဲ့တၚ်ထပ်မျှ ဟိန်းဟောက်ကြုံးဝါးပြီးလျှင်သားကောင်ရှာရန်ထွက်၏။”')
,(12700,3,4,'ငိုသည်။','“ကောန်သၟိၚ်တံဂှ် ဖေက် (ကၞုဲဂှ်) တုဲ လရိုအ်တိုန်အိုတ်ရ။” (ဇ—၃၂၉။ အစွောံ။) = “မင်းသားငယ်တို့သည် ထိုမျောက်ကိုကြောက်သဖြင့် ငိုကြကုန်၏။” || “မူဒှ်လရိုအ်ရောဗမၞး။” (ဇ—၃၂၆။ အစွောံ။) = “ပုဏ္ဏား၊ ဘာဖြစ်လို့ငိုသနည်း။” || “သဝ်ရဝကာ်မွဲ— ဍုန်ဒၟံၚ်ပ္ဍဲတဏအ်ဂှ်တုဲ ဗရုဂရဴမဇၞော်မသၠုၚ်ဟေၚ် နရိုအ်ဂြဴတဴလၟိုန်။” (ဇ—၁၁၇။ အစွောံ။) =“တစ်ခုသောခါငှက်သည် ထိုတောင်ပို့­နားနေလျက် ကျယ်လောင်သောတွန်သံဖြင့် အမြဲတစေ ငိုမြည်တွန်ကျူး၏။” || “(စိၚ်ဂှ်ဂတာံဇၞော်ရပ်လဝ်တုဲ) ဖေက်ဂစိုတ်တုဲ ဗရုဂစိုတ်ဂှ် ဗြုနရိုအ်တဴရ။” (ဇ—၂၆၇။ အစွောံ။) = “ဗုဇွန်ကြီးဖမ်းကိုင်ထားသော ဆင်သည်သေဘေးမှကြောက်သဖြင့် သေအံ့သောမြည်သံဖြင့် အော်မြည်ငို၏။” || “သၟိၚ်မိၚ်သၟတ်တံဂှ် နရိုအ်တိုန်တုဲ ‘မူရဴသၟတ်တံဂှ်မဒှ်ရော’သၟိၚ်သၟာန်။” (ဇ—၃၂၉။ အစွောံ။) = “မင်းသည် မင်းသားငယ်တို့ ငိုသည်ကိုကြား၍ ‘ထိုသူငယ်တို့ ဘာဖြစ်သနည်း’ ဟုမေး၏။”')
,(12701,3,4,'ငိုကြွေးညည်းတွားသည်။','“ပသဲမဂဵုဍာဲဂြၚ်တဴဂှ် (ချအ်) စုတ်ပ္ဍဲပါၚ်သတ်နရက်တံဂှ်တုဲ လရိုအ်ဒဝဴတဴရ။” (ဇ—နေမိ။ အစွောံ။) = “ရဲရဲနီတောက်လောင်နေသောသံကို ငရဲသားပါးစပ်ထဲသို့ ထိုးသွင်းသည်ရှိသော် ငရဲသားတို့သည် ငိုကြွေးညည်းတွားနေရကုန်၏။”')
,(12702,3,1,'လျှပ်စီး။ လျှပ်စစ်။','ဇုက်လလဳ = လျှပ်စီး။ || ဓါတ်လလဳ = လျှပ်စစ်ဓါတ်။ || “ရဴလျးလလဳ မစဳပျးတဴဇၟာပ်ဒိုဟ်ကီု။” (ဇ—၅၂၄။ အစွောံ။) = “အရပ်မျက်နှာတိုင်းကို ထွန်းလင်းစေသော လျှပ်စီးရောၚ်ကဲ့သို့။”')
,(12703,3,1,'ဘုရားအဆက်အနွယ်။ မြတ်စွာဘုရားညီနောင်။ (မြတ်စွာဘုရားအချင်းချင်းတော်စပ်ပုံ)','“ယွံခမဳတအ်၊ ခမဳဍောတ်အဇိတထေရ်ဝွံဂှ် မဒှ်လလဲအဲဂတဝွံရောၚ်” ကျာ်တြဲဂး။ = “ရဟန်းတို့၊ဤအဇိတရဟန်းငယ်သည် ငါ၏လာလတ္တံ့သော ဘုရားအဆက်အနွယ်ညီတော်တည်း” ဟုမြတ်စွာဘုရားမိန့်တော်မူ၏။ || ‘လဲ’ ဟုလည်းတွေ့ရသည်။')
,(12704,3,4,'၁။ နှောင်ကြိုးနှင့်လွှတ်ထားသည်။ လံထားသည်။','“ပ္ဍဲခလှာတ်ချောဲၜတ်ခိုဟ်ဂှ် လလဴလဝ်ဂၠဴရ။” = “မြက်နုကောင်းသောစားကျက်တွင် နွားကိုလံထားသည်။”')
,(12704,3,4,'၂။ (လွတ်အောင်) ပြေးသည်၊ အပြေးယူသွားသည်။ ယူပြေးသည်။ တစ်ပါတည်း အပြေးထုတ်ဆောင်သည်။','“ကွဳအဲကမၠတ်လလဴဏာ” တၠကွဳဂး။ (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ငါ့လှည်းကို သူခိုးယူပြေးသွား၏။” || “မဂဒူကၠတ်လလဴမေဏၚ်သောဲဍာ။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် မေနှင်းသွယ်တာကို ခိုးပြေးယူသွား၏။” || “မၞိဟ်ကောန်ကလော်ဂှ် ဍေံရပ်ကေတ်ဗမၞးမွဲတုဲ ဍေံလလဴဒရေပ်ဏာ—။” (ဇ—၅၁၃။ အစွောံ။) = “ထိုဘီလူးသားဖြစ်သောလူသည် ပုဏ္ဏားကိုဖမ်း၍ ယူပြေးသွား၏။” || “ယြဴပူဂဵုမွဲ သ္ၚိဍေံတူအာရ။ ဆအပေါတ်သ္ၚိဍေံ လလဴပတိတ်ဏာဂွံအိုတ်ရ။” (ဇ—၄၂၄။ အစွောံ။) = “အကြင်သူသည် အိမ်မီးလောင်သွား၏။ ထိုအိမ်ရှိသူ့ပစ္စည်းတို့ကို အပြေးထုတ်ဆောင်ယူနိုင်ခဲ့၏။” || “ထဝ်သြန်ညးသွံ၊ ပၠံၚ်ကေတ်ဟွံညှာ။ စိၚ်ချေံပြေၚ်ဂၠဴ၊ ဂွံလလဴဏာ။” (လိက်တရဳသံသာ) = “သူတစ်ပါးရွှေငွေကို မညှာလုယူ၍ သူတစ်ပါးဆင်မြင်းကျွဲနွားကို ယူပြေးသွား၏။”')
,(12705,3,1,'အက္ခရာ၏အထက်တွင် မွန် (အဴ) သရရအောင် သၚ်္ကေတအဖြစ်ရေးသောမျဉ်းစောင်း။—ဴ။',NULL)
,(12706,3,4,'မိမိကိုယ်ကို လွတ်အောင်ပြေးသည်။ လွတ်မြောက်စေသည်။','“သၟိၚ်ဒကောတ်တၠဇၚဳညာန် သွက်မဂွံဗလးဘဲ (အနာဂတ်) ဂမြေၚ်ကျာမွဲ ဂွံစဳရေၚ်လဝ်တုဲ (ကာလ) ဘဲကၠုၚ်စိုပ် မဂွံလလဴဗလးဇကုရ။” (ဇ—၁၄၁။ အစွောံ။) = “ဉာဏ်အမြော်အမြင်ရှင်ဖွတ်မင်းသည် အနာဂတ်ဖြစ်လာမည့်ဘေးမှ လွှတ်ရန်အလို့ငှာ ကယ်ပေါက်တစ်ခုကို စီရင်ထားရှိ၍ ဘေးရောက်သောအခါ မိမိကိုယ်ကို ထွက်ပြေးလွတ်မြောက်စေခဲ့၏။” || “(မဂဒူ) ဒဴလလဴဇကု တိတ်အာစိုပ်တ္ကံဝါန် သန်ဋ္ဌာန်မိမဂှ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် ကိုယ်လွတ်အောင်ထွက်ပြေး၍ မိဘနေရပ်ဖြစ်သော တကော့ဝန်းသို့ ထွက်သွား၏။”')
,(12707,3,4,'(ရန်သူ၏လိုက်ခြင်းမှ မိမိကိုယ်ကို) လွတ်မြောက်စေသည်။ (ရန်သူမလိုက်နိုင်အောင်) ရှောင်တိမ်းလွတ်မြောက်သည်။','“ညးဗၞိက်လီုတၠပညာ မလေပ်ဒေပ်စိုတ်တမ္ၚူတုန် ဂွံထးထဝ်မၞုံၚုဟ်မွဲလက်ဝွံရ။ စိုတ် (တမ္ၚူ) ဝွံ ပွ (တမ္ၚူ) ဝွံရ မလလဴဗဝက် မပလံၚ်ဗစိုပ်သ္ၚိ မဂွံအဵုဇိုတ် ဗဂေါဝ်မုက်ကောန်သမ္ဘာ တွဳဝါရအလုံသ္ၚိရ။” (ဇ—၃။ အစွောံ။) = “ဖြောင့်မတ်သောပညာရှိရွဲကုန်သည်သည် အဘိုးတစ်သိန်းထိုက်သော ရွှေခွက်ကိုရ၏။ ဤဖြောင့်မှန်သောစိတ် ဤဖြောင့်မှန်သော အပြုအမူကြောင့်သာ ရန်သူ၏လိုက်ခြင်းမှ လွတ်မြောက်စေ၍ အိမ်သို့ချောမောစွာရောက်စေ၍ အိမ်သူဇနီးသားနှင့် တစ်အိမ်လုံးရှိ မိမိလူများကို ဝမ်းမြောက်မျက်နှာလှစေ၏။”')
,(12708,3,4,'အသက်လုပြေးသည်။ အသက်လွတ်အောင်ပြေးသည်။','“တၠအဲဂှ် ကောတၠအဲရပ်ဂစိုတ်ကၠေံရောၚ် ညးချပ်လဝ်ရ။ ဟိုတ်ဂှ်ရ တၠအဲဒဴလလဴလမျီုညိ” အမာတ်ဂး။ (ဇ—၄၇၉။ အစွောံ။) = “အရှင်မင်းသား၊ အရှင်မင်းသား၏နောင်တော်သည် အရှင်မင်းသားကိုသတ်ရန်ကြံစည်ထား၏။ ထို့ကြောင့် အရှင်မင်းသား အသက်လွတ်ရန် ပြေးတော်မူလော့” ဟုအမတ်ဆို၏။ || “—၊ မဒးဒဴလလဴလမျီု သွိုဟ်ချိုတ်တုဲရ။” (ဇ—၄၈၁။ အစွောံ။) = “သေလုမတတ် အသက်လု၍ ပြေးခဲ့ရဖူးပြီ။” || “ဟာဲဗြဴဒၟိက်၊ — ကာလအဲလလဴဗလးလမျီုဗှ်ေ အဲစၚိန်ဏာဗှ်ေတုဲ ဗှ်ေထၚ်ဍာ်ဂှ် ကေတ်ဍာ်ဟွံဂွံတုဲ ဆီက္ၜံၚ်အဲ ပါ်ကဵုဗှ်ေသုၚ်ဂှ် ဗှ်ေဝိုတ်အာရဟာ” ဗောဓိသတ်ဂး။ (ဇ—၁၉၃။ အစွောံ။) = “ဟယ်မိန်းမယုတ်၊ နင့်ကိုငါထမ်းလျက် နင့်အသက်လွတ်အောင် အသက်လုပြေးသောကာလ­ နၚ်ရေငတ်၍ ရေရှာ၍မရသဖြင့် ငါ၏ပုဆစ်ဒူးသွေးကို ခွဲ၍နင့်ကိုသောက်စေခဲ့သည်ကို နၚ်မေ့သွားပြီလော။”')
,(12709,3,4,'ငြိမ်းသည်။—စေသည်။ ငြိမ်းအေးသည်။—စေသည်။ ငြိမ်းချမ်းသည်။—စေသည်။ ချုပ်ငြိမ်းသည်။—စေသည်။ ပြေပျောက်သည်။—စေသည်။','လလံကၠေံဒေါသ = ဒေါသကိုငြိမ်းစေသည်။ (ဇ—၄၉ဝ။ အစွောံ။) || လလံကၠေံဓဝ်လောဘ (ဇ—၄၉ဝ။ အစွောံ။) = လောဘတရားကိုငြိမ်းစေသည်။ || လလံကၠေံဓဝ်မာန (ဇ—၄၉ဝ။ အစွောံ။) = မာနတရားကို ငြိမ်းစေသည်။ || ဒေါသလလံအာ = ဒေါသပြေငြိမ်းသည်။ ဒေါသပြေပျောက်သည်။ || “ယွံကောန်၊ ကာလအဲတဴပ္ဍဲနန်မြပြာသာဒ်တေံဂှ် ရှ်ကြုက်ကဵုသဂြာ အဲဂွံပပြဘိုက်တုဲ ယဲကျာပ္ဍဲဂၞဴအဲဂှ် လလံအာရကောန်” ဘိမ္မာထေရဳ ဂးကဵုရာဟုလရ။ (ဇ—၂၈၁။ အစွောံ။) = “ချစ်သား၊ ငါသည် မြနန်းပြာသာဒ်­နေစဉ် သကာသကြားတို့ဖြင့်ဖျော်သော သရက်သီးရည်ကို သုံးဆောင်ရသည်ရှိသော် ဝမ်းထဲမှလေထိုးကျင့်နာသည် ငြိမ်းဖူး၏။” || “ပဟိုတ်ကဵုအမာတ်သၟိၚ်ကောသလရးညးၜါ သွေက်ဇွဵုမလလံအာဂှ်တုဲ ကစ္ဆပဇာတ် ကျာ်တြဲတွံ။” (ဇ—၂၇၃။ အစွောံ။) = “ဤကစ္ဆပဇာတ်ကို ကောသလမင်းကြီး၏ အမတ်ကြီးနှစ်ယောက်တို့ ခိုက်ရန်ငြိမ်းခြင်းကို အကြောင်းပြု၍ ဟောတော်မူ၏။” (ညောင်ကန်) || “အဲလလံကၠေံအဓိကဵုကလောအဲဂမၠိုၚ်ညိ” သၟိၚ်ခဍာ်ချပ်။ (ဇ—၁၄ဝ။ အစွောံ။) = “ငါသည် ငါ့ဆွေမျိုးအပေါင်းတို့၏ဘေးဒုက္ခကို ငြိမ်းစေအံ့” ဟုကျီးမင်းကြံ၏။')
,(12710,3,4,'ခန္ဓာကိုယ်ကို ငြိမ်းအေးစေသည်။ အပန်းဖြေသည်။','“(ကောန်တြုံသၟိၚ်ဂှ်ကၠုၚ်နူတရဴစိုပ်တုဲ) ဟာပ်ပုၚ်တုဲ ဇူလလံကၠေံကာယညိတုဲ—။” (ဇ—၂၅၂။ အစွောံ။) = “မင်းသားသည် ခရီးပန်းလာ၍ ထမင်းစားပြီးနောက် အတန်ငယ်နား၍ အပန်းဖြေ၏။”')
,(12711,3,4,'စိတ်ကိုအေးငြိမ်းစေသည်။','“ရသိဗောဓိသတ် ဟီုဝေတ်ဒၠောံဗ္တောန်မဇကုတုဲ ပတွဵုနူဂှ်တုဲ ရသိမဂှ် ဝေတ်စိုတ် လလံတဴစိုတ် ဗွဲမလောန်ပၠန်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “ဘုရားလောင်းရသေ့သည် မိမိဖခင်ကို ပြောဆိုဆုံးမပြီး ထိုအခါမှစ၍ ဖခင်ရသေ့သည် စိတ်ကို အလွန်စောင့်စည်း၍ ငြိမ်းအေးစေပြန်၏။” || “ညးမဒှ်သ္ဍိုက် ပကာဂစိုတ်တုဲဂှ် အေၚ်ဒုၚ်လလံစိုတ်ဟွံမာန်တုဲ မဒးစံၚ်တူယာံတဴရောၚ်။” (ဇ—၄၁ဝ။ အစွောံ။) = “ချစ်သောသူသေ၍ သည်းခံ၍ စိတ်ကိုငြိမ်းစိမ့်သောငှာ မတတ်နိုင်သည်ဖြစ်၍ ပူဆွေးငိုကြွေးရ၏။”')
,(12712,3,4,'ပြေပျောက်သည်။ ငြိမ်းသည်။','“အိုတ်ဒုဟ်မက္တဵုဒှ် နူကာယကံ ဝစဳကံ မနောကံတံဂှ် ဗွဲပြဟ်ကဵုဂွံလလံသွာအာတုဲ—။” (ပြကိုဟ်ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ကာယကံ ဝစီကံ မနောကံတို့မှ ဖြစ်ပေါ်သော အလုံးစုံသောအပြစ်တို့သည် အမြန်ပြေပျောက်ငြိမ်းသွားပါစေသတည်း။” || “ယဝ်ရဂၞကျာ်သ္ဂောံကလၚ်ပၚ်မှိၚ်ဓဝ်အဲတုဲ ဝေဒနာယဲစိုတ်ဂၞကျာ်ဂှ် သ္ဂောံလလံသွာအာရ။” (သၠပတ်ဗြဟ္မဒတ္တ ဂၞကျာ်ခေမာဝတဳ) = “ငါ၏တရားကို အကယ်၍မိဖုရားနာရသည်ရှိသော် မိဖုရား၏စိတ်ရောဂါဝေဒနာသည် ပြေပျောက်သွားလတ္တံ့။” || “တုဲလလံသွာ၊ရောဂါဂှ်စိ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ထိုနောက် ထိုရောဂါသည် ငြိမ်းပျောက်သွား၏။”')
,(12713,3,4,'ချုပ်ငြိမ်းသည်။ ပြေပျောက်သည်။','“ဂဝမဇၞော်ဂှ်က္တဵုဒှ်တုဲ လၞီစံၚ်တူ (သၟိၚ်) ဂှ် လလံဟဲအာရ။” (ဇ—၅၂၇။ အစွောံ။) = “အရှက်ကြီးရှက်၍ မင်း၏စိုးရိမ်ပူဆွေးမှုသည်ငြိမ်းပျောက်သွား၏။”')
,(12714,3,1,'ဖြန့်သည်။ ဆန့်သည်။','လလးတဲ = လက်ကိုဆန့်တန်းသည်။ ဖြန့်ထုတ်သည်။ || လလးသၞေၚ် = (ငှက်) တောင်ပံဖြန့်သည်။ ပျံသန်းသည်။ || “ဗွဲဒိုဟ်သၟဝ်ကျာ မတူရူကဵုဂြိုပ်ဟေမဝန်ဂှ် ဂၞကျာ်လလးဏာတဲတုဲ ဂးကဵုလၟရ။” (ဇ—၅၁၄။ အစွောံ။) = “မိဖုရားသည် မြောက်ဟိမဝန္တာသို့ ရှေးရှုလက်ဆန့်၍ မုဆိုးအားဆို၏။” || “(ဗောဓိသတ်သၟိၚ်တ္ၚေက်) လလးသၞေၚ်ပဝ်တိတ်အာဂြိုပ်ရ။” (ဇ—၅၂၁။ အစွောံ။) = “ဘုရားလောင်းကျေးမင်းသည် တောင်ပံဖြန့်၍ တောသို့ပျံထွက်သွား၏။” || “လလးသၞေၚ်ၜါတုဲ ၜိုပ်ထဝ်ပဝ်စဴအာဂိုဟ်တၟံထဝ်—။” (ဇ—၃၇ဝ။ အစွောံ။) = “တောင်ပံနှစ်ခုကိုဖြန့်၍ ရွှေဟင်္သာသည် ရွှေတောင်လိုဏ်သို့ ပျံ၍ပြန်သွား၏။”')
,(12715,3,4,'ကထိန်ခင်းသည်။',NULL)
,(12716,3,1,'ဆီးနှင်း။','‘လမၠာၚ်’ နှင့်အတူတူ။')
,(12717,3,1,'ပိုးစုန်းကြူး။ ပိုးစိမ်းဖြူ။','“ပၟတ်ၜိုန်အောန် ဗၞတ်တၟာလလိၚ်ကီု — နကျာပါၚ်ကီုလေဝ် ဗ္ဂိုဟ်ဗ္ဂဵုသိုက်သိုက်တုဲ သၞပၟတ်မဂၠိုၚ် ရဴမက္တဵုဗဒှ်ကီု။” (ဇ—၄။ အစွောံ။) = “ပိုးစုန်းကြူးပမာဏမျှသာရှိသောမီးသည် အနည်းငယ်မျှပင်ဖြစ်သော်လည်း နှုတ်လေဖြင့် ဖြည်းဖြည်းမှုတ်ကာကြီးစွာသောမီးလျှံကို ဖြစ်စေနိုင်သကဲ့သို့။” || ‘ကလဵုလိၚ်’ နှင့်အတူတူ။')
,(12718,3,1,'ပျက်စီးခြင်း။ ဆုံးရှုံးခြင်း။','“(ယာတ်ကၞိကိတ်လဝ် မဒှ်အမၚ်္ဂလဝွံဂှ်) ဍေံဟွံတီ ဍေံကေတ်လဝ်ဂှ်လေဝ် လလေၚ်ဇၞော် ဒှ်ကဵုဍေံပၠန်ရ။” (ဇ—၈၇။ အစွောံ။) = “ကြွက်ကိုက်ထားသဖြင့် အမင်္ဂလာဖြစ်သော ဤအဝတ်ကို မသိဘဲယူထားသူအား ကြီးစွာသောပျက်စီးခြင်းဖြစ်လိမ့်မည်။” || “(သၟိၚ်သီုဍုၚ်ရးဂှ်) အာစိုပ်လလေၚ်ဇၞော်တုဲရ ဟွံသေၚ်ဟာ။” (ဇ—၂၁၃။ အစွောံ။) =“မင်းနှင့်တကွ တိုင်းနိုင်ငံအလုံးသည် ကြီးစွာသောပျက်စီးခြင်းသို့ ရောက်၏။” || “လောဘမ္ဂးဂှ်မဒှ်ရိုဟ်ကၞက်လလေၚ်ရောၚ်။” (ဇ—၂၅၆။ အစွောံ။) = “လောဘမည်သည်ကား ပျက်စီးခြင်း၏အရင်းအမြစ်အကြောင်းတည်း။” || “ကဵုဒါန်ဝွံ ဒှ်လလေၚ်ရ” သေဋ္ဌဳချပ်။ (ဇ—၃၉ဝ။ အစွောံ။) = “အလှူပေးခြင်းသည် ဆုံးရှုံးခြင်းပၚ်တည်း” ဟုသူဋ္ဌေးတွေး၏။ || “ဂုန်ပတေဟ်ညးပြဟ် ဒှ်လလေၚ်ကီု။” (ဂလာန်ညးတမၠာ (၂၈) သာ်) = “သူတစ်ပါးကို အယုံစောလျှင် ပျက်စီးခြင်းသို့ရောက်ရတတ်၏။” || ‘လေၚ်’ (ကြိ) လည်းရှု။')
,(12719,3,1,'ကမ္ဘာပျက်ခြင်း။','‘လေၚ်ကဝ်’ နှင့်အတူတူ။')
,(12720,3,1,'အကျိုးမဲ့။ ဆိုးကျိုး။','“ပ္တုဲကေၚ်ကာမွဲမွဲမ္ဂး ဒတုဲဖဵုကီု လလေၚ်ဖဵုကီုချပ်ဗစာရဏာဗိုန်တုဲ ဂပ်ဂဝ်ပ္တုဲရ။” = “ကိစ္စတစ်ခုခုကိုဆောင်ရွက်လျှင် ကောင်းကျိုးဆိုးကျိုးကိုသေချာစွာဆင်ခြင်ပြီးမှ ဆောင်ရွက်သင့်သည်။” || “ဘိက္ခူနံ၊ ကုဂမဳဂမၠိုၚ်။ အနတ္ထာယ၊ တၞဟ်နလလေၚ်ဖဵု။ ပရိသက္ကတိ၊ ပ္ဍံပလွဳပရာရ။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “ရဟန်းများအား အကျိုးမဲ့ဖြစ်စေခြင်းငှာ အားထုတ်၏။”')
,(12721,3,4,'၁။ ကျယ်လောင်သောအသံပြုသည်။ ပဲ့တၚ်ထပ်မျှအသံပြုသည်။ ပဲ့တၚ်ထပ်စေသည်။','“သၟိၚ်ကလိၚ်ဖေက်ဒဴအာအိုတ်တုဲ ဗဵုပၞာန်သၟိၚ်အဿကတံဝွံ တက်ကၞက်ကဵုပါၚ် ဂအတ်ရမျှာၚ် လလောၚ်ကြီုတဴရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “ကာလိၚ်္ဂမင်းပြေးသည်ကိုမြင်၍ (အဿကမင်း၏) တထောၚ်ကုန်သောအမတ်တို့သည် ကာလိၚ်္ဂမင်းပြေး၏ဟု ပဲ့တၚ်ထပ်အောင် ကြော် ငြာကုန်၏။” (ညောင်ကန်) || “ဂွံမိၚ်တဝှ်ဓဝ်ရမျှာၚ် (ဗောဓိသတ်) သၟိၚ်တ္ၚေက်ထဝ်တုဲ သာဓုကာမကမွဲလ္ၚီဂှ် မှာဇန်ဂမၠိုၚ် လလောၚ်ကဵုသာဓုကာရ။” (ဇ—၅၂၁။ အစွောံ။) = “ဘုရားလောင်းရွှေကျေးမင်း၏ ဟောသောတရားသံကို ကြားနာရသည်ရှိသော် လူအပေါင်းတို့သည် အထောၚ်မကသောကောင်းချီးပေးခြင်းကို ပဲ့တၚ်ထပ်မျှ ပေးကြကုန်၏။” || “အလုံဍုၚ်ဗာရာဏသဳ စှ်ၜါယောဇနာဂှ်နရမျှာၚ်ဗောဓိသတ်ဂှ် လလောၚ်ဗျာပ်အာ—။” (ဇ—၅၁၅။ အစွောံ။) = “ဘုရားလောင်း၏ (တရား) သံသည် တစ်ဆယ့်နှစ်ယူဇနာသော ဗာရာဏသီမြို့အလုံးကို ပဲ့တင်ထပ်မျှပျံ့နှံ့သွား၏။” || “ဗရုတွိၚ်တွိုက်သီုဖအိုတ်ဂှ် ညံၚ်သွိုဟ်ဗြဲမဒတုံပ္ဍဲမှာသၟိတ်ကီု ဗြုလလောၚ်ဒၟံၚ်ရ။” (ဇ—ဝေသန္တဝ်။အစွောံ။) = “အလုံးစုံသော တူရိယာသံတို့သည် မိုးကြီးရွာ၍ သမုဒ္ဒရာထဲကျသောအသံကဲ့သို့ တစ်ခဲနက်ပဲ့တၚ်ထပ်မျှ မြည်ဟည်းနေ၏။”')
,(12721,3,4,'၂။ ကြေညာသည်။ (သတင်းစကားစသည်ကို) အများကြားသိအောင်လုပ်သည်။ ကြွေးကြော်သည်။','“ယွံမၞးတံ၊ သြောံဝွံဂှ် တၞဟ်နကဵုဒါန်လမျီုသတ်တၠသၞေၚ်တံရောၚ်” သာ်ဂှ် ကဵုလလောၚ်ဟီုရိုဟ်ဟ်တ္ၚဲရ။ (ဇ—၅ဝ၂။ အစွောံ။) = “လူများတို့၊ ဤစပါးတို့သည် ကျေးငှက်အပေါင်းတို့အား အလှူပေးရန်ဖြစ်၏” ဟု နေ့တိုင်းနေ့တိုင်းကြွေးကြော်ကြေညာစေ၏။')
,(12722,3,4,'၁။ ကြွေးကြော်သည်။',NULL)
,(12722,3,4,'၂။ ပျံ့နှံ့ကျော်ကြားသည်။','“ဒါန်မရာတ်ဝွံ ဇၞော်ကဵုဖဵုဒြဟတ်လောန်သန်ရောၚ်။ ဒဵုကဵုဍုၚ်သွဝ်တာဝတိၚ်တေံဂှ် လလောၚ်ကမြဴတိုန်အာရောၚ်။” (ဇ—၄၉၉။ အစွောံ။) = “အရှင်မင်းမြတ်၏ အလှူဒါနသည် အလွန်အကျိုးအင်အားကြီးမား၏။ တာဝၚ်္တံသာနတ်ပြည်သို့တိုၚ် ပျံ့နှံ့ကျော်ကြားသွား၏။” || “နကြဳဇှ်ပညာ (ဗောဓိသတ်) ဒယှ်တှ်လလောၚ်ကမြဴ အလုံဇမ္မဒိပ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ဘုရားလောင်း၏ပညာအစွမ်းသည် ဇမ္ဗူဒိပ်အလုံး ပျံ့နှံ့ထင်ရှားကျော်ကြား၏။”')
,(12723,3,4,'၁။ ကြေညာသည်။ (သတင်းစကားစသည်) အများကြားသိအောင်လုပ်သည်။','“ညးလလောၚ်တရးသွံအပေါတ်ဗၞိက်။” = “ကုန်ပစ္စည်းရောင်းချရန် ကြေညာသည်။” || လိက်လလောၚ်တြး = ကြေညာချက်။ ကြော်ငြာစာ။')
,(12723,3,4,'၂။ (သတင်းစကားစသည်) အရပ်ရပ်သို့ ပျံ့နှံ့ကျော်ကြားသည်။ လူသိရှင်ကြားဖြစ်သည်။','“ဂလာန်ဂှ် ပြးလလောၚ်တြးအာအဆက်က်။” (ဇ—၅၃၄။ အစွောံ။) = “ထိုစကားသည် အရပ်ရပ်သို့ ပျံ့နှံ့ကျော်ကြားသွား၏။” || “(ဗောဓိသတ်) ဒှ်တၠပညာဇၞော်ရဂးတုဲ အလုံဂတာဇမ္မုဒိပ် လလောၚ်တရးအာအိုတ်ရ။” (ဇ—၂၅၇။ အစွောံ။) = “ဘုရားလောင်း၏ ပညာရှိသောအဖြစ်သည် အလုံးစုံသောဇမ္ဗူဒိပ်ကို နှံ့၍သွား၏။” (ညောင်ကန်)')
,(12724,3,4,'ပဲ့တင်ထပ်မျှဆူညံသည်။ ကျယ်လောင်စွာမြည်သည်။ အုတ်အုတ်ကျက်ကျက်ဖြစ်သည်။','“ဇန်တံညးဂမၠိုၚ် ဟီုထိုၚ်သးအာ ဗက်ဗဵုအာ (စိၚ်ဗ္တာၚ်ဂှ်) လလောၚ်တမ္ညဝ်တဴအိုတ်ရ။” (ဇ—၁၂၂။ အစွောံ။) = “လူအပေါင်းတို့သည် ချီးမွမ်းပြောဆိုရင်း ဆင်ဖြူနောက်သို့ လိုက်ကြည့်သွားကြသည်မှာ ပဲ့တင်ထပ်မျှ ဆူညံကုန်၏။” || “မူဗရုလလောၚ်တမ်ညဝ်ဒၟံၚ်ဂှ်ရော။” (ဇ—၂၆၉။ အစွောံ။) = “ပဲ့တင်ထပ်မျှ ဆူညံမြည်ဟည်းနေသည်မှာ ဘာအသံပါနည်း။”')
,(12725,3,4,'ကြေညာသည်။ ကြွေးကြော်သည်။ လူအများကို ပြောဆိုအသိပေးသည်။','“ဝေၚ်သဘၚ်နက်သတ် ညးလလောၚ်ဟီုအလုံဍုၚ်။” (ဇ—၁၁၈။ အစွောံ။) = “နက္ခတ်ပွဲသဘင်စကားကြမည်ဟု တစ်မြို့လုံးကြွေးကြော်ကုန်၏။” || “တ္ၚဲပၠိုတ်တုဲ ဒးကာလပၚ်မိၚ်ဓဝ် ညးလလောၚ်ဟီုအိုတ်ရ။” (ဇ—၁၇၂။ အစွောံ။) = “နေဝင်၍ တရားနာအံ့သောကာလကို ကြွေးကြော်သည်ရှိသော်—။” (ညောင်ကန်) || “ပ္ဍဲပယာံတ္ၚဲပၠိုတ်ဂှ် ဒးကာလအဲဒဝ်တရၚ်ရဂးတုဲ ပိဝါအဲလလောၚ်ဟီုတုဲ အဲဒဝ်တရၚ်ရ” ပၟၚ်တရၚ်ဂး။ (ဇ—၂၇၆။ အစွောံ။) = “မိုးချုပ်သောအခါ တံခါးပိတ်ချိန်တန်ပြီဟု ငါသည် သုံးကြိမ်ကြေညာ၍ မြို့တံခါးကိုပိတ်၏” ဟုတံခါးမှူးဆို၏။')
,(12726,3,1,'လောင်းခြင်း။ လောင်းကြေး။','“သၟိၚ်ကဵုမၚ်ဗၠာဲ၊ ကစ္စာဲတုက။ ဒှ်လလံၚ်ဇၞော်၊ ဟွံမွဲတော်ဆ။ ဟွံကေၚ်မိၚ်ဆဵု၊ ညံၚ်ဗဵုအိုတ်ရ။” (လိက်ဝိဓူရ) = “မင်းနှင့်ကစ္စာယတုကလုလင်တို့သည် မတွက်ဆနိုင်သော လောင်းခြင်းကြီးဖြစ်၏၊ မကြားမမြင်ဖူးသူများ လာကြည့်လှည့်ကြကုန်လော့။”')
,(12727,3,1,'ပျက်ခြင်း။','လလီုဓဝ်သဳလ = သီလပျက်ခြင်း။ || “(ဒၟာနူအဲတုဲ) ဗၞတ်မသြောံညးမွဲသ္ကေံညးမဒးဟုတ်အာဂှ် ဒှ်အာလလီုဂရုကဓဝ်အဲရသွံဂးတုဲ ဟိုတ်ဂှ်ရ အဲမဒးစံၚ်တူတဴရောၚ်မၞးတံ” အမာတ်ပၟၚ်ဇရာံဂှ်ဂး။ (ဇ—၂၇၆။ အစွောံ။) = “ငါ့ကြောင့် တစ်ဆုပ်ပမာဏရှိသော သူတစ်ပါးစပါးလျော့သွားရသဖြင့် ငါ၏သီလပျက်ခြင်းဖြစ်သွားလေပြီဟု ငါပူပန်နေရ၏။” || ‘လၞီ—၂’ လည်းရှု။ || ‘လီု’ (ကြိ) လည်းရှု။')
,(12728,3,4,'ထကြွသည်။ ဖြစ်ပေါ်ကြီးထွားသည်။ (?)','“ဍေံမၞုံကာမလလာဲတဴဗွဲမဂၠိုၚ်။” (လက်သန်ပကာန်ဗြဴ (၆၄) = “များစွာဖြစ်ပေါ်ကြီးထွားထကြွသောကာမရှိသည်။”')
,(12729,3,4,'၁။ ကျန်ရစ်သည်။','“ညးကွာ်ဒၟံၚ်အိၚ်ၚ်တုဲ လလုဲဒၟံၚ်လက်ကြဴရ။” = “သူသည် ဖြည်းဖြည်းလျှောက်နေပြီး နောက်တွင်ကျန်ရစ်နေသည်။” || “က္ဍိုၚ်အဲလလုဲလဝ်ပ္ဍဲသ္ၚိညးရ။” =“သူ့အိမ်တွင် ကျွန်တော့်ထီးကျန်ရစ်ခဲ့သည်။”')
,(12729,3,4,'၂။ (ကျင်ကြီးကျင်ငယ်) ယိုဖိတ်သည်။','ကၞမ်လလုဲ = ကျင်ငယ်ယိုဖိတ်သည်။ || အိက်လလုဲ = ကျင်ကြီးယိုဖိတ်သည်။')
,(12729,3,4,'၃။ (လုံချည်၊ ထဘီစသည်) ကျွတ်ကျသည်။','“လ္ၚဵုဂၞိန်လလုဲ၊ ထုဲကြာန်ဇာနာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ)')
,(12730,3,4,'နောက်ကျကျန်ရစ်သည်။','“ပိုဲမန်တအ်ဟွံညဳသာ ဟွံလွဳပရာမ္ဂး ပိုဲဒးလလုဲသၞုဲဒၟံၚ်လက်ကြဴဂကူညးတၞဟ်တအ်လၟိုန်ရ။” = “ငါတို့မွန်တွေ မညီညွတ် မကြိုးစားလျှင် အမြဲတမ်းသူများနောက်­ နောက်ကျကျန်ရစ်နေလိမ့်မည်။” || ‘သၞုဲ’ (ကြိ) လည်းရှု။')
,(12731,3,4,'ချုပ်ရိုးဖြေသည်။',NULL)
,(12732,3,1,'ကြာသောအချိန်။','“တရဴဂှ် လလအ်လဵုဒးအာရော။” = “ထိုခရီးသည်ဘယ်လောက်ကြာအောင် သွားရမည်နည်း။” || “ယွံတၠသ္ၚိ၊ ပိုဲအာကၠေံထပှ်တ္ၚဲ၊ လလအ်ပိုဲစိုပ်ဏအ်ဂှ် တၠသ္ၚိဒၟံၚ်ပ္ဍဲလွဳမာန်ဝွံရ လ္ပအာ” ဒေဝတဴပြိုတ်ဗြဴတံဂး။ (ဇ—၄၁။ အစွောံ။) = “ချစ်လင်၊ ခုနစ်ရက်မျှ အကျွန်ုပ်တို့သွားကုန်အံ့။ အကျွန်ုပ်တို့မရောက်မီအချိန်­ သင်သည် ဤဗိမာန်­ နေလော့။” || “ယွံမိတ္တဝိန္ဒက၊ လုကဴလလအ်ဝွံဂှ် မူဒၞာဲမအာကၠေံရော။” (ဇ—၄၁။ အစွောံ။) =“မိတ္တဝိန္ဒက၊ ဤမျှကြာသောကာလပတ်လုံး အဘယ်သို့သွားလေသနည်း။”')
,(12733,3,4,'ချောင်သည်။ လျော့လျည်းသည်။','“ဒက်လဝ်ဇုက်ဂှ် လလောအ်ဒၟံၚ်ရ။” =“ကြိုးကိုချည်ထားသည်မှာ ချောင်နေသည်။ (ဝါ) လျော့လျည်းနေသည်။”')
,(12734,3,1,'အပင်၏ဥ။ အမြစ်အဥ။','‘လွာ’ ရှု။')
,(12735,3,1,'အစိတ်။ အခြမ်း။','‘လွး’ ရှု။')
,(12736,3,4,'၁။ လှုပ်ခါသည်။','“ကၠဵုဂှ် ကိတ်ဂွံကၞိတုဲ လဝိုက်ရ။” = “ထိုခွေးသည်ကြွက်ကိုဖမ်းကိုက်ပြီး လှုပ်ခါသည်။” || “လမၠိုက်သ္ဂောံတိတ်အာ လဝိုက်ထောံယာတ်ဂှ်ညိ။” =“ဖုန်ထွက်သွားရန် အဝတ်ကို ခါလိုက်ပါ။” || “စိၚ်ဗ္တာၚ်ဆဒ္ဒန္တ — လွိုက်ဇကု မၚ်နန္ဒသူသီုဂမာစိၚ် ဒတုံစှ်ေရ။” (အကြီုရာဇာဓိရာဇ်) = “ဆဒ္ဒန္တဆင်ဖြူသည် ကိုယ်ကိုလှုပ်ခါရာ မင်းနန္ဒသူရော ဆင်ထိန်းပါ ဆင်ပေါ်မှကျ၏။”')
,(12736,3,4,'၂။ (လေ) တိုက်ခတ်သည်။','“ကျာၜဳလဝိုက်၊ ပိုက်ကၠုၚ်ရဝ်ရဝ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ပင်လယ်လေသည် တရစပ်တိုက်ခတ်လာ၏။”')
,(12736,3,4,'၃။ (ယပ်တောင်စသည်ဖြင့်) လေယပ်သည်။','“ဇကုအ္စာ၊ ဍေက်အာနပလက်။ ကေတ်ပၞိက်ရပ်လွိုက်၊ ပိုက်လ္ပဒဗက်။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “ချွေးနှင့်စိုသွားသောဆရာ့ကိုယ်ကို ယပ်တောင်ယူ၍ ယပ်ခတ်ပေးပါ၊ အလျင်စလိုမခတ်ပါနှင့်။” (စည်း) အချီ။ အကြိမ်။ အလှည့်။ || မွဲလဝိုက် = တစ်ချီ။')
,(12737,3,4,'ဝှေ့ယမ်းသည်။','လဝိၚ်ထၟိၚ်က္ဍိုပ် = ခေါင်းပေါင်းကို ဝှေ့ယမ်းသည်။ || လဝိၚ်သ္ဇၚ် =ဓါးရှည်ကိုဝှေ့ယမ်းသည်။')
,(12738,3,4,'စိတ်အာရုံပြောင်းအောင်လုပ်သည်။ လှည့်ပတ်သည်။','“(နန္ဒဗၞုဟ်ဗှ်သၞာဒၟံၚ် ဇနပဒကလျာဏဳဂှ်) ကျာ်လဝိၚ်ကၠေံစိုတ် ပ္ဍဲဇနပဒကလျာဏဳတုဲ ကျာ်တြဲဏာဗစိုပ်ဂြိုပ်ဟေမဝန်ရ။” (ဇ—၁၈၂။ အစွောံ။) = “ညီတော်နန္ဒသည် ဇနပဒကလျာဏီကို အောက်မေ့သတိရလျက်ရှိရာ မြတ်စွာဘုရားသည် နန္ဒ၏စိတ်အာရုံကိုပြောင်းစေ၍ ဟိမဝန္တာတောသို့ ခေါ်ဆောင်သွားတော်မူ၏။” || “တရဴမစဴဍုၚ်ကလိၚ်ကရးဂှ် ဒေဝတဴတံလွိၚ်ကၠေံစိုတ် ဗမၞးအာဟွံဒး—။” (ဇ—ဝေသန္တဝ်။အစွောံ။) = “ကာလိၚ်္ဂရာဇ်တိုင်းသို့ ပြန်မည့်ခရီးကို နတ်တို့လှည့်ပတ်သဖြင့် ပုဏ္ဏားသည်မပြန်တတ်။”')
,(12739,3,4,'ဝှေ့ယမ်းသည်။','“အဲပေါရိသာဒရ” ဂးတုဲ ဂအတ်ရမျှာၚ်ပိဝါတုဲ လဝိၚ်ဂလိသၞာ်။ (ဇ—၅၃၇။ အစွောံ။) = “ငါပေါရိသာဒကွ” ဟုဆိုကာ သုံးကြိမ်ဟစ်ကြွေးကြုံးဝါး၍ သန်လျက်ကိုဝှေ့ယမ်း၏။')
,(12740,3,4,'မျက်နှာလှည့်သည်။','“(ကျာ်တြဲ) လဝိၚ်မုက္ခဝါ ဂတဒိုဟ်လ္ပာ်ဗၟံက်ပလိုတ်။” (ရာဇာထ္ၜုတ်) = “မြတ်စွာဘုရားသည် မျက်နှာတော်ကို လှည့်တော်မူ၍ အရှေ့ဘက်နှင့်အနောက်ဘက်ဆီသို့ မျက်နှာမူတော်မူ၏။”')
,(12741,3,4,'ရှောင်ရှားသည်။ ရှောင်ကြဉ်သည်။','‘ဝေၚ်’ (ကြိ) ရှု။')
,(12742,3,16,'‘အဝဲါ’ ရှု။',NULL)
,(12743,3,5,'‘အဝဲါဂှ်’ ရှု။',NULL)
,(12744,3,4,'၁။ စွန့်သည်။ ချန်ပစ်သည်။ ထားရစ်သည်။','“သီုကဵုကလောဂမၠိုၚ် မဏှဳတဴဍာ်ရမတ်ဂှ် လသာထောံလဝ်တုဲ တိတ်ပခမဳရ။” (ဇ—၁၄၆။ အစွောံ။) = “မျက်ရည်စက်လက်ဖြင့်ငိုကြွေးသောဆွေမျိုးတို့ကို စွန့်ထားရစ်ခဲ့၍ ရဟန်းပြုကုန်၏။” || “မိမအဲၜါဝွံဂှ် ပိုန်ဒြပ်ဂလိုၚ်ဝွံမဇမၞော်ပၟဝ်လဝ်တုဲ ၜးအတ္တဘဴဂှ် ဒြပ်တံဂှ် ဟွံဂွံကေတ်ဏာ လသာလဝ်တုဲ တဲလမ္ၚုမအာရောၚ်သွံ။” (ဇ—၃၁၃။ အစွောံ။) = “ငါ၏မိဘတို့သည် ဤမျှများလှစွာသောဥစ္စာတို့ကို ပွားများထားပြီးနောက် သေလွန်သောအခါ မယူသွားနိုင်ဘဲ စွန့်ထားကြရပြီးလျှင် လက်ချည်းစည်းသွားကြရကုန်၏။”')
,(12744,3,4,'၂။ ပြန့်ကြဲသည်။','“ကၠိက်ၜါလပါ်ဂှ် ဗျာံလဝ်ဂၞေဟ်တုဲ (တုက်ကၠဂှ်) ဂၞဴကၠညံၚ်ညးစာကၠေံ ကဵုၜုန်ဇမ္ကေက်ရ။ ကြုတ်တိတ်လသာဒၟံၚ်တုဲ ဒးပကာဂစိုတ်ရ။” (ဇ—၂၈၃။ အစွောံ။) =“နှစ်ဖက်မှဝက်တို့သည် အစွယ်တို့ဖြင့် ချိန်ရွယ်ထားပြီးလျှင် ကျားကိုထိုးခတ်သည်ရှိသော် ကျား၏ဝမ်းသည် ချွန်ထက်သောဓါးဖြင့် လှီးခွဲဘိသကဲ့သို့ အအူတို့သည် ထွက်ကျပြန့်ကြဲလျက် ကျားသည် သေရလေ၏။”')
,(12745,3,4,'ခန္ဓာစဲသည်။ ခန္ဓာကိုစွန့်သည်။ သေလွန်သည်။','“လသာခန္ဓတုဲ သုဂ္ဂတိဘုံ က္တဵုဒှ်ဇမူ။” (အာန်ဇုနာန်) = “သေလွန်ပြီးနောက် သုဂ္ဂတိဘုံသည် ခိုနားရာဖြစ်၏။”')
,(12746,3,1,'လှော်တက်။','‘ကသု’ နှင့်အတူတူ။')
,(12747,3,4,'ပင်ပန်းဆင်းရဲသည်။ ပူလောင်ခံစားရသည်။','“ပိမကဵုကောန်၊ ဒက်ဒေါန်နာနာ။ ထောံမတ်စမဳ၊ ၚဳလတူကျာ။ ဟွံညာတ်သက်လှက်၊ လသက်လသာ။” (လိက်သောဝါနနဟောၚ်) = “သားအဖသုံးဦးတို့သည် အမျိုးမျိုးရေရွတ်မြည်တမ်းလျက် လေပေါ်သို့မျှော်ကြည့်ကာ မမြင်ရသည်ဖြစ်၍ စိတ်ပင်ပန်းဆင်းရဲ၏။” || “သိုဟ်ဂၞဴဂျိသ္ပာတ်သ္ဗ၊ ဂန္ဓလသက်လသာ။” (လိက်လက္ခဏဒိပ္ပဗိန္ဒော) = “ရင်နှင့်ဝမ်းထိုးကျင့်နာကျင်၍ ခန္ဓာကိုယ်ပူလောင်ခံစားရသည်။”')
,(12748,3,4,'၁။ ကျော်လွန်သည်။',NULL)
,(12748,3,4,'၂။ (လှေမှရေကို) ပက်ထုတ်သည်။','‘သာတ်’ (ကြိ) ရှု။')
,(12748,3,4,'၃။ စုအုံသည်။ စုပြုံသည်။ (?)','“ကျာံဂမၠိုၚ်ညာတ်၊ လသာတ်ကၠုၚ်ကၠာ။” (လိက်ကကၠာ်။ကောန်ဍး။) = “မိကျောင်းများမြင်၍ စုံအုံ၍လာကြ၏။”')
,(12749,3,4,'ချည်နှောင်ထားရာမှပြေသည်။',NULL)
,(12750,3,11,'(န) ကြက်သွန်။ (ပါဠိ—လသုဏ/လသုန)','လသိုန်ဗ္တာၚ် = ကြက်သွန်ဖြူ။ || လသိုန်ဗကေတ် = ကြက်သွန်နီ။ || “ပုၚ်သြောံသာလဳကီု ကၠေၚ်သွဟ်ကီု ၜဵုကီု လသိုန်၊ လဂဝ်၊ ကၞိ၊ မြေက်ကီု။” (ဇ—၃၂၅။ အစွောံ။) = “သလေးထမင်းကို၄င်း၊ ထောပတ်ကို၄င်း၊ ဆားကို၄င်း၊ ကြက်သွန်၊ ဂျင်း၊ ပိတ်ချင်း၊ ငရုတ်ကို၄င်း။” || ‘ကသိုန်’ ဟုလည်းတွေ့ရသည်။')
,(12751,3,1,'မိုးရာသီ။','“မွဲလသီုပန်ဂိတုဂှ် ကလိလောန်အာတုဲ—။” (ဇ—၃၄၆။ အစွောံ။) = “တစ်မိုးလေးလကာလလွန်လတ်သော်—။” || ‘ကသီု’ နှင့်အတူတူ။')
,(12752,3,4,'ဖြန့်ကြဲသည်။ ပြန့်ကြဲသည်။','‘တသဵု’ (ကြိ) နှင့်အတူတူ။')
,(12753,3,10,'(န) တစ်မတြာမျှသောအသံ။ လဟု။','“ဂရုလဟုပၠန်၊ ပိုတ်ဗျန်သီုယတိ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ဂရု၊ လဟု၊ ပုဒ်၊ ဗျည်း၊ ယတိ။”')
,(12754,3,11,'(န) ပေါသောပစ္စည်း။ အလေးမပြုသင့်သည်ဖြစ်၍ ခွဲဝေရာသောပစ္စည်း။ လဟုဘဏ်ပစ္စည်း။ (ပါဠိ—လဟုဘဏ္ဍ)','‘ဂရုဘဏ်’ လည်းရှု။')
,(12755,3,4,'လေသလပ်ထားသည်။ ဝန်းကျင်လေနှင့် ထိတွေ့စေသည်။','“ဂြောဝ်တုန် အမာဲကဖျုန်ပကာရတၟေၚ်သာ် စဳရေၚ်ပ္တုဲတုဲ တၞဟ်နလၜိုဟ်လဟဲသၟုဟ် လမဳပံက်ဖျေၚ်ကၠေံတုဲ—။” (ဇ—၄၂။ အစွောံ။) = “ထမင်းချက်သည် အထူးထူးအပြားပြားသော ငါးအမဲတို့ကို စီရင်ပြီးစီး၍ အငွေ့ထွက်စေရန် လေသလပ်ထားရန် အိုးအဖုံးတို့ကို အတန်ငယ်စောင်းလျက်ဖွင့်၍။”')
,(12756,3,1,'ဆင်ကကြိုးတန်ဆာ။','“စိၚ်သီုလဟးထဝ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ရွှေကကြိုးတန်ဆာနှင့်တကွသောဆင်။”')
,(12757,3,4,'ဟောဟဲလှိုက်၍အသက်ရှူသည်။ အလွန်မောပန်းသည်။','“ညးမွဲချပ်ချာဲ၊ဂၠာဲပမတ်ညိ။ ဆဵုကလဵုလိၚ်၊ ဗစဳသွိၚ်ဂၠိ။ သလှ်ေပၟတ်သွံ၊ ဟွံစံၜတ်ညိ။ — ပအံၚ်ကျာဂၞဴ၊ ဗ္ဂဵုတဴဒမၠိ။ဣဝီုတဟက်၊ ဟွံဂွံအဂ္ဂိ။” (လိက်ပဒုမဝတဳ) = “တစ်ယောက်သောသူသည် မီးကိုရှာရန်ကြံသည်ရှိသော် လင်းလက်နေသော ပိုးစုန်းကြူးကိုတွေ့၍ မစုံစမ်းမူဘဲ မီးအမှတ်ဖြင့် ဝမ်းတွင်းလေကိုအောင့်ကာ ကြိုးစား၍မှုတ်ငြားသော်လည်း ထွက်သက်ဝၚ်သက် ဟောဟဲလှိုက်၍ မီးကိုမရ။”')
,(12758,3,4,'မောဟိုက်သည်။ ဖတ်ဖတ်မောသည်။','“ဇကုက္တဴသ္ဂီုသ္ဂီု၊ ယဝီုတဟက်ဍောၚ်။” (လိက်လက္ခဏဒိပ္ပဗိန္ဒော) = “ကိုယ်နွေးနွေးပူကာ အသက်ရှူကျပ်၍ မောဟိုက်သည်။” || “ယွီုလေဝ်လဟက်ဍောၚ်၊ တမောင်ဍေံက္ဍၚ်အာ။” (လိက်လက္ခဏဒိပ္ပဗိန္ဒော) =“အသက်ရှူကျပ်၍ မောဟိုက်ကာ အမောလွန်ကဲသွား၏။”')
,(12759,3,4,'ဒေါသဖြစ်သည်။ ဒေါမွှန်သည်။','“ကၟိန်ပိုဲပလဟုက်ဂၠိုၚ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “ငါ့တူတော်ဒေါသမများပါနှင့်။” || “မၚ်ရာဲကယျဝ်ဆွာ ဂွံမိၚ်သာ်ဂှ်တုဲ လဟုက်ဂၠိုၚ်တိုန်ရ။” (အကြီုရာဇာဓိရာဇ်) = “မင်းရဲကျော်စွာသည် ထိုသို့ကြားရသည်ရှိသော် ပို၍ဒေါမွှန်လာ၏။” || “ချိုန်ဗညာနဲ ဂွံမိၚ်ကေတ်ဂလာန်သာ်ဂှ်တုဲ လဟုက်မံၚ်ပ္ဍဲစိုတ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “ဗညားနွဲ့သည် ထိုစကားကိုကြားရသည်နှင့် စိတ်ထဲတွင်ဒေါသဖြစ်နေ၏။” || “စိုတ်မၚ္ငိုဟ်ကြံၚ်၊ လဟုက်ညံၚ်ကၠ။” (လောကသိဒ္ဓိ။ အစွောံ။) = “စိတ်ကြမ်း၍ ကျားကဲ့သို့ ဒေါသထွက်တတ်၏။”')
,(12760,3,1,'ဒေါမာန်ဟုန်။','“(ကမၠတ်တံဝွံ) သီုလဟုက်မာန် သ္ဍံၚ်ဗက်အာကမၠတ်သီုဒြပ်တံတေံ။” (ဇ—၄၈။ အစွောံ။) = “ဤခိုးသူတို့သည် ဒေါမာန်ဟုန်ဖြင့် ဥစ္စာနှင့်တကွသော ထိုခိုးသူတို့နောက် ထက်ကြပ်မကွာလိုက်သွား၏။”')
,(12761,3,1,'ဇက်ကြိုး။','ဇုက်လဟေက်ချေံ = မြင်းဇက်ကြိုး။ || “ယွံသဟာဲပိုဲသိန္ဓဴ၊ — ပ္ဍဲသၟန်ပါၚ်ဗှ်ေတ္ၚံက်ဒၟံၚ်ဂှ် ညးစုတ်လဟေက်—” ဗ္ၜေံဂး။ (ဇ—၃၈၆။ အစွောံ။) = “အဆွေသိန္ဓောမြင်း၊သင်၏ကောက်သောနှုတ်ခမ်း­ ဇက်ကြိုးတပ်ထား၏” ဟုဆိတ်ဆို၏။')
,(12762,3,1,'လက်ဝါးတစ်ခုပ်စာပမာဏ။','‘ဇဟာၚ်’ (န) နှင့်အတူတူ။')
,(12763,3,1,'၁။ အအိပ်။ အိပ်ခြင်း။ အိပ်ရေး။','“ဗောဓိသတ်ပၠန် ဟိုတ်ဒှ်တြဴအဓါန်မဂၠိၚ်သ္ၚောဲ မအောန်ကဵုလဟိၚ် ဍောၚ်ၜိုတ်ဂှ်ဒှ်တုဲ နလဟိၚ်မဇၞော် လှိၚ်တဴရ။” (ဇ—၂။ အစွောံ။) = “ဘုရားလောင်းသည် ခရီးရှည်ဖြစ်ခြင်းကြောင့် အိပ်ရေးနည်းကာ ပင်ပန်းသည်ဖြစ်၍ ကြီးစွာသောအိပ် ခြင်းဖြင့် အိပ်စက်လေ၏။”')
,(12763,3,1,'၂။ ကြည်နူးခြင်း။ မွေ့လျော်ခြင်း။ မွေ့လျော်ဖွယ်။','“ဒးမံၚ်ဖဴဍေံဂှ်လဟိၚ်အဲဟွံမွဲသက်က်ရ။” = “သူနှင့်အတူနေရသည်မှာ ငါ့မှာ မွေ့လျော်ပျော်ပိုက်ခြင်း အလျှင်းမရှိပါ။” || “ပူဂဵုမပဒတဴပ္ဍဲသ္ၚိကၟိန် မၞုံလဟိၚ်ပ္ဍဲကာမဂုန်မသုန်ပြကာ—။” (ဇ—၄၁၁။ အစွောံ။) =“ကာမဂုဏ်ငါးပါး­ မွေ့လျော်ခြင်းရှိသော အိမ်ထောင်­နေသောသူ။” || “ပြာသာတ်ဝေဒယန္တဝ် မဒှ်လဟိၚ်မာဃ နွံတဴသွံ။” (သၠပတ်သတိပထာန်) = “သိကြားမင်း၏မွေ့လျော်ရာ ဝေဇယန္တာပြာသာဒ်သည် ရှိသည်တကား။”')
,(12763,3,4,'ပျော်ရွှင်သည်။ ကြည်နူးသည်။','“ဍေံကလၚ်ဒၟံၚ်ဒွက်တုဲလဟိၚ်ဒၟံၚ်ရ။” = “သူသည် သီချင်းနားထောင်နေပြီး ကြည်နူးနေသည်။” || ‘ဋ္ဌာန်ဂြိုပ်လဟိၚ်စိုတ်အဲ။’ (ဇ—၄၈၈။ အစွောံ။) = ‘ငါ၏နှလုံးမွေ့လျော်ဖွယ်တောအရပ်။’')
,(12764,3,1,'စိတ်ကြည်နူးခြင်း။ စိတ်ပျော်မွေ့ခြင်း။ နှလုံးမွေ့လျော်ခြင်း။','“သၟိၚ်သာဓိနဂွံပကၚ်ရစသိုၚ် ပိုန်တသိုက်ဒိပ်ဂှ် လုကဴထပှ်ကၠံသၞာံမၞိဟ်ဂှ် ကလိလောန်အာတုဲ — လဟိၚ်စိုတ်ဟွံမွဲဂှ်သၟိၚ်ဣန်တီတုဲ ကဵုမာတလိပလံၚ်ဖျေံနၚ် (ဍုၚ်မၞိဟ်ပၠန်) ရ။” (ဇ—၄၉၄။ အစွောံ။) = “သာဓိနမင်းသည် နတ်စည်းစိမ်ကို လူ့သက်တမ်းအားဖြင့် အနှစ်ခုနစ်ရာတို့ပတ်လုံး စံစားပြီးနောက်စိတ်ပျော်မွေ့ခြင်းမရှိတော့သည်ကို သိကြားမင်းသိ၍ မာတလိနတ်သားကို မင်းအား လူ့ပြည်သို့ ပြန်ပို့ဆောင်စေ၏။” || ‘လှိၚ်စိုတ်’ (ကြိ) လည်းရှု။')
,(12764,3,4,'စိတ်ပျော်မွေ့သည်။ စိတ်ကြည်နူးသည်။','“ဍေံကလၚ်ဒွက်တုဲ လဟိၚ်ဒၟံၚ်စိုတ်ရ။” = “သူသည် သီချင်းနားထောင်ပြီး စိတ်ကြည်နူးနေသည်။”')
,(12765,3,4,'စိတ်ကြည်နူးသည်။ နှလုံးမွေ့လျော်သည်။','မိပ်ဇြိပ်လဟိၚ်လဟာဲ = ပျော်ရွှင်ကြည်နူးသည်။ || “လဟိၚ်လဟာဲဒၟံၚ် ဂၠံၚ်လပါ်ကုသဵု။” (မိတၠထဝ်။ ပါလိတ။) = “ကုသိုလ်ရေးဘက်­ နှလုံးမွေ့လျော်၏။” || “ညံၚ်ဂွံလဟိၚ်လဟာဲမြဟ်မြဴဒၟံၚ် ပ္ဍဲကဵုအရီုဓဝ်ညးသပ္ပရိုဟ်တအ်မာန်။” (လိက်လၟေတ်) = “သူတော်ကောင်းတို့၏တရား­ မွေ့လျော်ရွှင်ပျော်နေနိုင်စေရန်အတွက်။”')
,(12766,3,4,'လှည့်လည်သွားလာသည်။ ကျက်စားသည်။ (သံသရာတွင်) ကျင်လည်သည်။','‘ဂ္ၚေၚ်’ နှင့်အတူတူ။ || “အိုတ်သတ်မမံၚ်၊ ပ္ဍဲခြိုၚ်သံၚ်သာ။ ဒးဟဳဂေတ်ဂေၚ်၊ လဟေၚ်ဘဴကၠာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) (လဟေၚ်ဘဴ = ဂ္ၚေၚ်ဘဴ၊ ဂ္ၚေၚ်ဘဴသံၚ်သာ) = “သံသရာလှောင်ချိုင့်ထဲ­ နေသောသတ္တဝါအပေါင်းတို့သည် ဘဝသံသရာဝယ် တပြောင်းပြောင်းတပြန်ပြန်ကျင်လည်နေရကုန်၏။”')
,(12767,3,4,'ထိတ်လန့်သည်။','‘သမ္ၚာတ်’ နှင့်အတူတူ။ || “တုဲမၚ်ဗၠာဲညာတ်၊ လဟာတ်ဓမြဴ။ပ္ဍဲဇကုအဴ၊ ဂြဴဂြဴဒှ်တိုန်။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “လုလင်မြင်သော် ထိတ်လန့်တုန်လှုပ်၍ ကြက်သီးမွေးညှင်းထ၏။” || “ကောန်ခဏောဝ်ညာတ်၊ လဟာတ်ဘိၚ်ဘၚ်။” (လိက်ကကၠာ်။ကောန်ဍး။)')
,(12768,3,11,'(န) တစ်သောင်း။ (ပါဠိ—နဟုတ)','‘တိဇၞော်မၞုံတဴသတီု ၜါလက်ယောဇနာ ကဵုပန်လဟုတ်ပရဲ။’ (ဇ—၇၂။ အစွောံ။) = ‘နှစ်သိန်းလေးသောင်းအထုရှိသော မဟာပထဝဳမြေကြီး။’')
,(12769,3,1,'၁။ ဆုတ်ယုတ်ခြင်း။ လျော့နည်းခြင်း။ လျော့ပါးခြင်း။','“ယဝ်သဒှ် (သာ်) ဂှ် သြောံသၟိၚ်ဇၞော်မောဝ်ဂၠိုၚ်အာရ။ သြောံဂဟပ္ပတိဂှ် ဒှ်လဟုတ်ရ။” (ဇ—၂၇၆။ အစွောံ။) = “ထိုသို့ဖြစ်လျှင် မင်း၏စပါးသည် တိုးများသွားလိမ့်မည်။ သူကြွယ်၏စပါးသည် လျော့ပါးသွားလိမ့်မည်။”')
,(12769,3,1,'၂။ ဆုံးရှုံးခြင်း။ ပျက်စီးခြင်း။ အကျိုးယုတ်ခြင်း။','“အဲ (ဇက်ပၞာန်) သ္အာလၟုဟ်ဝွံဂှ် ဒှ်ဒတုဲမြမောဝ်ကီု ဒှ်လဟုတ်ကီု ကျာ်တြဲမတီရောၚ်” သၟိၚ်ချပ်။ (ဇ—၁၇၆။ အစွောံ။) = “ယခုငါစစ်ချီထွက်ရာ­ အကျိုးစီးပွားဖြစ်ခြင်းကို၄င်း အကျိုးယုတ်ခြင်းကို၄င်း မြတ်စွာဘုရားသည် သိတော်မူပေလတ္တံ့” ဟုမင်းကြံ၏။ || “ယွံညးမသၟဟ်ကဵုပိုဲ၊ ယြဴပူဂဵုမွဲ မဒးနှဴကေုာံပူဂဵုသမၠီုဂှ် တသိုက်စိုတ်ကီုတသိုက်ကာယျကီု ဟွံကလိဂွံရ၊ လဟုတ်မဒးဒှ်ရ။” (ဇ—၂၇၂။ အစွောံ။) = “အဆွေ၊ သူမိုက်နှင့်တကွပေါင်းဖော်သော အကြင်ပုဂ္ဂိုလ်သည် စိတ်၏ချမ်းသာခြင်းကို၄င်း ကိုယ်၏ချမ်းသာခြင်းကို၄င်း မရ၊ ဆုံးရှုံးခြင်းသာဖြစ်ရ၏။” || ‘ဟုတ်’ (ကြိ) လည်းရှု။')
,(12769,3,4,'၁။ ယုတ်လျော့သည်။လျော့ပါးသည်။','“ပ္ဍဲသ္ၚိမၞးတံဂှ် ဒြပ်ရတ်ထပှ်ပြကာ အဲသၟိၚ်ဣန်ဗပေၚ်လဝ်တုဲ ဟွံကဵုအိုတ်လဟုတ်ကဵုဂွံစဒၟံၚ်တွဵုအယုက်ရ။” (ဇ—၃၅၄။ အစွောံ။) = “သင်တို့အိမ်­ ရတနာခုနစ်ပါးကို ငါသိကြားမင်းဖြည့်ထားကာ မကုန်ခန်းမယုတ်လျော့စေဘဲ တစ်သက်ပတ်လုံး စားနေရစေမည်။”')
,(12769,3,4,'၂။ပျက်စီးသည်။ ဆုံးရှုံးသည်။','“သၟိၚ်ဟွံတဴပ္ဍဲဓဝ်ဂှ် ညးဂစိုတ်ကၠေံဍေံ ဒးလဟုတ်လမျီုရ။” (ဇ—၁၉၄။ အစွောံ။) = “တရားမစောင့်သောမင်းသည် သူတစ်ပါးတို့သတ်၍ အသက်ဆုံးရှုံးရလေ၏။”')
,(12770,3,1,'ကမ္ဘာပျက်ခြင်း။',NULL)
,(12771,3,1,'အကျိုးစီးပွားပျက်စီးဆုံးရှုံးခြင်း။','“ပူဂဵုစိုတ်ဟွံခိုဟ်တုဲဂှ် လဟုတ်ဒတုဲမြမောဝ်မဒးဒှ်ရ။” (ဇ—၂၈၈။ အစွောံ။) = “မကောင်းသောစိတ်ရှိသူသည် အကျိုးစီးပွားပျက်စီး ခြင်းဖြစ်ရာ၏။”')
,(12772,3,4,'အသက်ဆုံးရှုံးခြင်း။ သေကြေပျက်စီးခြင်း။','‘စဒးသတ်ဆုဂျိဝွံတုဲ ဒးစိုပ်လဟုတ်လမျီု။’ (ဇ—၅၄။ အစွောံ။) = ‘ဤအဆိပ်သီးကို စားမိသဖြင့် အသက်ဆုံးရှုံးခြင်းသို့ရောက်ရလေ၏။’ || “ပ္ဍဲကာလဂှ် ဒြာဲဂမၠိုၚ် ဒှ်လဟုတ်လမျီုဂၠိုၚ်သန်ရ။” (ဇ—၁၁။ အစွောံ။) =“ထိုအခါ­ များစွာကုန်သောသမင်တို့သည် သေကြေပျက်စီးခြင်းသို့ ရောက်ကုန်၏။”')
,(12773,3,1,'ဆုံးရှုံးခြင်း။ အရှုံး။','“ပၞောဝ်လဟုံပိုဲညးၜါ လဟုံတၠအဲမဇၞော်ရောၚ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ငါတို့နှစ်ဦး၏အရှုံးအနက် သင်၏အရှုံးက ပို၍ကြီး၏။” || ‘အဟုံ’ (န) နှင့်အတူတူ။ || ‘ဟုံ’ (ကြိ) လည်းရှု။')
,(12774,3,4,'‘သ္ၚောံ’ ရှု။',NULL)
,(12775,3,4,'နောင်တရသည်။ မှားခဲ့သဖြင့် နောင်အခါပူပန်သည်။','“ဟိုတ်ဍေံပသၞ၊ တလပညာ။ ဒးလဟုံမှာ၊ အစာဂးရောၚ်။” (လိက်ဝိဓူရ) = “ပညာရှိကို ရန်ပြုသောကြောင့် နောင်အခါပူပန်ရမည်ဟု ဆရာဆို၏။” || “ဗွဲကြဴဒေၚ်ဗျောံ၊ ဒးလဟုံမှာ။” (လိက်ဝိဓူရ) = “နောင်အခါေၚးမှိုင်၍ မှားကြောင်းပူပန်နောင်တရ၏။” || ‘သ္ၚောံမှာ’ ရှု။')
,(12776,3,1,'အပြောအဆို။ စကား။','“ပတွဵုနူဂှ်တုဲ လဟီုမွဲဒၞာဲမဟီုဂှ် စၚ်ခြၚ်စမ်ၜတ်တုဲမဟီုရ။” (ဇ—၃၃၁။ အစွောံ။) = “ထိုအခါမှစ၍ စကားတစ်ခုကိုပြောဆိုသော် စဉ်းစားဆင်ခြင်ပြီးမှ ပြောဆို၏။” || “ညံၚ်လဟီုညးဂမၠိုၚ် ကၠိက်ဂှ်ပတုဲ—။” (ဇ—၁၅၃။ အစွောံ။) = “ထိုဝက်သည် အများ၏အကြံပေးစကားအတိုင်း လုပ်၏။”')
,(12777,3,1,'စကားများခြင်း။','“သၟိၚ်ဂှ်တုန် မၞုံလဟီုဂၠိုၚ်လောန်။” (ဇ—၃၃၁။ အစွောံ။) =“ထိုမင်းသည်ကား များသောစကားရှိ၏။”')
,(12778,3,1,'အပြောအဆို။','“ပွမဂၠိုၚ်ကဵုလဟီုလဂးဂလာန်ဗဒါန်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) =“စကားအပြောအဆိုများလွန်းခြင်း။” || “လဟီုလဂးဟွံဒးရး။” (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “မလျောက်ပတ်သောအပြောအဆို။” || “ကာလမဂျိုၚ်တဴလမျီုဂှ် လဟီုလဂးဂြိုဟ်စာ။” (သၠပတ်ကာလထေ) = “အသက်ရှင်တုန်းအချိန်တွင် အပြောအဆိုရင့်သီးခက်ထန်၏။” || “လဟီုလဂး ပကဵုဂၠိုၚ်အန်။” (အာန်ဇုနာန်) = “အပြောအဆိုမများစေမနည်းစေနှင့်။” (သင့်ရုံပြောဟူလို။) || “ဒဝုဲကဝါ်၊ မွဲသာ်ဟွံယောၚ်။ လဟီုလဂး၊ ဟွံဗၠးမွဲတောင်။” (လိက်သောဝါနနဟောၚ်) = “အမူအရာလည်း တစ်စုံတစ်ရာမချွတ်ယွင်း၊ အပြောအဆိုလည်း တစ်စုံတစ်ရာမလွဲမှား။”')
,(12779,3,4,'(ပုခက်လွှဲသကဲ့သို့၊ ဒန်းစီးသကဲ့သို့) လှုပ်ရှားသည်။ (ငှက်ကဲ့သို့) ဝဲပျံသည်။','“(နူလတူဒဵုဂှ်) လၟပြာၚ်ကၠေံက္ဍိုၚ်သၞာံဂှ်တုဲ — ညံၚ်ရဴဂစေံပဝ်ကီု လဟုဲစှ်ေအာရ။” (ဇ—၅၁၄။ အစွောံ။) = “မုဆိုးသည် တောင်ပေါ်မှ သားရေထီးကိုဖွင့်၍ ငှက်ပျံသကဲ့သို့ (လေဟုန်စီး၍) ဝဲပျံဆင်းသွား၏။” || “(လကိုဟ်ဂှ်) ဍေံသွက်ကေတ်ဇိုၚ်ၜါ (ဗောဓိသတ်) တုဲ ဍေံဒဟုဲဖျေံဏာဗက် ညံၚ်စက်ဗဝ်မှောဝ်ကီု သီုဇကုဗောဓိသတ် ဂေတ်ဒဟုဲဒၟံၚ် ဇကုဗောဓိသတ်ဂှ် ဂေတ်တဴရ။” (ဇ—ဝိဓုရ။အစွောံ။) = “ထိုဘီလူးသည် ဘုရားလောင်း၏ ခြေနှစ်ဖက်ကိုဆွဲ၍ လွှဲ၍ပစ်ချသည်ရှိသော် ဘုရားလောင်း၏ကိုယ်သည် အိုးထိန်းစက်ကဲ့သို့ တွဲလျားလည်ပတ်လှုပ်ရှားနေ၏။” || “လၟေၚ်ဆုအိုဿီုတံဂှ် ကာလမဒးလဗိုတ်ကျာပိုက် ဂရိုက်ဂရာၚ်ကၞာၚ်လဟုဲ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) =“အလုံးစုံသောသစ်ပင်တို့သည် လေပြင်းထိသောအခါ ပုခက်လွှဲသကဲ့သို့ ဘေးဘယ်ညာလှုပ်ရှားတုန်ခါကုန်၏။” || “ပြိုၚ်စုတ်သရေၚ်၊ နတဲဟေၚ်ရ။ လဟုဲဖလှိၚ်၊ လဟိၚ်ဝကျ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “(သားကို) ပုခက်တွင်ထည့်ကာ လက်ဖြင့်လွှဲ၍ မွေ့လျော်ဖွယ်သံစဉ်ဖြင့်ချော့သိပ်၏။”')
,(12780,3,1,'နှဲ။ နှဲကြီး။ မွန်နှဲ။','“လဟဝ်ဆာၚ်ရိုက်၊ တိုက်အလုံတိ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “နှဲကြီးလၚ်ကွင်းတို့ကို မြေလုံးအနှံ့ တီးခတ်ကုန်၏။” || “ပုက်တလုက်ဗဝ်၊ အဟဝ်ခရာ။ တက်မံၚ်ဂြုဂြု၊ ဗြုတမ္ညဝ်အာ။” (လိက်တပူတဗဝ်)')
,(12781,3,1,'မျက်ရှု။ ရူမငြီးဖွယ်။','“ယွံလဟောဝ်မတ်၊ ဇန်သတ်လိုက်ဗာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “အို—လောကသတ္တဝါတို့၏မျက်ရှု။” || ‘ဒ္ၚောဝ်မတ်’ နှင့်အတူတူ။')
,(12782,3,4,'၁။ ပြုပြင်သည်။ မွမ်းမံသည်။','“ကျာ်စေတဳတြေံဂှ် ညးကလေၚ်လဟဵုလဝ်တၟိရ။” =“ဘုရားစေတီဟောင်းကို အသစ်မွမ်းမံပြုပြင်ထားသည်။” || “ဒဵုလာ်အာကီု ဟွံဂပ်ဂဝ်လဟဵု၊ ဆဨကရာတ်မွဲကီု ဂပ်ဂဝ်လဟဵု။” (လိက်သၚ်္ခါရလိုက်) = “တောင်ပြိုသွားသည်ကို လူတို့မပြုပြင်သင့်၊ မင်းဧကရာဇ်တစ်ပါးသာလျှင် ပြုပြင်သင့်၏။”')
,(12782,3,4,'၂။ ထွန်းပသည်။ ထွန်းတောက်သည်။','“နန်ထဝ်လဟဵု၊ ဂဵုခၠၚ်ဗစဳ။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။) = “ရွှေနန်းတော်သည် အရောင်တဖိတ်ဖိတ် ထွန်းပပြောင်လက်၏။” || “ဍုၚ်ဝွံပြဲဖာ၊ ပြာထာလဟဵု။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။) = “မြတ်သောဤမြို့သည် ကျော်စောထွန်းပ၏။”')
,(12783,3,4,'ဒေါမာန်ဖြင့်ဝၚ်လာသည်၊ ရှေ့တိုးသည်။','“ဟာဲကၠ၊ — ဗှ်ေကၠတၠဂၞေဟ်မသ္ကေက်ရောၚ်။ မူပမဖေက်ကၠိက်ဂှ်ရော။ ဗှ်ေအာမွဲဝါရ။ လ္ပဖေက်ဍေံ ဗှ်ေလဟဵုလုပ်တုဲ ဍေံမဒးဆုတ်ဒဴအာရ” ဣသိစၞာဲဂး။ (ဇ—၄၉၂။ အစွောံ။) = “ဟယ်ကျား၊ သင်သည်ကား ထက်သောအစွယ်ရှိသောကျားတည်း။ ဘာကြောင့်ဝက်တို့ကို ကြောက်ရမည်နည်း။ တစ်ကြိမ်သွားဦးလော့။ မကြောက်နှင့်၊ ဒေါမာန်ဖြင့်သင်ရှေ့တိုးဝၚ်လျှင် ဝက်တို့ဆုတ်ပြေးကြရလိမ့်မည်” ဟုရသေ့စဉ်းလဲဆို၏။ || “(လကိုဟ်ဗြဴ) ယက္ခဒေဝဳပၠန်တုန်လေဝ် ဍေံလဟဵုကၠုၚ်တုဲ (ဍေံလက်ဍေံထၞိက်စန္ဒဝတဳရ။)” (သၠပတ်စန္ဒဝတဳ) = “ယက္ခဒေဝီဘီလူးမသည် ဒေါမာန်ဖြင့်လာကာ စန္ဒဒေဝီအားဆဲဆိုကန်ကျောက်၏။”')
,(12784,3,4,'မျက်စိမှိတ်သည်။ မျက်တောင်ခတ်သည်။','“သဘဴကလော်စၟတ်မ္ဂးဂှ် မတ်ဍေံဟွံလၜဲရောၚ်။ သမၞိၚ်ဇကုဍေံ ဟွံမွဲရောၚ်။ မတ်ဍေံဗကေတ်တဴရောၚ်။” (ဇ—၅၁၃။ အစွောံ။) =“ဘီလူးတို့၏မျက်စိတို့သည် နီကုန်၏၊ မမှိတ်ကုန်၊ အရိပ်သည်မထၚ်။” (ညောင်ကန်) || “မတ်ဍေံဟွံဗကေတ် မတ်ဍေံလေဝ်လၜဲဒၟံၚ် သမၞိၚ်ဇကုဍေံလေဝ်နွံဒၟံၚ် ပူဂဵုဝွံဒှ်မၞိဟ်ရောၚ်။” (ဇ—၅၁၃။အစွောံ။) || “ဗောဓိသတ်ၚဳမွဲ (ဣန်) လၜဲမတ်ဟွံမွဲ ဒဒှ်မၞိဟ်ဟွံသေၚ် ဗောဓိသတ်တီကေတ်တုဲ—။” (ဇ—၂၄၃။ အစွောံ။) = “ဘုရားလောင်းသည် သိကြားမင်းကို ကြည့်သည်ရှိသော် မျက်စိမှိတ် ခြင်းမရှိသဖြင့် လူမဟုတ်ကြောင်းကို ဘုရားလောင်းသိ၏။” || “(ကျာ်တြဲ) ဗဵုဒၟံၚ်ဗောဓိ (၇) တ္ၚဲ ဟွံဂွံလၜဲမတ်ရ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “မြတ်စွာဘုရားသည် ခုနစ်ရက်တိုၚ် မျက်တောင်မခတ်ဘဲ ဗောဓိပၚ်ကို ကြည့်တော်မူ၏။”')
,(12785,3,4,'ကြည့်သည်။',NULL)
,(12786,3,4,'(တစ်စုံတစ်ခုထက်တွင်) တွဲလျားတၚ်သည်။','“ယာတ်ဂှ် ညးလၜက်လဝ်လ္တူပၞးရ။”= “အဝတ်ကို ပုခုံးပေါ်တွင် သူတင်ထားသည်။” || “(သၟတ်) သမ္ဘာဝဂှ်တုန် ဂၠိက်ဇကုဂှ် လၜက်လဝ်ပ္ဍဲပၞးဇကုတုဲ ဝေၚ်တဴခနှိက်တိရောၚ်။” (ဇ—၅၁၅။ အစွောံ။) = “သူငယ်သမ္ဘာဝသည် မိမိလုံချည်ကို မိမိပုခုံး­တၚ်၍ မြေမှုန့်ကစား၏။” || “ဇာဒိသိုၚ်ဂှ် ကိတ်ဂွံချေံမွဲတုဲ လၜက်စုတ်ပ္ဍဲစးတုဲကေတ်ဖျဴနၚ်—။” (ဇ—၃၉၇။ အစွောံ။) = “ခြင်္သေ့သည် မြင်းတစ်ကောာၚ်ကို ကိုက်သတ်ပြီးလျှင် ကျောထက်­တၚ်၍ ယူပြန်လာ၏။” || “(ဣသိတံသုၚ်သူရာဗ္ၜူအာ) ပခိုၚ်ဇကုဟွံခိုၚ် လတူအမာဲစၞ လောတ်လၜက်ဒၟံၚ်တုဲ လှိၚ်အာ။” (ဇ—၈၁။ အစွောံ။) = “ရသေ့တို့သည် အရက်သောက်၍ မူးယစ်ကုန်သည်ဖြစ်၍ ကိုယ်ကိုခိုၚ်အောင်မထိန်းနိုင်ဘဲ အစာပေါ်လဲ၍ အစာပေါ်ဖိမိလျက် အိပ်ပျော်ကုန်၏။”')
,(12787,3,1,'(ထိုင်ခုံစသည်တွင်) လက်တၚ်စရာ။','“ခုၚ်ဂ္ဇအ်ဂှ် မၞုံကဵုဇိုၚ်ပန်၊ ဒလာဲမွဲ၊ လၜက်တဲၜါရ။” = “ထိုထိုင်ခုံသည် အခြေလေးခု၊ အမှီတစ်ခုနှင့် လက်တၚ်စရာနှစ်ခုရှိသည်။”')
,(12788,3,4,'မှီခိုသည်။ ခိုလှုံသည်။',NULL)
,(12789,3,1,'လက်ကောက်။',NULL)
,(12790,3,4,'ဆင်ယင်သည်။ လှပအောင်လုပ်သည်။ တန်ဆာဆင်သည်။','“ၜါလ္ပာ်တရဴမသစဴဂှ် ကဵုသြံက်လဝ်က္ဍိုၚ်ဇၞောဝ် စဵုရာဇာဓမာတ် လၜတ်လဝ်တရဴသဗာန်ရ။” (အကြီုရာဇာဓိရာဇ်) = “ပြန်ရာလမ်းနှစ်ဖက်­ ထီးတံခွန်တို့ကိုစိုက်၍ ရာဇမတ်ကာရံ၍ လမ်းခရီးကို တန်ဆာဆင်ထား၏။”')
,(12791,3,4,'အေးအောင်လုပ်သည်။ အေးငြိမ်းစေသည်။ အေးချမ်းစေသည်။','“သွဍုန်လဝ်ဂှ် ဖျေံနူဖဴတုဲ လၜိုဟ်လဝ်ညိ။” = “ချက်ထားသောဟင်းကို မီးဖိုမှချပြီး အအေးခံထားပါ။” || “စဝ်လၜိုဟ်ကၠေံဂမ္တဴဂမ္တာန် မတွံဂးကိလေသ နကဵုဍာ်အရဟတ္တမဂ္ဂညာန်။” (ပြကိုဟ်ဓမ္မရာသဳ။ မာံရွှေငိုး။) = “ကိလေသာတည်းဟူသောအပူမီးကို အရဟတ္တမဂ္ဂဉာဏ်ဟူသောရေဖြင့် သွန်းလောင်းငြိမ်းအေးစေသည်။” || “ကာလဥတုဂမ္တဴဂှ် ဗြဴရတ်လၜိုဟ်ကဵုညးဒှ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ပူပြင်းသောရာသီ­ မိန်းမရတနာသည် သူတစ်ပါးကို အေးချမ်းစေတတ်၏။” || ‘ဗၜိုဟ်’ ဟုလည်းရေးသည်။')
,(12792,3,4,'စိတ်အေးချမ်းသာအောင်လုပ်သည်။ စိတ်အေးချမ်းစေသည်။','“ကောန်မရာတ်ဝွံ လၜိုဟ်ကဵုစိုတ်သတ်ဂမၠိုၚ်ရောၚ်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အရှင်မင်းကြီး၏သားတော်သည် သတ္တဝါအပေါင်းတို့အား စိတ်အေးချမ်းသာစေလတ္တံ့။” || ‘ၜိုဟ်စိုတ်/တ္ၜိုဟ်စိုတ်’ (ကြိ) လည်းရှု။')
,(12793,3,4,'(ရေချိုး၊ ရေသောက်၊ နားနေခြင်းစသည်အားဖြင့်) ကိုယ်ကိုအေးချမ်းစေသည်။','“ပ္ဍဲလဂေါဝ်ဂှ် (သၟိၚ်) သုၚ်ဍာ်ဟုံဍာ် လၜိုဟ်ဇကုတုဲ ပ္ဍဲသၞိၚ်ဆုမွဲဂှ် သတိက်ဇူမံၚ်ရ။” (ဇ—၅ဝ၃။ အစွောံ။) = “ထိုတောင်မြောင်­ မင်းသည် ရေသောက်ရေချိုး၍ ကိုယ်ကိုအေးချမ်းစေ၍ သစ်တစ်ပင်အရိပ်­ အိပ်၍နားနေ၏။” || “ဥတုဂမ္တဴ သၟိက်လၜိုဟ်ဇကုဂှ်ဒှ်တုဲ ရသိမွဲဂှ် တိုန်အာလၜိုဟ်ဇကုပ္ဍဲသွဝ်တာဝတိၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ပူပြင်းသောရာသီ­ ကိုယ်ကိုအေးချမ်းစေလိုသည်ဖြစ်၍ တစ်ပါးသောရသေ့သည် တာဝတိၚ်သာနတ်ပြည်သို့သွား၍ နားနေ၏။”')
,(12794,3,1,'အသွား။ သွားခြင်း။ သွားပုံ။ သွားဟန်။','‘ညံၚ်ရဴလအာကပ္ဍဲဍာ် ဟွံညာတ်ဒၞာဲဇိုၚ်ကီု။’= ‘ရေထဲ­ ငါး၏သွားခြင်းကဲ့သို့ ခြေရာကိုမမြင်ရ။’ || “လအာအဲ လ္ပကဵုလီုညိ။” (ဇ—၅၂၅။အစွောံ။) = “ငါ၏သွားခြင်းကို မပျက်ပါစေနှင့်။” || ‘အာ’ (ကြိ) လည်းရှု။')
,(12795,3,4,'(ဆီ၊ ဆီမန်းစသည်) လိမ်းကျံသည်။ လိမ်းသပ်သည်။ လူးသည်။','“ကၠေၚ်မဖျိန်လဝ်လ္ၚီဝါဂှ် (သၟိၚ်) ကဵုလအက်စုတ်သၞေၚ် (သၟိၚ်ၜိုပ်) ရ။” (ဇ—၄၇၆။ အစွောံ။) = “ဗာရာဏသီမင်းသည် — အကြိမ်တထောင်ချက်အပ်ကုန်သောဆီတို့ဖြင့် ဘုရားလောင်းဟင်္သာမင်း၏အတောင်ကြားတို့ကို လိမ်းကျံ (စေ) ပြီးလျှင်—။” (ညောင်ကန်) || “နကၠေၚ်မဖျိန်လဝ်ကၠံဝါဂှ် လအက်သၞေၚ် (တ္ၚေက်) တုဲ နတဲၜါသၟိၚ်ရပ်ပ္တိတ်မ္ၚးတုဲ ဗလးပ္တိုန်လတူအကာသရ။” (ဇ—၂၈၁။ အစွောံ။) = “အကြိမ်တရာချက်သောဆီဖြင့် ကျေးသား၏အတောင်ကြားတို့ကိုလိမ်း၍ လက်နှစ်ဘက်တို့ဖြင့်ကိုင်၍— ကောင်းကင်သို့လွှတ်၏။” (ညောင်ကန်) || “မၚ်ဗၠာဲတၠသ္ၚိဂှ် — လအက်ကၠေၚ်ပ္ဍဲစးချေံဂှ်တုဲ ကဵုချေံဂှ်စကၟတ်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “အိမ်ရှင်သည် — (မြင်း၏) ကျောက်ကို ဆီလူး၍ မြက်ကိုပေး၏။” (ညောင်ကန်) || “ဂၞကျာ်ကြဴဇိုၚ်သဟာဲဂှ်တုဲ ဂၞကျာ်အာကေတ်နၚ်ကၠေၚ်မြမောဝ်တုဲကၠုၚ်လအက်ဂတာဇိုၚ်သဟာဲဂှ်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “မိဖုယားသည်လည်း (အဆွေခင်ပွန်း၏) ခြေတို့ကိုဆေး၍ နံ့သာဆီဖြင့်လိမ်း၏။” (ညောင်ကန်) || “ဍာ်မကြဴဇိုၚ်ကီု ကၠေၚ်မလအက်ဇိုၚ်ကီု။” (ဇ—၅ဝ၉။ အစွောံ။) = “ခြေဆေးရေကို၄င်း ခြေလိမ်းဆီကို၄င်း။”')
,(12796,3,4,'(မေတ္တာ၊ သဒ္ဓါစသည်) ပွားသည်။ ခြုံလွှမ်းသည်။','“မေတ္တာစိုတ်လအက်ဒၟံၚ်ပ္ဍဲသတ်တံဂမၠိုၚ်။” (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “သတ္တဝါအပေါင်း­ မေတ္တာစိတ်ကိုပွားသည်။” || “သဒ္ဓါလအက်၊ ရတ်အနက္ဃ။ မာလေကမက်၊ ဆက်ဗိုန်ဒါန။ အဲပပူဇဴ၊ ရဴဂဴဓမ္မ။” (လိက်ဝိဓူရ) = “ကြည်ညိုသဒ္ဓါပွား၍ အနဂ္ဃရတနာလည်ဆွဲကို မြဲစွာအလှူဒါနပြု၍ တရားတော်ကို ငါပူဇော်ပါ၏။”')
,(12797,3,1,'သည်းခံခြင်း။ ခန္တီတရား။','“ဝေတ်ဇကုတုဲ က္တဵုဗဒှ်ခန္တဳလအေၚ် က္တဵုဗဒှ်မေတ္တာကရုဏာစိုတ်ညိ။” (ဇ—၁၄၉။ အစွောံ။) = “မိမိကိုယ်ကိုဆုံးမ၍ ခန္တီသည်းခံခြင်းကို၄င်း မေတ္တာကရုဏာစိတ်ကို၄င်း မွေးလော့။” || “မူဂှ် မဒှ်ဝါတ်ခမဳရော” သၟိၚ်ဂး။ “ခန္တဳဝါဒဳလအေၚ်ရမရာတ်”ရသိဂး။ (ဇ—၃၁၃။ အစွောံ။) = “ရဟန်း၊ သင်၏ဝါဒကား အဘယ်နည်း” ဟုမင်းသည်မေး၏။“မင်းမြတ်၊ ခန္တီဝါဒသည်းခံခြင်းပၚ်တည်း” ဟုရသေ့ဆို၏။ || “ဟာဲရသိစၞာဲ၊ လအေၚ်တၠဂှ် တၠယိုက်ဒိုက်လဝ်တုဲ ဂ္ဇံဒၟံၚ်ဒၞာဲဏအ်ရ” သၟိၚ်ဂး။ (ဇ—၃၁၃။ အစွောံ။) = “ရသေ့စဉ်းလဲ၊ သင့်ခန္တီကို သင်သည်လျှင်ရွက်ဆောင်၍ နေလော့” ဟုမင်းဆို၏။ (ညောင်ကန်) || ‘အေၚ်’ (ကြိ) လည်းရှု။')
,(12798,3,1,'၁။ အလှူခံ။ တောင်းရမ်းသူ။','တမၠၚ်လအာတ် = တောင်းရမ်းစားသူ။ သူတောင်းစား။ || “တၠပညာတမၠာဂှ် ယာံလအာတ်မွဲကၠုၚ်စိုပ်တုဲဂှ် ဒဵုလမျီုဇကုကီုလေဝ် သၠးကဵုဒါန်ကီု ဒဵုဖျုန်ဇကုလေဝ် သၠးကဵုဒါန်ကီုတုဲရ။” (ဇ—၃၁၆။ အစွောံ။) = “ရှေးပညာရှိတို့သည် ရောက်လာကုန်သော အလှူခံတို့အား အသက်ကိုစွန့်၍ မိမိ၏အသားကိုလည်း လှူဘူးကုန်၏။” (ညောင်ကန်) || “ဗောဓိသတ်ပိုဲ ဂ္ၚေၚ်ဘဴသံၚ်သာ အာဗိုတ်ပဋိသန္ဓိ ပ္ဍဲဂဝ်ဂၞဴဗြဴလအာတ်ရ။” (သၠပတ်ရာဇာသာန်) = “ဘုရားလောင်းသည် သံသရာတွင်ကျင်လည်စဉ် သူတောင်းစားမ၏ဝမ်း­ ပဋိသန္ဓေယူ၏။”')
,(12798,3,1,'၂။ တောင်းရမ်းခြင်း။ အတောင်းအရမ်း။','“ယွံခမဳတံ၊ လအာတ်ဂၠိုၚ်ဝါ မဂၠေံဂၠိုၚ်ဝါတုဲ မကၠောန်ကုဋဳမ္ဂးဂှ် ဒှ်ကွေံဟာ” ကျာ်တြဲသၟာန်။ (ဇ—၂၅၃။ အစွောံ။) = “ရဟန်းတို့၊ အတောင်းအရမ်းများ၍ အချေးအငှားများ၍ ကုဋဳကိုဆောက်လုပ်၏ဟူသည် မှန်သလော” ဟုမြတ်စွာဘုရားမေးတော်မူ၏။ || ‘အာတ်’ (ကြိ) လည်းရှု။')
,(12799,3,1,'အစွန်းအဖျား။ အဆုံး။','“ကောန်သၟိၚ်ထေဲပၞတ်ကဵုအ္စာတုဲ သီုမတ်မဗကေတ်တဴဂှ်ၚဳအ္စာနူဂတာဇိုၚ် ဒဵုလအိတ်မုဟ်သော်ရ။” (ဇ—၂၅၂။ အစွောံ။) = “မင်းသားသည် အမျက်ထွက်၍ မျက်စိတို့ကို နီစွာပြု၍ ခြေဘမိုးမှ ဆံဖျားတိုင်အောင် ဆရာကိုကြည့်၏။” (ညောင်ကန်) || “(ပံက်စၞာဲဂှ်) အာစိုပ်လစ ပ္ဍဲလအိတ်ဍာ်သ္ကဲသြၚ် ချပ်စံၚ်တူဒေၚ်ဒၟံၚ်တုဲ တန်ဒၟံၚ်ရ။” (ဇ—၃၈။အစွောံ။) = “ဗျိုင်းစဉ်းလဲသည် ရေအိုင်သို့သွားရောက်၍ ရေ၏အဆုံးကမ်းစပ်­ ပူပန်ေၚးမှိုင်လျက် ကြံ၍နေ၏။” || “ပ္ဍဲလအိတ်သမၞိၚ်ဆုဂှ် ဒတဴဒၟံၚ်ရ။” (ဇ—၃၉၈။ အစွောံ။) = “အရိပ်အစွန်း­ရပ်လျက်—။” (ညောင်ကန်) || “ပ္ဍဲလအိတ်ကျာ်တြဲမကဵုပိုန်တုဲဂှ် ပ္ဍဲဋ္ဌာန်မဗၠးဒုဟ်ဂှ် သၟိၚ်ဂ္ဇံဒၟံၚ်ရ။” (ဇ—၅ဝ၄။ အစွောံ။) = “(မြတ်စွာဘုရား၏) ဆွမ်းဘုဉ်းခြင်းကိစ္စအဆုံး­ (မင်းသည်) တင့်အပ်လျောက်ပတ်စွာနေ၏။” (ညောင်ကန်) || “နနဲသာ်ဝွံ ဒဵုထပှ်တ္ၚဲဂှ် နဒါန်မဇၞော်ဂှ် တရိုပ်ကဵုဒါန်တုဲ ပ္ဍဲလအိတ်ထပှ်တ္ၚဲဂှ် သဗ္ဗပရိက္ခရာအိုဿီုဂှ် ကဵုဒါန်ရ။” (ဇ—၄၉၅။ အစွောံ။) = “ဤသို့ခုနစ်ရက်ပတ်လုံး အလှူကြီးကိုလှူ၍ ခုနစ်ရက်၏အဆုံး­ အလုံးစုံသောပရိက္ခရာတို့ကို လှူကုန်၏။” || “—၊ ဒဒှ်မၞိဟ်ဂှ်သ္ဂောံဒှ်တုဲ ဓဝ်သစ္စပန်ဂှ် ကြက်အဲသ္ဂောံဂြၚ်တီတုဲ ဒဒှ်လအိတ်ဒဒိုက်ဂှ် အဲသ္ပညိ” သၟိၚ်နာ်ချပ်။ (ဇ—၅ဝ၆။ အစွောံ။) = “လူ့ပြည်သို့ရောက်လျှင် သစ္စာလေးပါးတရားတို့ကို သိသဖြင့် ဝဋ်ဆင်းရဲ၏အဆုံးကို ငါပြုအံ့” ဟုနဂါးမင်းကြံ၏။ (ညောင်ကန်)')
,(12800,3,5,'အလွန်အမင်း။ အဆုံးစွန်။','“မိတၠဂုဏ်အဲဝွံ ၜိုန်ဒိုက်လအိတ်ကီု ဋ္ဌာန်ကောန်စွံအဲတုဲ သီုလမောင်ဒဒိုက်ဟေၚ် မမြိမြန်ဇၞော်ပၟဝ်လဝ်အဲ—” ဗောဓိသတ်ဂၠဴချပ်။ (ဇ—၂၉။ အစွောံ။) = “ငါ၏ကျေးဇူးရှင်မိခင်သည် အလွန်အမင်းဆင်းရဲသော်လည်း ငါ့ကို သားအရာ­ထား၍ ငြိုငြင်သဖြင့် ငါ့ကိုကြီးပြင်းအောင် စောင့်ရှောက်မွေးမြူထားပေ၏” ဟုဘုရားလောင်းနွားကြံ၏။ || “ဒှ်လၞီလၞာ်လအိတ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “အလွန်အမင်း ပူပန်သောကဖြစ်၏။” || “ရးနဳဂီုဂမၠိုၚ် ကတဴကတာန်လအိတ်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “တိုင်းနိုင်ငံသည် အလွန်အမင်းဆူပူလတ္တံ့။” || “အဲသ္ဍိုက်ပ္ဍဲကောအဲလအိတ်ရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ငါသည်မောင်တော်ကို အချစ်ဆုံးပါ။” || “ဍုၚ်မတ္တမ ဒယှ်တှ်တဴလအိတ်ရ။” (အကြီုရာဇာဓိရာဇ်) =“မုတ္တမမြို့သည် အလွန်အမင်းကျော်ကြား၏။”')
,(12801,3,5,'ယုတ်စွအဆုံး။ အယုတ်သဖြင့်။','“ပ္ဍဲပွမပ္တုံလမျီုသတ်အိုတ်သီုဂှ် ဗွဲလအိတ် ကမှာဲဒဂိတ်စဲတံဂှ်လေဝ် ပိုဲဝေၚ်ပဲါ ပိုဲဟွံဂွံဂစိုတ်ရ။” (ဇ—၄၄၇။ အစွောံ။) = “အလုံးစုံသော သူ့အသက်ကိုသတ်ခြင်း­ ယုတ်စွအဆုံး ကြမ်းပိုးဥသန်းဥတို့ကိုမျှလည်း ငါတို့ရှောင်ကြဉ်ကုန်၏၊ ငါတို့မသတ်ကုန်။” || “နဒြပ်ညး ညးဟွံဂွံကဵုနပါၚ်နစိုတ်ဂှ် ဗွဲလအိတ် ဇြေဟ်ကၟဟ်ညိကီုလေဝ် ပိုဲဝေၚ်ပဲါ ပိုဲဟွံကေတ်ရ။” (ဇ—၄၄၇။ အစွောံ။) = “ဥစ္စာရှင်က နှုတ်အားဖြင့်၄င်း စိတ်အားဖြင့်၄င်း မပေးသောဥစ္စာကို ယုတ်စွအဆုံး တံမြက်စည်းအမျှင်တစ်ခုကိုမျှလည်း ငါတို့ရှောင်ကြဉ်ကုန်၏၊ ငါတို့မယူကုန်။” || “ပ္ဍဲသ္ၚိဗမၞးဓမ္မပါလဂှ် ဗွဲလအိတ် ဍိက်ညးမကၠောန်ကေၚ်ကာတံကီုလေဝ် ဂွံပ္တုဲတဴဒါနသဳလရ။” (ဇ—၄၄၇။ အစွောံ။) = “ထိုဓမ္မပါလအမျိုး­ အယုတ်သဖြင့် ကျွန်အမှုလုပ်တို့သည်လည်း (ဒါနသီလကို ပြုကြရကုန်၏။)” (ညောင်ကန်)')
,(12802,3,5,'အလွန်အမင်း။ အလွန်တရာ။ အဆုံးစွန်အားဖြင့်။ အထွတ်အထိပ်အားဖြင့်။','“(လၟာဲဂှ်ပျဲတုဲ) သီုဆီမလမုဲလမေက်ဒၟံၚ်ဂှ် ဗောဓိသတ် (သၟိၚ်နာ်) မဒးဒုၚ်တဴဒဒိုက်မဇၞော်လောန်စိုပ်ကဵုလအိတ်ရ။” (ဇ—၅ဝ၆။ အစွောံ။) = “အလမ္ပာယ်ကညှဉ်းပမ်းသဖြင့် ဘုရားလောင်းနဂါးမင်းသည် သွေးတို့ဖြင့်လိမ်းကျံလျက် အထွတ်အထိပ်ရောက်သော ကြီးစွာသောဒုက္ခဝေဒနာကို ခံစားရ၏။” || “ကၠောဝ်ဗျဵုစိုပ်ကဵုလအိတ်။” (အကြီုရာဇာဓိရာဇ်) = “အလွန်အမင်းငတ်မွတ်၏။” || “ဍုၚ်ဂှ် အိန်သ္ဂီုရာၚ်ဆာဲ စိုပ်ကဵုလအိတ်ရ။” (ပေါရဏာံပေါရဒံါ။ အစွောံ။) = “ထိုမြို့သည်အလွန်တရာ သာယာဝပြော၏။”')
,(12803,3,1,'သေလုနီးသောကာလ။ သေအံ့သောကာလ။ သေခြင်းလျှင် အဆုံးရှိသောကာလ။','“တြုံပိုတ်ဂှ် ပ္ဍဲလအိတ်ဂစိုတ်ဂှ်ရ အဲဟံၚ်လဝ်တုဲ အဲမြိမြန်လဝ်။” (ဇ—၁၉၃။ အစွောံ။) =“ထိုၚပြတ်အား သေအံ့လုနီးကာလ­ ငါဆယ်တၚ်၍ ငါမွေးမြူထား၏။”')
,(12804,3,1,'အသက်၏အဆုံး။ ကွယ်လွန်ချိန်။','“သၟိၚ်သီုပုရိသာတ်တံညးဂမၠိုၚ်ဂှ် ဒါန်မဇၞော်ဂှ်ဂွံပ္တုဲတုဲ ပ္ဍဲလအိတ်အယုက်ဂှ် ဂွံတိုန်စိုပ်ဍုၚ်သွဝ်ဖအိုတ်ရ။” (ဇ—၄၉၅။အစွောံ။) = “မင်းနှင့်တကွ ပရိသတ်အပေါင်းတို့သည် အလှူကြီးကိုလှူ၍ အသက်၏အဆုံး­နတ်ပြည်သို့ လားရောက်ရကုန်၏။”')
,(12805,3,1,'တောင်ဝၚ်ရိုးစွန်း။',NULL)
,(12806,3,1,'မြောက်ဝၚ်ရိုးစွန်း။',NULL)
,(12807,3,1,'ဝမ်းနည်းခြင်း။ စိတ်ပျက်ခြင်း။','“လ္ပကဵုညးဇမၞော်ဒှ်လအောန်စိုတ်။” (အကြီုရာဇာဓိရာဇ်) = “လူကြီးကို ဝမ်းနည်းစိတ်ပျက်ခြင်း မဖြစ်ပါစေနှင့်။” || ‘အောန်စိုတ်’ (ကြိ) လည်းရှု။')
,(12808,3,1,'ဝရောင်းချဉ်ပၚ်။',NULL)
,(12809,3,10,'(န) လာဘ်လာဘ။','“—၊ ကျာ်တြဲတုန်လေဝ် လာဘဂၠိုၚ်တိုန်က္ဍၚ်အာပၠန်တုန်။” (ဇ—၂၈၅။ အစွောံ။) = “မြတ်စွာဘုရားအား လာဘ်လာဘသည် ပို၍များသွားပြန်လေ၏။”')
,(12810,3,1,'‘လဳမဴ’ ရှု။',NULL)
,(12811,3,4,'မျက်နှာသစ်သည်။','‘လဳမုက်’ ရှု။ || “စိုပ်ဥဒျာန်သၟတ်၊ ဗြဴရတ်မပြဲ။ ဟုံလဳဝေၚ်ဂြိုၚ်၊ကျိုၚ်ကျဝ်ဖဲလဲ။” (လိက်ထေအနန်) = “ဥယျာဉ်သို့ရောက်သော ရတနာမယ်သည် ရောင့်ရဲသည်အထိ ရေချိုးမျက်နှာသစ် ကစားရွှင်ပျော် ဝတ်စားဆင်ယင်၍။” || “ဇမောဝ်ရဴကြုၚ်၊ ဂွံသုၚ်ဟုံလဳ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ချောင်းကဲ့သို့သောရေစီးကြောင်းဖြင့် သောက်ရ၊ချိုးရ၊ မျက်နှာသစ်ရ၏။”')
,(12812,3,1,'‘လေဝ်ၚာဲ’ ရှု။',NULL)
,(12813,3,12,'(န) လိမ္မော်သီး။','“(ဒြာဲထဝ်ဂှ်) မၞုံကဵုဇိုၚ်မဗကေတ် ညံၚ်ရဴသာ်လဳမဴကီု။” (ဇ—၅ဝ၁။ အစွောံ။) = “ထိုရွှေသမင်သည် လိမ္မော်ရောၚ်ကဲ့သို့ နီသောခြေရှိ၏။” || “လိမှဴပဏှ်၊ ရှ်သာလောန်တဲ။” (လိက်ဇိဝှစက္က) = “လိမ္မော်ပိနနဲ အရသာထူးကဲ၏။” || “သဳလောလဳမှဴ၊ သီုသတ်ဗြဴတာ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။)')
,(12814,3,4,'မျက်နှာသစ်သည်။','“ယွံမၞးတံ၊ မၞးတံပ္တုဲကေၚ်ကာဒၞာဲဝွံညိ။ အဲသ္အာလဳမုက်ညိ။” (ဇ—၃၈၉။ အစွောံ။) = “အချင်းတို့၊ သင်တို့သည် ဤနေရာ­ အလုပ်လုပ်ကြကုန်လော့။ ငါသည်မျက်နှာသစ်ရန်သွားအံ့။” || “နူဂယးပြဟ်ဟေၚ် လဳမုက်တ္ၜဴပါၚ်တုဲ စဴအာသ္ၚိဇကုရ။” (ဇ—၄၃၉။အစွောံ။) = “နံနက်စောစောကလျှင် မျက်နှာသစ် ပလုတ်ကျင်း၍ အိမ်သို့ပြန်သွား၏။” || “ဍာ်မလဳမုက်ကီု ဍာ်မတ္ၜဴပါၚ်ဂှ်ကီု ပရာပ်နၚ်ကဵုတၠသ္ၚိတုဲ—။” (ဇ—၅၁၉။ အစွောံ။) = “မျက်နှာသစ်ရန်ရေကို၄င်း ပလုတ်ကျင်းရန်ရေကို၄င်း လၚ်အား ယူဆောင်ပေး၏။” || “(ယွံတဳလ) ၊ က္ညလဳမုက် ဍာ်အဲဍိက်စုတ်လဝ်ရအဴ။” (ဇ—၃၂၁။ အစွောံ။) = “အရှင်ဘုရား၊ ရေကို တည်ထားအပ်ပြီ။ မျက်နှာသစ်တော်မူပါလော။” (ညောင်ကန်) || “ဍာ်ထီုမြမောဝ်၊ တေဝ်စွံလဝ်ကၠာ။ လဳမုက်က္ၜဴပါၚ်၊ လာၚ်မုက္ခဝါ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မျက်နှာသစ်၊ ပလုတ်ကျင်းရန်အတွက် အမွှေးနံ့သာထုံထားသောရေကို တည်ခင်းပေးထား၏။” || ‘လာၚ်မုက်’ လည်းရှု။')
,(12815,3,1,'မနက်ဖြန်။','“စိုပ်တ္ၚဲသဝ်ပၠန်၊ တ္ၚဲသဝ်လောန်အာ။ လဳယးပြဟ်မာ၊ က္တဵုကၠောန်ကာရ။” (လိက်လၞုဟ်ပန်) = “ညနေခင်းသို့ရောက်သောအခါ မိုးချုပ်လောန်သွားပြီ၊ မနက်ဖြန်စောစောမှ ထ၍အလုပ်လုပ်တော့မည်။”')
,(12816,3,3,'(ကျွဲ၊ နွား) ဦးချိုအောက်စိုက်သော။','ပြေၚ်လု = ချိုအောက်စိုက်သောကျွဲ။ ကျွဲတယ်လူး။')
,(12817,3,6,'ကာလတစ်လျှောက်။ တိုင်အောင်။ ပတ်လုံး။ တာ။','“ရသိဂှ် လုကဴမသုန်စှ်ောသၞာံပရဲဒၟံၚ်တဴဒၞာဲဂှ်ရ။” (ဇ—၂၇၇။ အစွောံ။) = “ရသေ့သည် ထိုအရပ်­ အနှစ်ငါးဆယ်ကျော်ပတ်လုံးနေ၏။” || “ပ္ဍဲဒလောအ်ဗတောန် (ဗောဓိသတ်) သၟိၚ်ဒြာဲထဝ်ဂှ် လုကဴလ္ၚီသၞာံဟေၚ် ဒ္ဂေတ်တဴရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “ဘုရားလောင်းရွှေသမင်၏ အဆုံးအမသြဝါဒသည် အနှစ်တထောၚ်ပတ်လုံးတည်၏။” (ညောင်ကန်) || “လုကဴစှ်ၜါသၞာံဂတဂှ် မၞးတံစဴပကၚ်ရၚ်ကၟိန်ဍုၚ်ရ။” (ဇ—၄၆၁။အစွောံ။) = “ရှေ့လာမည့် (၁၂) နှစ်တာကာလ­ သင်တို့ပြန်လာ၍ တိုင်းပြည်ကို မင်းလုပ်အုပ်ချုပ်ကြကုန်လော့။” || “ဣသိဂှ် လုကဴမွဲဗြဲပန်ဂိတု ပဒတဴပ္ဍဲဥဒျာန်တုဲ—။” (ဇ—၅ဝ၅။ အစွောံ။) =“ရသေ့သည် တစ်မိုးလေးလပတ်လုံး ဥယျာဉ်­နေ၍—။” || “ဝဳပက်ဂှ် လုကဴဂ္ၚေၚ်ဘဴသံသာ ကာလမလအ်ဝွံဂှ် အခေါၚ်ဂှ် ဍေံဟွံကလိဂွံဏီတုဲ ဍေံဟွံဂွံကဵုဖဵုဏီရ။” (ဇ—၅၂၂။ အစွောံ။) = “ထိုကံဝိပါက်သည် ကာလရှည်မြင့်စွာ သံသရာတွင် ကျင်လည်သောကာလတစ်လျှောက် အခွင့်ကိုမရသေး၍ အကျိုးမပေးရသေး။” || “ယွံသၟိၚ်၊ ဓဝ်ပၞတ်မက္တဵုဒှ်ဂှ် လုကဴအဲမဂျိုၚ်တဴလမျီုဝွံ အဲဟွံဂွံဗလးပ္တိတ်ဍေံရ” ဣသိဂး။ (ဇ—၄၄၃။ အစွောံ။) = “မင်းမြတ်၊ ငါသည် ဖြစ်ပေါ်သောအမျက်ဒေါသကို အသက်ရှင်သမျှကာလပတ်လုံး အပြင်သို့မထွက်စေလတ္တံ့။”')
,(12818,3,4,'လျှပ်ပေါ်သည်။ လော်လည်သည်။ စောင့်စည်းမှုမရှိ။ လောဘရမ္မက်ကြီးသည်။ တပ်မက်သည်။','‘ခမဳမလုလန်ပ္ဍဲဗစဲပန်။’ = ‘ပစ္စည်းလေးပါး­ အလိုကြီးသောရဟန်း။’ || “ညးဗၞိက်လီုလုလန်မွဲသ္အာၚ် မဟိမုသေရိဝကီု အာပဗၞိက်။” (ဇ—၃။ အစွောံ။) = “လောဘရမ္မက်ကြီးသော သေရိဝအမည်ရှိသော အခြားတစ်ပါးသော ရွဲကုန်သည်သည်လည်း ကုန်ရောင်းအံ့သောငှာသွား၏။” || “ပဟိုတ်ကဵုခမဳမွဲ မလုလန်တဴဂှ်တုဲ ဒူတဇာတ် ကျာ်တြဲတွံ။” (ဇ—၂၆ဝ။အစွောံ။) = “ဤဒူတဇာတ်ကို — လော်လည်သောရဟန်းတပါးကို အကြောင်းပြု၍ ဟောတော်မူ၏။” (ညောင်ကန်) || “ပြောဟိတ်ဂှ်တုန်လေဝ် လောဘလုလောန်တဴ ပ္ဍဲယဿပတ်။” (ဇ—၃၅၃။ အစွောံ။) = “ထိုပုရောဟိတ်သည် စည်းစိမ်­တပ်မက်သဖြင့်။” (ညောင်ကန်) || “ခ္ဍာ်မလုလန်မွဲဂှ် ဇွစိၚ်ဇွချေံဇွပြေၚ်ဂၠဴတံဂှ်စတုဲ ဟွံပေၚ်တရိုပ်စိုတ်တုဲ။” (ဇ—၃၉၄။ အစွောံ။) =“တစ်ခုသောလျှပ်ပေါ်သောကျီးသည် ဆင်ကောင်အစရှိသည်တို့ဖြင့် မရောင့်ရဲသည်ဖြစ်၍။” (ညောင်ကန်) || “ဗြဴတံညးဂမၠိုၚ်မ္ဂးဂှ် ဍေံလုလန်ပ္ဍဲတြုံတံသန်ရောၚ်။” (ဇ—၅၁၉။ အစွောံ။) =“မိန်းမတို့မည်သည် ယောကျာ်းတို့­ အလွန်လော်လည်တတ်၏။ (စောင့်စည်းမှုမရှိ။)”')
,(12819,3,1,'‘လေဝ်ၚာဲ’ ရှု။',NULL)
,(12820,3,16,'(န) လေလံ။','ဗိုတ်လေလာန် = လေလံတၚ်သည်။ လေလံပစ်သည်။')
,(12821,3,10,'(န) ဥပါယ်။ ပရိယာယ်။','“ပသာ်လေသမွဲမသ္ပတုဲ (သၟိၚ်မြာ်ထဝ်) မသ္ဂောံဗၠးဓနက်လၟရော။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မည်သို့သောဥပါယ်ကိုပြု၍ ရွှေဥဒေါင်းမင်းသည် မုဆိုး၏ကျော့ကွင်းမှ လွတ်ပါမည်နည်း။” || “နကဵုလေသဟေၚ် သ္ပဇြဟာန်သၟိန်ကဵုရၚ်သ္ကံ။” (အကြီုရာဇာဓိရာဇ်) = “ဥပါယ်ပရိယာယ်ဖြင့်သာလျှင် တစ်ဖက်နှင့်တစ်ဖက် ချစ်ခြင်းမိတ်ဖွဲ့ကြသည်။” || “အဲရဟွံအာယဝ်သဒှ် အဲတီကေတ်လေသဍေံ ဍေံသ္ဂးရ။” (အကြီုရာဇာဓိရာဇ်) = “အကယ်၍ငါမသွားခဲ့သော် သူ့ပရိယာယ်ကို ငါသိလိုက်ပြီဟု သူဆိုလိမ့်မည်။” || “လေသဂၠိုၚ်ဒၞာဲ၊ ဥပ္ပဲါဂှ်စိ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ပရိယာယ်ဥပါယ်မာယာ များလှစွာ၏။”')
,(12822,3,1,'၁။ (မြတ်စွာဘုရားအချင်းချင်း ခေါ်ဆိုသော) ညီတော်နောင်တော်။ ဘုရားညီနောင်။','“ဒှ်ကၠာအဲသၟတ်၊ လဲကဿပ။” (ကျာ်တြဲဂေါတမဂး။) (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ငါ၏အလျင်ပွင့်တော်မူသော နောင်တော်ကဿပဘုရား။” || “ထာန်ဒမံၚ်ကျာ် (၃) လဲအဲတမၠာတေံ” (ကျာ်တြဲဂေါတမဂး။) (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “ငါ၏ဘုရားနောင်တော်များဖြစ်သော လွန်လေပြီးသောမြတ်စွာဘုရား (၃) ဆူတို့၏နေရာအရပ်။” || “တုဲသၟိၚ်အရှန်၊ ဗကန်မွဲဂၠံၚ်။ ဓါတ်လဲအဲပိ၊ ပရိဘောဂံၚ်။ လဝ်ပ္ဍဲဒဵုရ၊ သိၚ်ဃုတ္တရံၚ်။ ဓါတ်အဲလၟုဟ်၊ ဒၞာဲဝွံထပ်ပံၚ်။” (ကျာ်တြဲဂေါတမဂး။) (လိက်တပူတဗဝ်။ အစွောံ) = “ရဟန္တာမင်းမြတ်စွာဘုရားသည် တစ်နည်းမှာကြားတော်မူ၏။ ငါ၏ဘုရားနောင်တော်သုံးဆူတို့၏ ဓါတ်တော်နှင့်အသုံးအဆောင်တော်များကို သိၚ်ဃုတ္တရတောင်­ထားရှိ၏။ ငါ၏ဓါတ်တော်ကိုလည်း ဤနေရာ­ ထပ်ပေါင်း၍ထားပါ။”')
,(12822,3,1,'၂။ အဆွေခင်ပွန်း။မိတ်ဆွေ။','“ညးၜါဂှ်ပြဲ၊ ဒှ်ဒၟံၚ်လဲဇွာ။ ညးဗၠာဲအဲဗၠာဲ၊ ကြဴတဲသြာဲအာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) (လဲ = ဇွာ) = “နှစ်ဦးသားတို့သည် အဆွေခင်ပွန်းဖြစ်ကုန်၏၊ နှစ်ဦးစလုံးသည် လူပျိုဖြစ်ကြပြီး နောက်အဖို့­ ဝေးကွာသွားကြကုန်၏။” || “ယဝ်မတီဂုန်၊ ဂုန်ဓဝ်မပြဲ။ ပ္ကတ်ကဵုညိလဲ၊ အဲဂွံဗၠးချိုတ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “မြတ်သောတရား၏ဂုဏ်ကျေးဇူးတော်ကို သၚ်သိပါက ငါ့ကို သင်ကြားပေးပါ အိုအဆွေ။” || “မၞိဟ်ဇၞော်ကွာန်ၜါ၊ ညဳသာထဒၟ။ နူကဵုဍောတ်မွဲ၊ ဒှ်လဲသဟ။ ဆာန်ရေၚ်သ္ကံလောန်၊ သၟဟ်ကောန်မွဲမ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ရွာသူကြီးနှစ်ဦးတို့သည် ညီညွတ်လေးစားကြကုန်၏၊ ငယ်စဉ်ကတည်းက အဆွေခင်ပွန်းဖြစ်ကုန်၍ တစ်ဖတည်းသားပမာ အလွန်ချစ်ခင်ကြကုန်၏။”')
,(12823,3,4,'လိမ့်သည်။','‘လောစှ်ေအာနူလ္တူသ္ၚိ။’ = ‘အိမ်ပေါ်မှလိမ့်ကျသွားသည်။’')
,(12824,3,10,'(န) လောက။',NULL)
,(12825,3,11,'(န) စကြာဝဠာ။ ကမ္ဘာလောက။ လောကဓါတ်။ (ပါဠိ—လောကဓါတု)','“စှ်လ္ၚီလောကဓါတ်။” = “စကြာဝဠာတိုက်တစ်သောင်း။”')
,(12826,3,1,'အရှေ့လောကဓါတ်။ အရှေ့စကြာဝဠာ။','“ပါစိဏလောကဓါတ် အဝေါန်ဗၞဳစက်ဂိတုပုဏ္ဏမဳဂတဝ်တိုန်။” (ဇ—၄၈။ အစွောံ) = “အရှေ့လောကဓါတ်မှ ပြည့်သောလဝန်းသည် တက်၏။” (ညောင်ကန်) || “ညံၚ်ရဴသၟိၚ်တ္ၚဲဂှ်ကီုရ တိုန်ပျးကဵုညး နူဒိုဟ်ဗၟံက်လောကဓါတ်တုဲ ရဴမဒးစှ်ေပၠိုတ်အာ ဗွဲဒိုဟ်ပလိုတ်ပၠန်ကီု။” (ဇ—၃၅၁။ အစွောံ။) = “နေမင်းကဲ့သို့ အရှေ့စကြာဝဠာမှတက်ကာ သတ္တဝါအပေါင်းအား အလင်းရောင်ပေးပြီးလျှင် အနောက်အရပ်ဖြင့်ဆင်း၍ ကွယ်သွားရပြန်၏။” || ပညာလောကဓါတ် = လောကဓါတ်ပညာ။ သိပ္ပံပညာ။')
,(12827,3,16,'(န) လောကဓံတရား။ အဆိုးနှင့်အကောင်း အပြောင်းအလဲ ဖြစ်လေ့ရှိသောတရား။','လောကဓဝ်ဒစာံပြကာ = လောကဓံတရားရှစ်ပါး။ (၁၊ လာဘော — လာဘ်ရခြင်း။ ၂၊ အလာဘော — လာဘ်မရခြင်း။ ၃၊ ယသော — အခြွေအရံများခြင်း။ ၄၊ အယသော— အခြွေအရံနည်းခြင်း။ ၅၊ နိန္ဒာ — ကဲ့ရဲ့ခံရခြင်း။ ၆၊ ပသံသာ — ချီးမွမ်းခံရခြင်း။ ၇၊ သုခံ— ချမ်းသာခြင်း။ ၈၊ ဒုက္ခံ — ဆင်းရဲခြင်း။) || “ပရိုက်လောကဓဝ်ဒစာံပြကာမ္ဂး — အဲတီဒၟံၚ်တုဲရ။” (ဇ—၃၅၁။ အစွောံ။) = “ရှစ်ပါးသောလောကဓံတရား၏ဒဏ်ကို ငါသိပြီးလေပြီ။” || “လောကဓဝ်ဗျာံ၊ ဒစာံပြကာ။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “ရှစ်ပါးသောလောကဓံတရား။”')
,(12828,3,10,'(န) လူတို့၏အကျိုးစီးပွားကို ညွှန်ပြသောနီတိကျမ်း။ လောကနီတိ။',NULL)
,(12829,3,10,'(န) လောကကိုစောင့်ရှောက်သော အရှက်နှင့်အကြောက်တရားနှစ်ပါး။ လောကပါလတရား။',NULL)
,(12830,3,10,'(န) လူတို့ခေါ်ဝေါ်သုံးစွဲသောစကား။ လောကဝေါဟာရ။',NULL)
,(12831,3,11,'(န) လူအချင်းချင်း ဆက်ဆံရာတွင် စောင့်စည်းလိုက်နာအပ်သောတရား။လောကဝတ်။','“ရာဇာဝတ်ကောံ၊ ဓမ္မဝတ်ဇဳ။ လောကဝတ်စိ၊ ဝတ်ပိသၟဟ်ညဳ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ရာဇဝတ်၊ ဓမ္မဝတ်၊ လောကဝတ်ဟူသော ဝတ္တရားသုံးပါးနှင့် ပြည့်စုံညီညွတ်သည်။”')
,(12832,3,12,'(န) လောကသျှတ္တရကျမ်း။ လောကအကြောင်းရပ်ကို ရှင်းလင်းဖွင့်ဆိုသောကျမ်း။','“ယဝ်ညးမွဲကောံ၊ မၞုံဒုဟ်ပါပ။ အန္တရာဲဂှ်၊ ယဝ်က္တဵုဒှ်ရ။ မိက်ဆေဒနာ၊ ပၠေၚ်ဒုဟ်ပါပ။ ပ္ဍဲပြကိုဟ်ရော၊ လောကသာတ်တြ။ ပြာ်ဂြိုဟ်ဆက်ဒဲ၊ ပၠေၚ်သၞဲပါပ။” (လိက်ပဒုမဝတဳ) = “မကောင်းသောပါပအပြစ်ရှိသောသူသည် အကယ်၍အန္တရာယ်ဖြစ်ပေါ်ပါကထိုမကောင်းသောပါပအပြစ်ကို တားဆီးကျိန်းကျေစေလိုသော် လောကသျှတ္တရကျမ်း­လာသောဂြိုဟ်အစီအမံအတိုင်း ကျိန်းကျေအောင်ပြုပါလေ။”')
,(12833,3,10,'(န) လောကရေးရာ။ လောကီ။',NULL)
,(12834,3,11,'(န) လောကမှလွန်မြောက်ကြောင်း ဖြစ်သောတရား။လောကုတ္တရာ။',NULL)
,(12835,3,11,'(န) စကြာဝဠာသုံးခုအကြားတွင် တည်ရှိသောငရဲ။ လောကန္တရိက်။',NULL)
,(12836,3,1,'လိမ့်သည်။ လိမ့်လျက်ရွေ့သွားသည်။','“(သၟိၚ်ကုသတုန်) ညံၚ်ဇိုၚ်မတဆူလောတ်အာဂှ်ပတုဲ ထမာဲပုၚ်သွ (မဂၠေၚ်နၚ်) တံဂှ် လောတၟဝ်အာ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ခြေချော်လဲသကဲ့သို့ပြု၍ ထမ်းလာသောထမင်းဟင်းအိုးတို့သည် ကျ၍လိမ့်ကုန်၏။” || “ဒဂဵုဆုဂှ် လောတမဝ်အာတုဲ ဗက်ထဍေၚ်လကိုဟ်တံဂှ်ရ။” (သၠပတ်ရာဇာသာန်) = “ထိုသစ်ၚုတ်သည် လိမ့်၍ရွေ့လျားကာ ထိုဘီလူးတို့အား ပြေးလိုက်၏။” || ‘လောတ်တမဝ်’ လည်းရှု။')
,(12837,3,4,'လူးလိမ့်သည်။ အလူးလူးအလိမ့်လိမ့်ဖြစ်သည်။','“(ကုကၞုဟ်ဂှ်) ထောံဖျေံပ္ဍဲကြုၚ်ဂှ်တုဲ ဒးလောဗတောဒၟံၚ်ရ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “ထိုလိပ်အား မြစ်ထဲသို့ပစ်ချလိုက်လျှင် ထိုလိပ်သည် အလူးလူးအလိမ့်လိမ့်ဖြစ်နေရလတ္တံ့။”')
,(12838,3,10,'(န) လောဘ။ လိုချင်မက်မောခြင်း။',NULL)
,(12838,3,10,'(ကြိ) လောဘကြီးသည်။ လောဘရှိသည်။','‘လ္ပလောဘညိ။’ = ‘လောဘမကြီးပါနှင့်။’ || “(သၟိၚ်ဂှ်) လောဘကဵုဒြပ်လောန်။” (ဇ—၂၂၈။ အစွောံ။) = “ထိုမင်းသည် ဥစ္စာတို့­ လောဘကြီး၏။”')
,(12839,3,4,'လောဘကြီးသည်။',NULL)
,(12840,3,10,'(န) မိမိအတွက်သာကြည့်သော လွန်ကဲသောလောဘ။ လောဘသက္ကာယ။',NULL)
,(12841,3,4,'လူးလဲသည်။ လူးလိမ့်သည်။','“ဗမၞးမွဲ ဂၠေၚ်ကၠုၚ်ထမှာဲပုၚ် မွဲဒလေၚ်ဂှ် ကောန်သၟိၚ်ဒိဒးတုဲ ထမှာဲပုၚ်ဒတုံစှ်ေပါ်အာတုဲ ဗမၞးယာံလောလိန်တဴရ။” (ဇ—၄၅၆။ အစွောံ။) = “ထမင်းအိုးကို ထမ်း၍လာသော တယောက်သောပုဏ္ဏားကို မင်းသားသည်တိုက်မိ၍ ပုဏ္ဏား၏ထမင်းအိုးသည် ကျကွဲသွားရာ ပုဏ္ဏားသည် လူးလဲ၍ငိုမြည်တမ်း၏။”')
,(12842,3,5,'အစီအစဉ်မကျ။ ဋ္ဌာန်ကရိုဏ်းမကျ။ ကပေါက်ချိကပေါက်ချာ။','“ဟွံကၠိုဟ်ခၠၚ်နဲကဲပိဋကတ်ပိတုဲ ဟီုတွံအာဒၟံၚ်လောလီလောလီ လီၜန်ထုဲထံၚ် ဟွံမွဲကဵုတံဝစနံ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ပိဋကတ်သုံးပုံနည်းနာကို နားမလည်ဘဲ ကပေါက်ချိကပေါက်ချာတရားဟော၍ အစီအစဉ်မကျ ထွေးရောယှက်တၚ်ဖြစ်ကုန်၏။”')
,(12842,3,4,'ပူပန်သည်။ ပူလောင်ခံစားရသည်။','“ပ္ဍဲနရက်ဂၠိုၚ်ကဵုဒဒိုက်လၞီ လောလီပူဆာ—။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) =“ဆင်းရဲဒုက္ခများလှစွာသောငရဲ­ ပူပန်ပူလောင်ခံစားရ၏။”')
,(12843,3,10,'(န) သံ။ ကြေး။ သတ္တု။',NULL)
,(12844,3,10,'(န) လောဟကုမ္ဘိငရဲ။',NULL)
,(12845,3,10,'(နဝိ) နီသော။',NULL)
,(12846,3,1,'၁။ မြား။',NULL)
,(12846,3,1,'၂။ လောလူမျိုး။ လားအိုလူမျိုး။',NULL)
,(12846,3,4,'ပြောပြသည်။','လဴပုံ = ပုံပြောသည်။ || “သမ္တီလဝ်သွံ၊ သ္ဂောံလဴဆက်အာ။” (လိက်ဇိဝှစက္က) = “မှတ်သားထားပါက ဆက်၍ပြောပြသွားနိုင်မည်။”')
,(12847,3,4,'(စစ်ထိုးရာတွင်) မဆုတ်မနစ် ရှေ့တိုးသည်။ ရှေ့တက်သည်။',NULL)
,(12848,3,4,'အားထုတ်၍ ရှေ့တိုးချီတက်သည်။','“ယွံမၞးတံ၊ ဗဵုပၞာန်ဂမၠိုၚ် ပ္ဍဲမစၞေဟ်ဝွံ မၞးတံပ္တိတ်ဒြဟတ်သၟတ်စၞေဟ်ညိ။ ပ္ဍဲပၞာန်စိၚ်တုန်လေဝ် သြဝ်လဴပ္တိုန်ညိ။ ပၞာန်ချေံလေဝ် သြဝ်လဴပ္တိုန်ညိ။ပ္ဍဲပၞာန်ကွဳတုန်လေဝ် သြဝ်လဴပ္တိုန်ညိ။—” သၟိၚ်ဂး။ (ဇ—၂၂၉။ အစွောံ။) = “အချင်းတို့၊ စစ်သည်ဗိုလ်ပါးများဖြင့် စစ်ထိုးရာတွင် သင်တို့သည် အထူးအားထုတ်၍ စစ်ထိုးကြကုန်လော့။ ဆင်တပ်တို့ကိုလည်း ရှေ့တိုးချီတက်နှင်ကုန်လော့။ မြင်းတပ်တို့ကိုလည်း ရှေ့တိုးချီတက်နှင်ကုန်လော့။ ရထားတပ်တို့ကိုလည်း ရှေ့တိုးချီတက်နှင်ကုန်လော့။”')
,(12849,3,4,'(စစ်ထိုးရာတွင်) အရှိန်အဟုန်ဖြင့် ရှေးရှုဝင်သည်။','“သၟိၚ်သာမန္တရးဗပါ်ကၠေံဍုၚ်ညးတုဲ တၞဟ်နရပ်ကေတ်သၟိၚ်သတြုဂှ် လဴလောပ်စိၚ်ရ။” (ဇ—၁၈၂။ အစွောံ။) =“သာမန္တမင်းသည် ဗာရာဏသီမြို့ကိုဖြို၍ ရန်သူမင်းကိုဖမ်းအံ့ဟု ဆင်ကိုနှင်၍ အရှိန်ဖြင့်ရှေးရှုဝၚ်၏။”')
,(12850,3,1,'ပြောပြသည်။ တိုၚ်တန်းသည်။','“ဒဒှ်ဍေံဒြေပ်ဘာ အဲလဴဗစကဵုအ္စာရ။” = “သူကျောင်းပြေးကြောင်းကို ဆရာ့ကို ကျွန်တော်တိုၚ်တန်းသည်။” || “(ပရိုၚ်ဒဒှ်အိုဿီုဂှ်) တ္ၚေက်သုဝဟီုလဴဗ္စ ကုဗောဓိသတ်အိုတ်ရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “အလုံးစုံသောသတင်းကိုကျေးသားသည် ဘုရားလောင်းအား အားလုံးပြောပြ၏။”')
,(12851,3,4,'စေ့ဆော်သည်။ တိုက်တွန်းသည်။','“ဗောဓိသတ် (သၟိၚ်စိၚ်) မိၚ်ဗရုယဝံါလၟ မဇၞော်ကဵုဒြဟတ် ‘အဲဗလးဒဒိုက်ပူဂဵုဝွံညိ’ ကရုဏာဟိုတ်လဴစိုတ်တုဲ ပြာပ်ကၠုၚ်ဇရေၚ်လၟရ။” (ဇ—၇၂။ အစွောံ။) = “ဘုရားလောင်းဆင်မင်းသည် ထိုမူဆိုး၏သည်းစွာသော ငိုကြွေးသံကိုကြား၍ ‘ဤယောကျာ်းကို ဆင်းရဲမှလွတ်စေအံ့’ ဟု ကရုဏာသည် တိုက်တွန်းအပ်သည်ဖြစ်၍ ထိုမူဆိုး၏အထံသို့ သွား၏။” (ညောင်ကန်) || “ဒေဝတဴတံ ဟိုတ်လဴစိုတ် ဨကရာတ်ကဵုသၟာန်တိုန် သၟိၚ်အမာတ်မွဲ။” (သၠပတ်ရာဇာသာန်) = “နတ်တို့စေ့ဆော်သောကြောင့် ဘုရင်သည် အမတ်တစ်ဦးအား မေးလိုက်၏။”')
,(12852,3,4,'သုတ်ခြေတၚ်သည်။','“ဖေက်တုဲဒြေပ်ဒဴ၊ လဴဇိုၚ်ဂစာန်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ကြောက်၍ထွက်ပြေးကာ သုတ်ခြေတၚ်ကြိုးစား၏။”')
,(12853,3,5,'လောလောလတ်လတ်။ ချက်ချင်းလက်ၚင်း။','“တိတ်ညာတ်ကောန်သ္တိုတ်၊ ကောန်ချိုတ်လဴလဴ။ မူဒှ်ချိုတ်သၟတ်၊ သၟာန်စံၜတ်တဴ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လောလောလတ်လတ်သေသောသားကို ထွက်၍မြင်လေလော် အဘယ်ကြောင့်သေသနည်းဟု မေးမြန်းစုံစမ်း၏။” || “ဖျိုက်စိုတ်ညးသွံ၊ ဂွံသိုက်လဴလဴ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “သူတစ်ပါးအားစိတ်ချမ်းသာအောင်ပြုသဖြင့် (မိမိသည်လည်း) ချမ်းသာကို ချက်ချင်းလက်ၚင်းရ၏။”')
,(12854,3,4,'၁။ ခင်းသည်။','လးဖုန် = အိပ်ရာခင်းသည်။ || လးယာတ် = အဝတ်ခင်းသည်။')
,(12854,3,4,'၂။ ပြန့်သည်။','“တိဂှ် ကုန်ဒဵုဟွံမွဲ လးဒၟံၚ်ရ။” = “ထိုမြေသည် တောင်ကုန်းများမရှိဘဲ မြေပြန့် ဖြစ်သည်။”')
,(12855,3,4,'ပက်လက်အိပ်သည်။ ကျောခင်းသည်။','“လးစးလတူဒကဝ်တုဲ တိက်ဒၟံၚ်ရ။” =“ဖျာပေါ်တွင် ကျောခင်း၍ အိပ်နေသည်။”')
,(12856,3,4,'ခင်းသည်။','“(ခမဳကောကာလိကဂှ် တၞဟ်နတွံဓဝ်) တိုန်လတူသၞာဓဝ် ညးမလးပ္ညပ်လဝ်ဂှ်တုဲ—။” (ဇ—၁၇၂။ အစွောံ။) = “(ကောကာလိကမည်သောရဟန်းသည် တရားဟောရန်အလို့ငှာ) ခင်းအပ်သော ဓမ္မကထိကတို့၏ နေရာသို့တက်၍—။” (ညောင်ကန်) || “ပ္ဍဲဒေန်ကျာ်သြဳ မလးပ္ညပ်လဝ်ဂှ် (ဂၞကျာ်သတိက်ဒၟံၚ်ရ။)” (ဇ—၂၅၁။ အစွောံ။) = “(မိဖုယားသည်) ညောင်စောင်းငယ်ကိုခင်း၍ (အိပ်နေ၏။)” (ညောင်ကန်) || “ပ္ဍဲသၞာညးမလးပ္ညပ်လဝ်ဂှ် ကျာ်တြဲဂ္ဇံဒၟံၚ်တုဲ—။” (ဇ—၃၂၈။ အစွောံ။) = “(မြတ်စွာဘုရားသည်) ခင်းအပ်သောနေရာ­ နေတော်မူ၍—။” (ညောင်ကန်)')
,(12857,3,5,'လုံးဝ။ အလျှင်း။','“အဲမံၚ်ဟွံမာန်လးလးရကောန်။” (ဇ—ဘူရိဒတ်။ အစွောံ။) =“ချစ်သား၊ ငါလုံးဝမနေနိုင်တော့ပါ။” || “ဟွံဟီုလးလး၊ ရောဒးပြဝ။” (လိက်သုပိဏ္ဏကုမ္မာ။မၚ်သၚ်ကြာ။) = “လုံးဝမပြောပြန်လျှင်လည်း မလျောက်ပတ်။”')
,(12858,3,4,'(ချစ်သူနှင့်အတူ) မွေ့လျော်သည်။ သာယာကြည်နူးသည်။','“ညံၚ်ဗီုဆဒ္ဒန်၊ ဇၟူကုဥ္ဇရ။ မဂွံနိသြဲ၊ ဇြဲနိဂြောဓ။ မဂွံဒ္ၚောဝ်မိတ်၊ သၟဟ်ကဵုစိတ္တ။ လးလေၚ်သာဓါ၊ ဂွံသံၚ်ဝါသ။” (လိက်မေဃသန်) = “ဆဒ္ဒန်ဆင်ပြောင်ကဲ့သို့ ပညောင်ပင်ရိပ်ကိုမှီ၍ စိတ်အလိုကျဖြစ်သော ချစ်သူသက်လျာနှင့် ဖူးတွေ့ခွင့်ရ၍ အတူတကွ မွေ့လျော်ပေါင်းဖက် ဆက်ဆံပျော်ပါးရပေတော့မည်။” || “ရေၚ်ကာန်ဆာန်ကၟိန်၊ စိန်ဝုန်လးလေၚ်။” (လိက်မာဃဒေဝါန်) = “ပေါင်းဖက်ချစ်ကြင်နာ၍ အတူမွေ့လျော်ပျော်ရွှင်၏။” || “ယဝ်ဒါန်ဟွံမွဲ၊ ပ္ဍဲဘဴတမၠာ။ စးကဵုစးဗ္ဒာဲ၊ ဒလာဲလဝ်ကၠာ။ ဟွံဂွံလးလေၚ်၊ ရောၚ်ဟွံသေၚ်ဟာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ရှေးဘဝကရေစက်မရှိပါက ကျောချင်းကပ်၍ မှီထားကြလင့်ကစား အတူမမွေ့လျော်ကြရသည် မဟုတ်လော။” || ‘လၚ်လး’ နှင့်အတူတူ။')
,(12859,3,16,'(ပါသက်) (ဂဏန်း) တစ်သောင်း။ (ယနေ့ခေတ်သုံး)','တစ်သိန်း။ (ခေတ်ဟောင်းသုံး) || ပန်အသၚ်ဃဲကဵုပရဲမွဲမှာလက်ကဝ် = လေးအသင်္ချေနှင့်ကမ္ဘာတစ်သိန်း။ || “ကွာန်ဇၞော်မွဲဂှ် မၞုံကၠေဝ်ဍေံ မွဲမွဲသၞာံထဝ်မွဲလက်ဂှ် (သၟိၚ်) ဇိုန်ကဵုသၟာဂလုံတုဲ—။” (ဇ—၉။ အစွောံ။) =“(မင်းသည်) ဆတ္တာသည်အား (တနှစ်လျှင်) အခွန်တစ်သိန်းထွက်သောရွာကို ဆုပေး၍—။” (ညောင်ကန်) || “ဗောဓိသတ် (ညးဗၞိက်လီု) ညာတ်တုဲ တီဒဒှ်ထးထဝ်တုဲ ‘ထးဝွံ ၚုဟ်မွဲလက်ဟေၚ်၊ဗၞိက်မတန်ကဵုထးဟွံမွဲ’ ဗောဓိသတ်ဂး။” (ဇ—၃။ အစွောံ။) = “ထိုဘုရားလောင်းကုန်သည်သည်ထိုခွက်၏ရွှေခွက်၏အဖြစ်ကိုသိ၍ ‘အမိ၊ ဤခွက်သည် အဘိုးတသိန်းထိုက်၏။ အဘိုးတသိန်းထိုက်သောဥစ္စာသည် ငါ၏လက်­မရှိ’ ဟုဆို၏။” (ညောင်ကန်)')
